local config = {
  ui_story_5004_50040101_1_dialog_content = "PlayerName!",
  ui_story_5004_50040101_2_dialog_content = "Mundur, PlayerName!",
  ui_story_5004_50040101_3_dialog_content = "(Gelombang gelombang besar hampir menjatuhkan saya.)",
  ui_story_5004_50040101_4_dialog_content = "(Garis kilat ungu dan merah menyala di langit yang gelap dan mendung. Deru guntur bergema di telingaku.)",
  ui_story_5004_50040101_5_dialog_content = "(Saya menatap meteorit yang tak terhitung jumlahnya menabrak kami dari atas.)",
  ui_story_5004_50040101_6_dialog_content = "(Kastil hitam yang tidak menyenangkan terus naik perlahan dari kedalaman lautan, membawa serta perasaan melankolis.)",
  ui_story_5004_50040101_7_dialog_content = "(Vice dan Carleen ada di depan, mencoba melindungiku dengan sia-sia...)",
  ui_story_5004_50040101_8_dialog_content = "(Sudah terlambat.)",
  ui_story_5004_50040101_9_dialog_content = "(Tidak pernah berpikir bahwa saya akan bertanggung jawab atas malapetaka dan kehancuran yang akan datang ...)",
  ui_story_5004_50040101_10_dialog_content = "Lalu aku akan meninggalkannya dalam perawatanmu. Pamitan.",
  ui_story_5004_50040101_11_dialog_content = "Tunggu, Anda tidak bisa tiba-tiba muncul dengan seorang gadis dan mengharapkan saya untuk merawatnya tanpa pemberitahuan!",
  ui_story_5004_50040101_12_dialog_content = "Aku bahkan tidak tahu namanya!",
  ui_story_5004_50040101_13_dialog_content = "...",
  ui_story_5004_50040101_14_dialog_content = "Hai...",
  ui_story_5004_50040101_15_dialog_content = "Nama saya adalah...",
  ui_story_5004_50040101_16_dialog_content = "Namanya adalah <color=#FFB400>Beril</color>. Sekarang setelah Anda berkenalan, saya akan pergi.",
  ui_story_5004_50040101_17_dialog_content = "Tahan di sana! Itu tidak cukup informasi!",
  ui_story_5004_50040101_18_dialog_content = "Nah jika Anda bersikeras, PlayerName, dengan senang hati saya akan mencerahkan Anda dengan Kebenaran...",
  ui_story_5004_50040101_19_dialog_content = "Jangan ganti topik! Sebelumnya, bukankah kamu mengatakan dia ...",
  ui_story_5004_50040101_20_dialog_content = "...",
  ui_story_5004_50040101_21_dialog_content = "Maksudku Beryl, kamu bilang dia <color=#FFB400>Saya akan</color>? Jenis penyakit apa?",
  ui_story_5004_50040101_22_dialog_content = "Aku tidak yakin.",
  ui_story_5004_50040101_23_dialog_content = "Apa?",
  ui_story_5004_50040101_24_dialog_content = "Saya meninggalkan dia dalam perawatan Anda karena saya tidak tahu.",
  ui_story_5004_50040101_25_dialog_content = "Anda adalah seorang Caelestite dengan kemampuan psikis, dikelilingi oleh Aurorian berpengalaman dalam penyembuhan Luminatics.",
  ui_story_5004_50040101_26_dialog_content = "Lady Victoria dan aku sama-sama setuju bahwa akan lebih baik bagimu untuk menjaganya.",
  ui_story_5004_50040101_27_dialog_content = "Kapan Orde Sejati menjadi amal?",
  ui_story_5004_50040101_28_dialog_content = "...",
  ui_story_5004_50040101_29_dialog_content = "Tunggu, Faust, mari kita coba cara lain.",
  ui_story_5004_50040101_30_dialog_content = "Maksudku...",
  ui_story_5004_50040101_31_dialog_content = "Apakah dia...",
  ui_story_5004_50040101_32_option_content = "Putri Lady Victoria?",
  ui_story_5004_50040101_33_dialog_content = "No Lady Victoria didedikasikan semata-mata untuk mengejar Kebenaran. Dia tidak memiliki keinginan duniawi seperti itu.",
  ui_story_5004_50040101_34_option_content = "Apakah Anda menawarkan Beryl sebagai pengorbanan untuk salah satu ritual menyeramkan Anda?!",
  ui_story_5004_50040101_35_dialog_content = "Tentu saja tidak. Tolong jangan memfitnah pencarian kami akan Kebenaran.",
  ui_story_5004_50040101_36_dialog_content = "Juga, Beryl adalah anggota penting dari True Order.",
  ui_story_5004_50040101_37_dialog_content = "Hmm…",
  ui_story_5004_50040101_38_dialog_content = "Oke, selama tidak ada yang mencurigakan terjadi...",
  ui_story_5004_50040101_39_dialog_content = "Meskipun aku masih tidak mengerti mengapa Lady Victoria memilihku.",
  ui_story_5004_50040101_40_dialog_content = "Tidak perlu mencoba memahami keputusannya.",
  ui_story_5004_50040101_41_dialog_content = "Kami semakin dekat dengan Kebenaran dengan mengikuti dan melaksanakan perintahnya.",
  ui_story_5004_50040101_42_dialog_content = "(Itu hanya membuatku semakin curiga...)",
  ui_story_5004_50040101_43_dialog_content = "Nah, karena Raphael kebetulan berada di Colossus sekarang, sebaiknya kunjungi dia.",
  ui_story_5004_50040101_44_dialog_content = "<color=#e8d9bb>Beberapa menit kemudian...</color>",
  ui_story_5004_50040101_45_dialog_content = "Bersenandung...",
  ui_story_5004_50040101_46_dialog_content = "Hmm... Ahh...",
  ui_story_5004_50040101_47_dialog_content = "Bagaimana?",
  ui_story_5004_50040101_48_dialog_content = "Setelah mencoba segalanya, saya masih tidak tahu apa yang salah dengannya.",
  ui_story_5004_50040101_49_dialog_content = "Namamu Beryl, kan?",
  ui_story_5004_50040101_50_dialog_content = "Ya.",
  ui_story_5004_50040101_51_dialog_content = "Jadi, Beryl, apa kau merasakan sakit di mana saja?",
  ui_story_5004_50040101_52_dialog_content = "Beril...?",
  ui_story_5004_50040101_53_dialog_content = "Maaf, saya lambat memahami bagaimana perasaan tubuh saya.",
  ui_story_5004_50040101_54_dialog_content = "Tapi akhir-akhir ini saya sangat lelah, dan kesulitan mengendalikan Lumina saya...",
  ui_story_5004_50040101_55_dialog_content = "Terkadang saya merasakan sakit yang luar biasa di sekujur tubuh, seperti dimangsa hidup-hidup oleh jutaan serangga.",
  ui_story_5004_50040101_56_dialog_content = "Aku tahu.",
  ui_story_5004_50040101_57_dialog_content = "Ini pertama kalinya saya melihat pasien dengan gejala Anda.",
  ui_story_5004_50040101_58_dialog_content = "Bagaimana menurutmu, PlayerName?",
  ui_story_5004_50040101_59_dialog_content = "(Beryl mengerutkan kening seolah ada sesuatu yang dipikirkannya.)",
  ui_story_5004_50040101_60_option_content = "Mungkin dia tidak senang tentang sesuatu?",
  ui_story_5004_50040101_61_dialog_content = "Itu mungkin!",
  ui_story_5004_50040101_62_dialog_content = "Carleen akan membuat wajah ini setiap kali setelah berdebat dengan Tuan Kota.",
  ui_story_5004_50040101_63_dialog_content = "Sama seperti Beryl sekarang.",
  ui_story_5004_50040101_64_option_content = "Mungkin aku harus mencoba psikis...",
  ui_story_5004_50040101_65_dialog_content = "Tidak! Itu terlalu invasif untuk seorang gadis kecil!",
  ui_story_5004_50040101_66_dialog_content = "Ini seperti memotongnya terbuka untuk menemukan penyebabnya!",
  ui_story_5004_50040101_67_dialog_content = "Bagaimanapun!",
  ui_story_5004_50040101_68_dialog_content = "Apakah masalahnya fisik atau mental, saya mengerti!",
  ui_story_5004_50040101_69_dialog_content = "Jangan khawatir, Beryl, sebagai dokter utama Anda, saya akan mendukung Anda!",
  ui_story_5004_50040101_70_dialog_content = "Saya akan menemukan penyebabnya, lalu membuat Anda kembali normal dalam waktu singkat!",
  ui_story_5004_50040101_71_dialog_content = "Tidak ada waktu... Lebih baik tidak berarti dia tidak punya banyak waktu lagi...",
  ui_story_5004_50040101_72_dialog_content = "PlayerName!",
  ui_story_5004_50040101_X72_dialog_content = "Jangan membuat lelucon seperti itu di depan pasien!",
  ui_story_5004_50040101_73_dialog_content = "Terima kasih.",
  ui_story_5004_50040101_74_dialog_content = "Ada apa?",
  ui_story_5004_50040101_75_dialog_content = "Halo, PlayerName. Ah, halo Rafael. Saya melihat Anda di sini juga.",
  ui_story_5004_50040101_76_dialog_content = "Carleen! Apa yang kamu lakukan di sini?",
  ui_story_5004_50040101_77_dialog_content = "Saya di sini mewakili Lumopolis pada kunjungan resmi reguler, dan mengobrol dengan Vice saat itu.",
  ui_story_5004_50040101_78_dialog_content = "Dan keduanya adalah...?",
  ui_story_5004_50040101_79_dialog_content = "Ini adalah Faust.",
  ui_story_5004_50040101_80_dialog_content = "Selamat siang, nyonya.",
  ui_story_5004_50040101_81_dialog_content = "Apakah kamu bersama? <color=#FFB400>Perintah Sejati</color>?",
  ui_story_5004_50040101_82_dialog_content = "Saya tidak berharap Anda tahu tentang The True Order.",
  ui_story_5004_50040101_83_dialog_content = "Apakah Anda juga seorang pencari Kebenaran?",
  ui_story_5004_50040101_84_dialog_content = "Saya tidak tertarik pada apa yang disebut Kebenaran. Saya memiliki keyakinan saya sendiri.",
  ui_story_5004_50040101_85_dialog_content = "Sayang sekali.",
  ui_story_5004_50040101_86_dialog_content = "Namun, selama Anda mempertimbangkan Kebenaran, Anda selangkah lebih dekat dengan Kebenaran.",
  ui_story_5004_50040101_87_dialog_content = "Mungkin kita akan bertemu di akhir.",
  ui_story_5004_50040101_88_dialog_content = "Betapa acuh tak acuh... Siapa gadis itu, PlayerName?",
  ui_story_5004_50040101_89_dialog_content = "Namanya Beryl. Faust membawanya, tampaknya menjadi temannya.",
  ui_story_5004_50040101_90_dialog_content = "Beryl berada di bawah perawatanku sekarang, Carleen.",
  ui_story_5004_50040101_91_dialog_content = "Saya mengerti. Bagus sekali, Rafael.",
  ui_story_5004_50040101_92_dialog_content = "Jaga pasien dengan baik atas nama White Night.",
  ui_story_5004_50040101_93_dialog_content = "Hee, tentu saja!",
  ui_story_5004_50040101_94_dialog_content = "Tapi kita masih tidak tahu apa yang mengganggu Beryl.",
  ui_story_5004_50040101_X94_dialog_content = "Dugaan kami adalah itu terkait mental atau stres.",
  ui_story_5004_50040101_95_dialog_content = "Anda dapat mengobati penyakit mental juga? Kira Anda lebih dari malaikat tempur yang menembakkan rudal!",
  ui_story_5004_50040101_96_dialog_content = "Jangan meremehkan Malaikat Lumopolis, Vice!",
  ui_story_5004_50040101_97_dialog_content = "(Bagus, sepertinya Raphael cocok dengan Vice!)",
  ui_story_5004_50040101_98_dialog_content = "Ada apa dengan senyum bodoh itu, PlayerName? Oh, aku membawa sesuatu yang luar biasa.",
  ui_story_5004_50040101_99_dialog_content = "Mungkin Anda akan merasa berguna.",
  ui_story_5004_50040101_100_dialog_content = "Ini surat untukmu.",
  ui_story_5004_50040101_101_dialog_content = "Surat untukku?",
  ui_story_5004_50040101_102_dialog_content = "Eho menyerahkannya padaku sebelum kabur. Amplop itu berbunyi, <color=#FFB400>tir' hotel</color>.",
  ui_story_5004_50040101_103_dialog_content = "Tapi anehnya, tidak ada pengirim yang terdaftar.",
  ui_story_5004_50040101_104_dialog_content = "Apakah Anda akan membukanya?",
  ui_story_5004_50040101_105_option_content = "Ini agak mencurigakan. Bagaimana nanti?",
  ui_story_5004_50040101_106_dialog_content = "Jangan malu-malu. Itu akan baik-baik saja!",
  ui_story_5004_50040101_107_dialog_content = "Biarkan saya membukanya untuk Anda!",
  ui_story_5004_50040101_108_dialog_content = "Awas, bisa meledak!",
  ui_story_5004_50040101_109_dialog_content = "Ini hanya kertas di dalamnya, dan kertas yang bagus, dalam matte.",
  ui_story_5004_50040101_110_dialog_content = "Fiuh, tidak ada yang terjadi, syukurlah.",
  ui_story_5004_50040101_111_option_content = "Seharusnya baik-baik saja. Mari kita buka.",
  ui_story_5004_50040101_112_dialog_content = "Buka. Aku juga ingin tahu apa yang ada di dalamnya.",
  ui_story_5004_50040101_113_dialog_content = "Hmm, itu hanya selembar kertas.",
  ui_story_5004_50040101_114_dialog_content = "Itu saja?",
  ui_story_5004_50040101_115_dialog_content = "Apa yang dikatakan, PlayerName?",
  ui_story_5004_50040101_116_dialog_content = "Hmm…",
  ui_story_5004_50040101_117_dialog_content = "Halo, PlayerName,",
  ui_story_5004_50040101_118_dialog_content = "Anda dengan hormat diundang untuk mengunjungi Hotel Tir' untuk berlibur.",
  ui_story_5004_50040101_X118_dialog_content = "Bergabunglah dengan kami yang menarik <color=#FFB400>Penguasa Laut</color> peristiwa.",
  ui_story_5004_50040101_119_dialog_content = "Terlampir adalah undangan yang baik untuk hingga enam teman lain di pesta Anda.",
  ui_story_5004_50040101_120_dialog_content = "Nikmati suite mewah gratis dan semua fasilitasnya!",
  ui_story_5004_50040101_121_dialog_content = "Ini luar biasa! Aku sudah sangat ingin pergi ke pantai!",
  ui_story_5004_50040101_122_dialog_content = "Festival ini seharusnya sangat bermanfaat bagi Beryl!",
  ui_story_5004_50040101_123_dialog_content = "Jika kondisinya memang terkait dengan stres, perjalanan yang menyenangkan mungkin bisa membantu!",
  ui_story_5004_50040101_124_dialog_content = "Ayo pergi ke pantai dengan Beryl, PlayerName, tolong?",
  ui_story_5004_50040101_125_dialog_content = "Tunggu, saya masih memproses ini. Aku bahkan belum pernah mendengar tentang tempat itu...",
  ui_story_5004_50040101_126_dialog_content = "Jangan khawatir, PlayerName, resor ini sebenarnya cukup terkenal.",
  ui_story_5004_50040101_127_dialog_content = "Itu benar, Hotel Tir' telah membuat nama untuk dirinya sendiri di lingkaran bangsawan Lumo. Bahkan saya mendengar sedikit tentang hal itu.",
  ui_story_5004_50040101_128_dialog_content = "Seharusnya, pemilik menjalankan bisnis yang sangat baik.",
  ui_story_5004_50040101_129_dialog_content = "Undangan dan apa yang disebut Ocean Sovereign mungkin dimaksudkan untuk menjadi hype.",
  ui_story_5004_50040101_130_dialog_content = "Tapi kenapa saya diundang?",
  ui_story_5004_50040101_131_dialog_content = "Ini mungkin semacam aksi publisitas.",
  ui_story_5004_50040101_132_dialog_content = "Kebanyakan Aurorian agak ingin tahu tentang Caelestites.",
  ui_story_5004_50040101_133_dialog_content = "Fasilitas, kamar, atau bahkan meja tempat tinggal atau makan seorang Caelestite bisa menjadi skema untuk mempromosikan resor.",
  ui_story_5004_50040101_134_dialog_content = "Itu membuatku terdengar seperti binatang eksotis...",
  ui_story_5004_50040101_135_dialog_content = "...",
  ui_story_5004_50040101_136_dialog_content = "...",
  ui_story_5004_50040101_137_dialog_content = "Bahkan tidak akan membantah itu?",
  ui_story_5004_50040101_138_dialog_content = "Karena ini adalah tempat rekreasi bagi para bangsawan dan ini menguntungkan mereka dan kita...",
  ui_story_5004_50040101_139_dialog_content = "Itu harus benar-benar aman, bukan?",
  ui_story_5004_50040101_140_dialog_content = "Sepertinya ada konsensus.",
  ui_story_5004_50040101_141_dialog_content = "Kamu masih di sini?",
  ui_story_5004_50040101_142_dialog_content = "Saya akan meninggalkan Beryl untuk Anda dan silakan menikmati perjalanan. Pamitan.",
  ui_story_5004_50040101_143_dialog_content = "Faust masih datang dan pergi seperti angin seperti biasanya.",
  ui_story_5004_50040101_144_dialog_content = "Besar! Aku akan melakukan tugasku sebagai dokter dan merawatmu dengan baik, Beryl!",
  ui_story_5004_50040101_145_dialog_content = "Saya hanya tidak berpikir semuanya sesederhana kelihatannya ...",
  ui_story_5004_50040101_146_dialog_content = "Lihat disana! Ada laut!",
  ui_story_5004_50040101_147_dialog_content = "Ini pertama kalinya saya melihat laut, PlayerName.",
  ui_story_5004_50040101_148_dialog_content = "Anda juga, Vice?",
  ui_story_5004_50040101_149_dialog_content = "Saya pikir saya adalah satu-satunya...",
  ui_story_5004_50040101_150_dialog_content = "Tentu saja Anda bukan satu-satunya! Sulit untuk keluar sejauh ini tanpa Colossus.",
  ui_story_5004_50040101_151_dialog_content = "Angin laut sangat bagus. Warna biru yang memikat di mana-mana sangat membantu menenangkan pikiran.",
  ui_story_5004_50040101_152_dialog_content = "Ini seharusnya membuat keajaiban bagi Beryl!",
  ui_story_5004_50040101_153_dialog_content = "Anda terus mengatakan itu untuk Beryl, tetapi Anda sebenarnya ingin bersenang-senang di pantai, ya?",
  ui_story_5004_50040101_154_dialog_content = "Ya, itu salah satu alasannya.",
  ui_story_5004_50040101_155_dialog_content = "Karena bagi sebagian besar Aurorian, pergi ke pantai sangat jarang.",
  ui_story_5004_50040101_156_dialog_content = "Anda mungkin tidak mengerti itu, setelah hidup begitu lama di Colossus.",
  ui_story_5004_50040101_157_dialog_content = "Bagi orang Auroria, liburan pantai sekarang menjadi <color=#FFB400>upacara peralihan</color>!",
  ui_story_5004_50040101_158_dialog_content = "Kenapa bilang begitu?",
  ui_story_5004_50040101_159_dialog_content = "Pikirkan tentang hal ini, banyak Eclipsites sekarang nongkrong di sepanjang pantai.",
  ui_story_5004_50040101_160_dialog_content = "Anda harus siap dengan serangan mereka sambil menikmati matahari dan ombak.",
  ui_story_5004_50040101_161_dialog_content = "Bukankah kombinasi bahaya dan relaksasi itu menantang?",
  ui_story_5004_50040101_162_dialog_content = "Menantang? Kedengarannya sangat berbahaya!",
  ui_story_5004_50040101_163_dialog_content = "Katakanlah saya terkubur di pasir dan Eclipsites muncul.",
  ui_story_5004_50040101_164_dialog_content = "Anda tidak akan meninggalkan saya dan lari, kan, Vice?",
  ui_story_5004_50040101_165_dialog_content = "Bukankah kita berteman? Aku tidak akan melakukan itu!",
  ui_story_5004_50040101_166_dialog_content = "Apapun, matahari ditambah air laut yang sejuk baik untuk pikiran.",
  ui_story_5004_50040101_167_dialog_content = "Beryl pasti bisa dan akan bersantai di sini.",
  ui_story_5004_50040101_168_dialog_content = "Air laut untuk berenang, kan? Tapi kami tidak mengemas apapun <color=#FFB400>baju renang</color>.",
  ui_story_5004_50040101_169_dialog_content = "Anda tidak perlu khawatir tentang itu sedikit pun.",
  ui_story_5004_50040101_170_dialog_content = "Saya tahu resor ini menjual pakaian renang merek mereka sendiri.",
  ui_story_5004_50040101_171_dialog_content = "Pelanggan mereka adalah bangsawan Lumopolis.",
  ui_story_5004_50040101_172_dialog_content = "Mereka bahkan menjual pakaian renang? Itu mencakup semua pangkalan.",
  ui_story_5004_50040101_173_dialog_content = "Tentu saja. Pakaian renang ke pantai seperti baju besi ke medan perang.",
  ui_story_5004_50040101_174_dialog_content = "Apakah itu seorang prajurit Illumina atau bangsawan Lumopolis, pakaian renang adalah suatu keharusan di pantai.",
  ui_story_5004_50040101_175_dialog_content = "Ini hanya etiket pantai!",
  ui_story_5004_50040101_176_dialog_content = "Oh, begitu…",
  ui_story_5004_50040101_177_dialog_content = "(Kenapa berbeda dari apa yang Soroz katakan padaku? Apakah itu benar-benar untuk pakaian renang?)",
  ui_story_5004_50040101_178_dialog_content = "Bagaimana Anda tahu banyak tentang hotel dan pakaian renang, Carleen?",
  ui_story_5004_50040101_179_dialog_content = "Bagaimana itu aneh? Bagaimanapun, aku adalah Kapten Penjaga Lumopolis.",
  ui_story_5004_50040101_180_dialog_content = "Itu bagian dari tugasku untuk mengikuti tren di antara para bangsawan.",
  ui_story_5004_50040101_181_dialog_content = "Pokoknya, nantikan baju renang saya, PlayerName.",
  ui_story_5004_50040101_182_dialog_content = "(Carleen dalam pakaian renang?)",
  ui_story_5004_50040101_183_dialog_content = "Tentu.",
  ui_story_5004_50040101_184_dialog_content = "Kenapa kau terus menatapku seperti itu, PlayerName?",
  ui_story_5004_50040101_185_dialog_content = "Apa aku terlihat aneh?",
  ui_story_5004_50040101_186_dialog_content = "Tidak, tidak sama sekali! Oh, apa lagi yang Anda ketahui tentang resor hotel ini?",
  ui_story_5004_50040101_187_dialog_content = "Saya tahu itu dulu milik seorang bangsawan di Lumopolis.",
  ui_story_5004_50040101_188_dialog_content = "Hingga dijual ke pihak tak dikenal di Umbraton karena bisnisnya gagal.",
  ui_story_5004_50040101_189_dialog_content = "Umbraton sudah menjadi tempat yang membingungkan, jadi sulit untuk memvalidasi informasi itu.",
  ui_story_5004_50040101_190_dialog_content = "Belum lagi pihak tak dikenal yang berusaha menyembunyikan diri.",
  ui_story_5004_50040101_191_dialog_content = "Orang luar bahkan tidak akan merasakannya tanpa sumber lokal yang mahir.",
  ui_story_5004_50040101_192_dialog_content = "Saya mengerti. Umbraton memang tidak bisa ditebak.",
  ui_story_5004_50040101_193_dialog_content = "Ya. Ia berutang semua stabilitas dan harmoni saat ini kepada ...",
  ui_story_5004_50040101_194_dialog_content = "Tunggu, berhenti dengan topik serius!",
  ui_story_5004_50040101_195_dialog_content = "Tujuan kami untuk perjalanan ini adalah untuk membantu Beryl bersantai dan memulihkan diri!",
  ui_story_5004_50040101_196_dialog_content = "Aku baik-baik saja...",
  ui_story_5004_50040101_197_dialog_content = "!!!",
  ui_story_5004_50040101_198_dialog_content = "PlayerName?!",
  ui_story_5004_50040101_199_dialog_content = "Soroz!",
  ui_story_5004_50040101_200_dialog_content = "Gangguan kuat pada sistem uji coba terdeteksi ke arah tujuan, PlayerName.",
  ui_story_5004_50040101_201_dialog_content = "Jika kita teruskan, kita bisa lepas kendali.",
  ui_story_5004_50040101_202_dialog_content = "Aduh…!",
  ui_story_5004_50040101_203_dialog_content = "Beril?",
  ui_story_5004_50040101_204_dialog_content = "Ada apa?",
  ui_story_5004_50040101_205_dialog_content = "Menjauhlah dari tujuan, Soroz, dan segera temukan tempat untuk mendarat!",
  ui_story_5004_50040101_206_dialog_content = "Aku mengerti.",
  ui_story_5004_50040101_207_dialog_content = "Kamu baik-baik saja, Beryl?",
  ui_story_5004_50040101_208_dialog_content = "Ini...",
  ui_story_5004_50040101_209_dialog_content = "Di mana aku?",
  ui_story_5004_50040101_210_dialog_content = "Panasnya api, bau asap, dan tangisan banyak orang Aurora...",
  ui_story_5004_50040101_211_dialog_content = "Tapi aku tidak bisa melihat apapun...",
  ui_story_5004_50040101_212_dialog_content = "Di mana tepatnya aku?",
  ui_story_5004_50040101_213_dialog_content = "PlayerName!",
  ui_story_5004_50040101_214_dialog_content = "PlayerName!!",
  ui_story_5004_50040101_215_dialog_content = "Vice?",
  ui_story_5004_50040101_216_dialog_content = "Kau baik-baik saja, PlayerName?",
  ui_story_5004_50040101_217_dialog_content = "Apa yang terjadi?",
  ui_story_5004_50040101_218_dialog_content = "Anda membeku setelah menabrak Beryl.",
  ui_story_5004_50040101_219_dialog_content = "Apakah Anda merasakan sesuatu?",
  ui_story_5004_50040101_220_dialog_content = "Yeah, tapi itu kabur... Sudahlah. Bagaimana situasi kita saat ini?",
  ui_story_5004_50040101_221_dialog_content = "Kami berada di luar jangkauan gangguan, sekarang saya mencari tempat pendaratan.",
  ui_story_5004_50040101_222_dialog_content = "Kamu baik-baik saja, Beryl?",
  ui_story_5004_50040101_223_dialog_content = "Ya...",
  ui_story_5004_50040101_224_dialog_content = "Apa itu sebenarnya?",
  ui_story_5004_50040201_1_dialog_content = "Apa... kenapa aku harus mengantar kalian? Bukan aku yang menyebabkan Colossus mendarat!",
  ui_story_5004_50040201_2_dialog_content = "Saya hanya berpikir untuk bermain di bar.",
  ui_story_5004_50040201_3_dialog_content = "Apakah resor whatchamacallit itu benar-benar memiliki sistem stereo super mewah?",
  ui_story_5004_50040201_4_dialog_content = "Jika Anda berani berbohong kepada saya ... Saya akan memanggang Anda dengan kekuatan matahari yang terik!",
  ui_story_5004_50040201_5_dialog_content = "Berhenti menggedor atap sebelum aku jatuh!",
  ui_story_5004_50040201_6_dialog_content = "Mereka harus memilikinya...",
  ui_story_5004_50040201_7_dialog_content = "Jika tidak...",
  ui_story_5004_50040201_8_dialog_content = "Saya akan mengganti stereo di Colossus dengan sistem Boom Shakalaka yang Anda inginkan!",
  ui_story_5004_50040201_9_dialog_content = "Pokoknya, tolong fokus mengemudi. Aku masih di atap! Terima kasih.",
  ui_story_5004_50040201_10_dialog_content = "Maaf, PlayerName harus berada di atap mobil.",
  ui_story_5004_50040201_11_dialog_content = "Tidak masalah. Saya baik-baik saja.",
  ui_story_5004_50040201_12_dialog_content = "Itu tidak akan cocok untuk para gadis.",
  ui_story_5004_50040201_13_dialog_content = "Tidak menyangka Anda begitu bijaksana, PlayerName.",
  ui_story_5004_50040201_14_dialog_content = "Jauhkan mata Anda di jalan! Dan tangan Anda, di setir, tolong!",
  ui_story_5004_50040201_15_dialog_content = "Jangan khawatir tentang itu. Setiap anggota Rediesel Wrench dilahirkan untuk mengemudi!",
  ui_story_5004_50040201_16_dialog_content = "Bahkan jika Eclipsite tingkat tinggi muncul, aku akan menjalankannya.",
  ui_story_5004_50040201_17_dialog_content = "Anda sangat beruntung memilikinya <color=#FFB400>Bangsat</color>'s <color=#FFB400>mobil</color> di garasi di sini, atau Anda akan berjalan...",
  ui_story_5004_50040201_18_dialog_content = "Awas!",
  ui_story_5004_50040201_19_dialog_content = "gerhana, Regina!",
  ui_story_5004_50040201_20_dialog_content = "Hah?",
  ui_story_5004_50040201_21_dialog_content = "Aduh! Eclipsites sialan muncul entah dari mana! Pertama kali saya mengemudi dalam dua puluh tahun ...",
  ui_story_5004_50040201_22_dialog_content = "Aahhhhhh!",
  ui_story_5004_50040201_23_dialog_content = "Ugh, pusing sekali... Apakah benturannya membuat Eclipsite terbang?",
  ui_story_5004_50040201_24_dialog_content = "Apakah semua orang baik-baik saja?",
  ui_story_5004_50040201_25_dialog_content = "Ya, hanya goresan.",
  ui_story_5004_50040201_26_dialog_content = "Wooga!",
  ui_story_5004_50040201_27_dialog_content = "Dari mana semua Eclipsites ini berasal? Bersiaplah untuk bertarung!",
  ui_story_5004_50040201_28_dialog_content = "Buru-buru! Senjata ada di bagasi!",
  ui_story_5004_50040201_29_dialog_content = "Kita akan segera dikelilingi!",
  ui_story_5004_50040201_30_dialog_content = "Beryl, bangun, Beryl!",
  ui_story_5004_50040201_31_dialog_content = "Aw...",
  ui_story_5004_50040201_32_dialog_content = "Raphael…",
  ui_story_5004_50040201_33_dialog_content = "Awas!",
  ui_story_5004_50040201_34_dialog_content = "…!",
  ui_story_5004_50040201_35_dialog_content = "Kristal...",
  ui_story_5004_50040201_36_dialog_content = "Ahh...",
  ui_story_5004_50040201_37_dialog_content = "Gan!! Gan!!!",
  ui_story_5004_50040201_38_dialog_content = "Mereka menabrak mobil untuk terbalik!",
  ui_story_5004_50040201_39_dialog_content = "Mekarlah!",
  ui_story_5004_50040201_40_dialog_content = "Grr...",
  ui_story_5004_50040201_41_dialog_content = "Wow, itu pekerjaan yang cepat!",
  ui_story_5004_50040201_42_dialog_content = "Tidak menyangka kamu begitu kuat... Kurasa The True Order bukanlah sesuatu yang bisa disindir.",
  ui_story_5004_50040201_43_dialog_content = "Jumlah kristal yang dilepaskan dan Eclipsites dikalahkan dalam sekejap mata, menyaingi kekuatan Malaikat Lumopolis.",
  ui_story_5004_50040201_44_dialog_content = "Benar.",
  ui_story_5004_50040201_45_dialog_content = "Itu luar biasa... Oh, terima kasih, Beryl!",
  ui_story_5004_50040201_46_dialog_content = "Huft, huft...",
  ui_story_5004_50040201_47_dialog_content = "Kamu baik-baik saja, Beryl?",
  ui_story_5004_50040201_48_dialog_content = "Apakah kalian sudah selesai berbicara? Ambil senjata Anda, lebih banyak Eclipsites akan datang!",
  ui_story_5004_50040301_1_dialog_content = "Wah, hampir sampai. Saya tidak pernah ingin mengemudi lagi.",
  ui_story_5004_50040301_2_dialog_content = "Terima kasih telah mengantarkan kami dalam keadaan utuh.",
  ui_story_5004_50040301_3_dialog_content = "Berhentilah menggoda dan cari tempat untuk parkir.",
  ui_story_5004_50040301_4_dialog_content = "Hei, apa yang kalian lakukan di sini?",
  ui_story_5004_50040301_5_dialog_content = "Hei... Kenapa kap mobilku penyok?",
  ui_story_5004_50040301_6_dialog_content = "Bahkan jika kita berteman, PlayerName, sebaiknya kau ceritakan padaku apa yang terjadi!",
  ui_story_5004_50040301_7_option_content = "Sebenarnya, Regina ingin membawa mobil keluar untuk berputar...",
  ui_story_5004_50040301_8_dialog_content = "Usaha yang bagus. Dia tidak akan mengemudi bahkan jika dia ingin pergi berkeliling.",
  ui_story_5004_50040301_9_dialog_content = "Apa yang Anda miliki padanya?",
  ui_story_5004_50040301_10_dialog_content = "Hai! Apakah saya terlihat seperti seseorang yang menyembunyikan sesuatu?",
  ui_story_5004_50040301_11_dialog_content = "Jadi PlayerName setuju untuk meningkatkan sistem stereo untuk Anda?",
  ui_story_5004_50040301_12_dialog_content = "Saya tidak percaya Brock, Anda dapat menebaknya!",
  ui_story_5004_50040301_13_dialog_content = "Mengapa tidak? Saya tidak bodoh! Saya langsung melihatnya!",
  ui_story_5004_50040301_14_option_content = "Saya memperbaiki mobil dan memutuskan untuk menjalankannya khusus untuk Anda!",
  ui_story_5004_50040301_15_dialog_content = "Betulkah? Apakah saya memberi tahu Anda bahwa saya akan berada di sini?",
  ui_story_5004_50040301_16_dialog_content = "Saya menggunakan kemampuan psikis. Ya, psikis.",
  ui_story_5004_50040301_17_dialog_content = "sejauh ini? Menakjubkan!",
  ui_story_5004_50040301_18_dialog_content = "Penyok di kap mesin berbentuk seperti Eclipsite...",
  ui_story_5004_50040301_19_dialog_content = "Kau bisa beritahu?",
  ui_story_5004_50040301_20_dialog_content = "Jangan meremehkan saya. Saya menabrak lebih dari beberapa ratus Eclipsites setahun.",
  ui_story_5004_50040301_21_dialog_content = "Saya hafal bentuknya! Apakah Anda menabrak Linebreaker?",
  ui_story_5004_50040301_22_dialog_content = "Anda bahkan tahu jenisnya? Ups, maaf, saya akan memperbaikinya untuk Anda nanti.",
  ui_story_5004_50040301_23_dialog_content = "Jangan terlalu khawatir, Anda baru saja menambahkan satu lagi ke jumlah pembunuhan bayi saya.",
  ui_story_5004_50040301_24_dialog_content = "Saya hanya akan memiliki teman saya yang <color=#FFB400>montir</color> memperbaikinya.",
  ui_story_5004_50040301_25_dialog_content = "Lagi pula, untuk apa kamu datang ke sini, liburan?",
  ui_story_5004_50040301_26_dialog_content = "Ya! PlayerName mendapat undangan dari Tir' Hotel, semua biaya dibayar!",
  ui_story_5004_50040301_27_dialog_content = "Apa? Itu tidak biasa. Saya tidak tahu pemilik hotel bisa begitu murah hati.",
  ui_story_5004_50040301_28_dialog_content = "Mungkin pemiliknya memanfaatkan status Caelestite PlayerName untuk tujuan promosi.",
  ui_story_5004_50040301_29_dialog_content = "Hmm, itu lebih mungkin.",
  ui_story_5004_50040301_X29_dialog_content = "Kamu rupanya!",
  ui_story_5004_50040301_30_dialog_content = "Anda adalah penjahat Rediesel Wrench yang keluar dari penjara...",
  ui_story_5004_50040301_31_dialog_content = "Tunggu! Kami sedang dalam perjalanan untuk Beryl, bukan menangkap penjahat!",
  ui_story_5004_50040301_32_dialog_content = "Lagi pula, kita tidak di Lumopolis, tidak perlu ribut!",
  ui_story_5004_50040301_33_dialog_content = "Ya sudah.",
  ui_story_5004_50040301_34_dialog_content = "Tetapi jika Anda berani melakukan sesuatu yang merugikan Lumopolis sementara itu,",
  ui_story_5004_50040301_35_dialog_content = "Aku akan menangkapmu dan membawamu kembali untuk diadili.",
  ui_story_5004_50040301_36_dialog_content = "Jadi kenapa kamu di sini, Brock? Anda tampak ketat dengan pemiliknya juga.",
  ui_story_5004_50040301_37_dialog_content = "Tentang itu... Saya di sini untuk membantu teman lama, teman mekanik yang saya sebutkan.",
  ui_story_5004_50040301_38_dialog_content = "Bagaimana saya menempatkan ini ... Dia merawat saya dan mobil saya berkali-kali. Ini adalah cara Rediesel Wrench untuk membayar hutang kita!",
  ui_story_5004_50040301_39_dialog_content = "Jika Anda pergi ke Tir' Hotel, Anda mungkin akan bertemu dengannya di sana.",
  ui_story_5004_50040301_40_dialog_content = "Dia menonjol seperti ibu jari yang sakit, dalam segala hal.",
  ui_story_5004_50040301_41_dialog_content = "Oh, hal lain.",
  ui_story_5004_50040301_42_dialog_content = "Soroz menemui gangguan yang datang. Tahu kenapa?",
  ui_story_5004_50040301_43_dialog_content = "Tidak. Saya tidak pernah mengemudikan Colossus sebelumnya.",
  ui_story_5004_50040301_44_dialog_content = "Anda bertindak seperti semua orang memiliki salah satunya.",
  ui_story_5004_50040301_45_dialog_content = "Tapi Colossi adalah kombinasi dari makhluk dan mesin, bukan?",
  ui_story_5004_50040301_46_dialog_content = "Jadi mungkin Soroz masuk angin atau semacamnya.",
  ui_story_5004_50040301_47_dialog_content = "<size=30>PlayerName, apakah ini tempat saya menertawakan leluconnya?</size>",
  ui_story_5004_50040301_48_dialog_content = "<size=30>Tidak yakin. Saya tidak tahu apakah dia bercanda atau serius.</size>",
  ui_story_5004_50040301_49_dialog_content = "Berhentilah berbisik di depanku.",
  ui_story_5004_50040301_50_dialog_content = "Saya mengambil mobil saya. Ikuti jalan ini, dan Anda akan sampai ke hotel.",
  ui_story_5004_50040301_51_dialog_content = "(Pemandangan ombak biru yang menerjang pantai emas sangat indah.)",
  ui_story_5004_50040301_52_dialog_content = "(Pohon rimbun dan hijau yang saya tidak tahu namanya bergoyang tertiup angin laut.)",
  ui_story_5004_50040301_53_dialog_content = "(Ada orang yang bermain di pasir.)",
  ui_story_5004_50040301_54_dialog_content = "(Saya tersesat dalam pemandangan, dan semua yang ada di sini di bawah sinar matahari, semuanya begitu bersemangat.)",
  ui_story_5004_50040301_55_dialog_content = "...",
  ui_story_5004_50040301_56_dialog_content = "Tempat ini... jauh lebih baik dari yang saya bayangkan.",
  ui_story_5004_50040301_57_dialog_content = "Apakah ini pantai, PlayerName?",
  ui_story_5004_50040301_58_dialog_content = "Saya tidak tahu ada tempat yang begitu santai mengingat krisis saat ini.",
  ui_story_5004_50040301_59_dialog_content = "lautnya sangat indah...",
  ui_story_5004_50040301_60_dialog_content = "Vendor itu punya antrean panjang, Beryl! Mari kita pergi dan melihat apa yang mereka miliki di sana!",
  ui_story_5004_50040301_61_dialog_content = "Heh, sepertinya kalian semua menemukan <color=#FFB400>Pantai Surgawi</color> sangat menyenangkan bukan?",
  ui_story_5004_50040301_62_dialog_content = "?!",
  ui_story_5004_50040301_63_dialog_content = "Selamat datang, saya penghubung resor Anda dan tuan rumah Ocean Sovereign, <color=#FFB400>Bonacie</color>!",
  ui_story_5004_50040301_64_dialog_content = "Hai, Bonasi.",
  ui_story_5004_50040301_65_dialog_content = "Anda di sini juga, Beryl! Pria menyebalkan berkacamata itu tidak bersamamu, bukan?",
  ui_story_5004_50040301_66_dialog_content = "Maksudnya Pak Faust? Dia memiliki pekerjaan yang harus dilakukan dan meninggalkan saya dengan PlayerName.",
  ui_story_5004_50040301_67_dialog_content = "Megah. Ini pasti PlayerName, saya kira?",
  ui_story_5004_50040301_68_dialog_content = "Menawan, bebek yang beruntung dikelilingi oleh wanita cantik, bukan?",
  ui_story_5004_50040301_69_dialog_content = "Kami hanya berteman.",
  ui_story_5004_50040301_70_dialog_content = "Pokoknya teman-teman saja, hehe.",
  ui_story_5004_50040301_71_dialog_content = "Tapi melihat PlayerName, saya tidak melihat sesuatu yang aneh, mata ketiga atau tanduk untuk Caelestite...",
  ui_story_5004_50040301_72_option_content = "Haruskah saya meminta maaf untuk itu?",
  ui_story_5004_50040301_73_dialog_content = "Anda memiliki selera humor yang tinggi, bukan?",
  ui_story_5004_50040301_74_option_content = "Caelestites dan Aurorian sangat mirip dalam penampilan.",
  ui_story_5004_50040301_75_dialog_content = "Ini lucu ketika Anda menjawab begitu serius.",
  ui_story_5004_50040301_76_dialog_content = "Aku hanya membuat lelucon. Tolong jangan menganggapnya serius.",
  ui_story_5004_50040301_77_dialog_content = "Anda semua adalah VIP hotel dan tamu kehormatan untuk Penguasa Laut.",
  ui_story_5004_50040301_78_dialog_content = "Tolong izinkan saya, Bonacie, untuk menunjukkan kepada Anda eksotika pantai musim panas yang mempesona dan layanan yang penuh gairah...",
  ui_story_5004_50040301_79_dialog_content = "Terima kasih banyak, tapi kami baik-baik saja...",
  ui_story_5004_50040301_80_dialog_content = "Aku punya pertanyaan. Apa sebenarnya Penguasa Laut itu?",
  ui_story_5004_50040301_81_dialog_content = "Ini adalah upacara yang ditinggalkan oleh para Aurorian yang dulu tinggal di pantai ini.",
  ui_story_5004_50040301_82_dialog_content = "\"Laut adalah asal mula semua kehidupan, merangkul dan memelihara semua yang ada di dadanya.\"",
  ui_story_5004_50040301_83_dialog_content = "\"Dewi laut menari dengan semua penantang juara di sini.\"",
  ui_story_5004_50040301_84_dialog_content = "Melalui Ocean Sovereign, peserta akan melakukan uji coba legendaris.",
  ui_story_5004_50040301_85_dialog_content = "Pemenang akhir akan muncul setelah kontes <color=#FFB400>kekuatan</color>, <color=#FFB400>pengetahuan</color>, dan <color=#FFB400>keberanian</color>.",
  ui_story_5004_50040301_86_dialog_content = "Dewa akan memberikan pemenang dengan hadiah dan menunjukkan berkah ke tanah yang indah ini.",
  ui_story_5004_50040301_87_dialog_content = "Pemenang juga akan mendapatkan <color=#FFB400>Pejuang Pantai</color> judul,",
  ui_story_5004_50040301_88_dialog_content = "dan bahkan hadiah utama misteri!",
  ui_story_5004_50040301_89_dialog_content = "Nikmati matahari dan kesenangan saat bersaing dengan gadis-gadis dalam kontes.",
  ui_story_5004_50040301_90_dialog_content = "Anda tidak menolaknya, PlayerName, bukan?",
  ui_story_5004_50040301_91_dialog_content = "Pejuang... Pantai...",
  ui_story_5004_50040301_92_dialog_content = "Saya masih harus membicarakannya dengan semua orang.",
  ui_story_5004_50040301_93_dialog_content = "Itu benar. Biarkan saya membawa semua orang ke hotel dan memeriksa Anda.",
  ui_story_5004_50040301_94_dialog_content = "Festival dimulai lusa. Nikmatilah dirimu sendiri dan bersantailah sesukamu, bukan?",
  ui_story_5004_50040301_95_dialog_content = "Ini sangat mewah!",
  ui_story_5004_50040301_96_dialog_content = "Memang gaya bangunannya berbeda dari Lumopolis dan Illumina.",
  ui_story_5004_50040301_97_dialog_content = "Ini mungkin dari peradaban tua.",
  ui_story_5004_50040301_98_dialog_content = "Berikut adalah lobi. Saya akan menyerahkan Anda ke manajer lobi, <color=#FFB400>Fleur</color>!",
  ui_story_5004_50040301_99_dialog_content = "Hmm, Fleur? Anda bisa bergerak sedikit lebih cepat, bukan?",
  ui_story_5004_50040301_100_dialog_content = "Ada urusan lain yang harus saya selesaikan, tetapi saya akan segera kembali.",
  ui_story_5004_50040301_101_dialog_content = "fleur?",
  ui_story_5004_50040301_102_dialog_content = "Maaf!",
  ui_story_5004_50040301_103_dialog_content = "Aku akan ke sana sebentar lagi!",
  ui_story_5004_50040301_104_dialog_content = "Fleur!",
  ui_story_5004_50040301_105_dialog_content = "Pak Fleur!",
  ui_story_5004_50040301_106_dialog_content = "Apakah Anda bebas malam ini, Tn. Fleur?",
  ui_story_5004_50040301_107_dialog_content = "Bawa saya ke gym, Fleury, dan saya akan menunjukkan abs saya yang sempurna!",
  ui_story_5004_50040301_108_dialog_content = "Saya baru saja memanggang ini. Buka lebar-lebar dan cobalah...",
  ui_story_5004_50040301_109_dialog_content = "Apa yang sedang terjadi? Kerumunan yang aneh, termasuk orang Fleur itu.",
  ui_story_5004_50040301_110_dialog_content = "Aku mendapatkan getaran aneh dari pria itu.",
  ui_story_5004_50040301_111_dialog_content = "Sepertinya Fleur bahkan lebih populer darimu, PlayerName.",
  ui_story_5004_50040301_112_dialog_content = "Berhentilah menertawakanku...",
  ui_story_5004_50040301_113_dialog_content = "Maaf. Saya Fleur. Anda harus menjadi pihak Colossus.",
  ui_story_5004_50040301_114_dialog_content = "Dan PlayerName, Brock cukup sering menyebut Anda.",
  ui_story_5004_50040301_115_dialog_content = "Anda tahu Brock?",
  ui_story_5004_50040301_116_dialog_content = "Ya. Saya sebenarnya seorang mekanik dengan Rediesel Wrench dan saya sudah mengenalnya sejak lama.",
  ui_story_5004_50040301_117_dialog_content = "Jadi Anda adalah mekanik yang dibicarakan Brock! (Dan juga sangat mencolok.)",
  ui_story_5004_50040301_118_dialog_content = "Ya, saya meminta bantuannya.",
  ui_story_5004_50040301_119_dialog_content = "Saya ingat, Fleur adalah legenda di Akademi Mekanik Illumina!",
  ui_story_5004_50040301_120_dialog_content = "Saya mendengar siswa senior di Illumina berbicara tentang Anda.",
  ui_story_5004_50040301_121_dialog_content = "Mereka bilang Anda mahir menggunakan mesin dan juga lembut, <size=40>meskipun ada beberapa </size><size=35>agak aneh</size>, <size=30><color=#FFB400>ceritanya kurang bagus</color> juga...</size>",
  ui_story_5004_50040301_122_dialog_content = "Ya, itu sebabnya dia lari ke Rediesel Wrench.",
  ui_story_5004_50040301_123_dialog_content = "Dan dia membantu Sinsa untuk memperbaiki Lepidoz. Cukup mengesankan.",
  ui_story_5004_50040301_124_dialog_content = "Apakah Anda tidak mendapatkan waktu libur dari Sinsa untuk liburan musim panas khusus?",
  ui_story_5004_50040301_125_dialog_content = "Dan di sinilah Anda, seorang manajer lobi... tapi tidak benar-benar terlihat seperti itu.",
  ui_story_5004_50040301_126_dialog_content = "Bukankah seharusnya kamu setidaknya memakai dasi seperti bangsawan Lumo yang sombong itu?",
  ui_story_5004_50040301_127_dialog_content = "...",
  ui_story_5004_50040301_128_dialog_content = "(Hei, kami memiliki bangsawan Lumo bersama kami!)",
  ui_story_5004_50040301_129_dialog_content = "Saya di sini atas permintaan Bonacie, dan juga untuk alasan lain.",
  ui_story_5004_50040301_130_dialog_content = "Saya pikir Anda baru saja mengambil waktu besar, tapi itu cocok untuk Anda.",
  ui_story_5004_50040301_131_dialog_content = "Tugas saya sebagai guide dan sopir sudah selesai. Saatnya saya memeriksa sistem stereo di bar.",
  ui_story_5004_50040301_132_dialog_content = "Jangan mencari saya kecuali sesuatu terjadi.",
  ui_story_5004_50040301_133_dialog_content = "Tenang saja, Regina.",
  ui_story_5004_50040301_134_dialog_content = "Dengan cara ini, semua orang. Aku akan memeriksamu.",
  ui_story_5004_50040301_135_dialog_content = "Bagaimana Anda ingin kamar Anda diatur?",
  ui_story_5004_50040301_136_dialog_content = "Yah, aku ingin...",
  ui_story_5004_50040301_137_dialog_content = "saya, saya! Saya ingin berbagi satu kamar dengan Beryl!",
  ui_story_5004_50040301_138_dialog_content = "Saya dokter utamanya, jadi saya tidak bisa membiarkan Beryl lepas dari pandangan saya!",
  ui_story_5004_50040301_139_dialog_content = "Tidak apa-apa kan? Benar?",
  ui_story_5004_50040301_140_dialog_content = "O-Oke. Saya tidak punya masalah dengan itu.",
  ui_story_5004_50040301_141_dialog_content = "Vice dan aku masing-masing akan memiliki kamar terpisah.",
  ui_story_5004_50040301_142_option_content = "Itu artinya aku...",
  ui_story_5004_50040301_143_dialog_content = "Kau tidur sendirian, tentu saja. Cukup yakin Anda tidak takut gelap, setelah menghabiskan lebih dari satu dekade di Soroz.",
  ui_story_5004_50040301_144_dialog_content = "Tentu saja!",
  ui_story_5004_50040301_145_option_content = "Bagaimana dengan Regina?",
  ui_story_5004_50040301_146_dialog_content = "Regina? Dia akan sibuk dengan sistem stereo selama berhari-hari.",
  ui_story_5004_50040301_147_dialog_content = "Aku bisa memeriksanya dan memberikan kuncinya nanti.",
  ui_story_5004_50040301_148_dialog_content = "Jadi itu total lima kamar.",
  ui_story_5004_50040301_149_dialog_content = "eh, tips...",
  ui_story_5004_50040301_150_dialog_content = "Tamu-tamu ini adalah VIP. kita tidak bisa meminta tip dari mereka. Ingat itu, oke?",
  ui_story_5004_50040301_151_dialog_content = "Ah, oh.",
  ui_story_5004_50040301_152_dialog_content = "Ini kunci kamarmu, tolong.",
  ui_story_5004_50040301_153_dialog_content = "Petugas itu, terlihat sedikit aneh...",
  ui_story_5004_50040301_154_dialog_content = "Haha, agak tidak pantas untuk mengatakan itu, PlayerName.",
  ui_story_5004_50040301_155_dialog_content = "Saya memiliki tanduk di kepala saya juga.",
  ui_story_5004_50040301_156_dialog_content = "Namun demikian, saya berharap semua orang bisa bergaul.",
  ui_story_5004_50040301_157_dialog_content = "(Tipe orang yang benar-benar baik-baik...)",
  ui_story_5004_50040301_158_dialog_content = "Sejujurnya, mereka bisa agak aneh ...",
  ui_story_5004_50040301_159_dialog_content = "Pemilik mematok mereka untuk tuntutan gaji rendah dan lembur gratis.",
  ui_story_5004_50040301_160_dialog_content = "Jadi banyak dari mereka dipekerjakan atas dasar itu.",
  ui_story_5004_50040301_161_dialog_content = "Saya percaya Brock mengatakan pemiliknya bukan tipe bisnis biasa?",
  ui_story_5004_50040301_162_dialog_content = "Pemiliknya ternyata adalah pemimpin geng dari Umbraton,",
  ui_story_5004_50040301_163_dialog_content = "yang memiliki ketajaman bisnis yang tajam dan mencintai uang. Rumor mengatakan pemiliknya memiliki usaha yang teduh saat menjalankan hotel.",
  ui_story_5004_50040301_164_dialog_content = "Saya tidak tahan sepenuhnya, tetapi karena saya memiliki kesepakatan dengan Bonacie, saya terjebak di sini setidaknya untuk saat ini.",
  ui_story_5004_50040301_165_dialog_content = "Oh, pengingat yang lembut. Ada beberapa perangkap turis yang tidak masuk akal di hotel dan di pantai. Mereka bisa mahal.",
  ui_story_5004_50040301_166_dialog_content = "Maksudmu vendor rip-off? Ya, kami akan berhati-hati.",
  ui_story_5004_50040301_167_dialog_content = "Mari saya tunjukkan kamar Anda. Silahkan lewat sini.",
  ui_story_5004_50040401_168_dialog_content = "Masuk, PlayerName.",
  ui_story_5004_50040401_169_dialog_content = "Apakah ini kamarku?",
  ui_story_5004_50040401_170_dialog_content = "Semoga Anda menemukannya sesuai dengan keinginan Anda.",
  ui_story_5004_50040401_171_dialog_content = "Oh, saya ingin berbicara dengan Anda, pemilik Colossus, tentang mesin.",
  ui_story_5004_50040401_172_dialog_content = "Tapi Anda pasti kelelahan, jadi lain kali, jika Anda mau.",
  ui_story_5004_50040401_173_dialog_content = "Setiap pertanyaan atau masalah, jangan ragu untuk menghubungi meja depan dengan <color=#FFB400>penghubung</color> di sana.",
  ui_story_5004_50040401_174_dialog_content = "Baiklah. Terima kasih.",
  ui_story_5004_50040401_175_dialog_content = "...",
  ui_story_5004_50040401_176_dialog_content = "Kamar rapi dengan apa yang tampak seperti tempat tidur empuk. Saya bisa melihat pantai di malam hari langsung dari jendela.",
  ui_story_5004_50040401_177_dialog_content = "Ini berbeda dari Illumina yang tertib atau Lumopolis yang canggih, tetapi hidup dan energik.",
  ui_story_5004_50040401_178_dialog_content = "Fiuh…",
  ui_story_5004_50040401_179_dialog_content = "Tempat tidurnya memang goyang.",
  ui_story_5004_50040401_180_dialog_content = "Sebuah undangan tiba-tiba, saya di pantai, berbaring di tempat tidur yang nyaman, tetapi semua ini belum meresap ...",
  ui_story_5004_50040401_181_dialog_content = "Lalu ada Ocean Sovereign... Rasanya aneh. Haruskah saya menjadi bagian darinya?",
  ui_story_5004_50040401_182_dialog_content = "Aku ingin tahu apa yang semua orang lakukan sekarang?",
  ui_story_5004_50040401_183_dialog_content = "<color=#e8d9bb>Bip Bip Bip!</color>",
  ui_story_5004_50040401_184_dialog_content = "Apa itu? Apakah komunikator yang disebutkan Fleur?",
  ui_story_5004_50040401_185_dialog_content = "Halo?",
  ui_story_5004_50040401_186_dialog_content = "Halo! Hai!",
  ui_story_5004_50040401_187_dialog_content = "Selebaran Anda, katanya, \"Mengungkap potensi penuh Anda untuk menjadi lebih kuat dalam tujuh hari.\" Benarkah itu?!",
  ui_story_5004_50040401_188_dialog_content = "Bangsat? Apa yang Anda mengoceh tentang?",
  ui_story_5004_50040401_189_dialog_content = "PlayerName? Saya pasti salah nomor.",
  ui_story_5004_50040401_190_dialog_content = "Aku akan menangkapmu lain kali!",
  ui_story_5004_50040401_191_dialog_content = "<color=#e8d9bb>Bip ... bip ...</color>",
  ui_story_5004_50040401_192_dialog_content = "Dia menutup telepon. Mudah-mudahan dia tidak jatuh untuk beberapa penipuan.",
  ui_story_5004_50040401_193_dialog_content = "Saya seharusnya bisa melakukan panggilan dari kamar ke kamar dengan menekan nomor kamar, bukan?",
  ui_story_5004_50040401_194_dialog_content = "Mari kita coba...",
  ui_story_5004_50040401_195_option_content = "Panggilan Vice",
  ui_story_5004_50040401_196_dialog_content = "Apakah itu PlayerName?",
  ui_story_5004_50040401_197_dialog_content = "Saya tidak tahu hotel akan memiliki komunikator yang nyaman!",
  ui_story_5004_50040401_198_dialog_content = "Aku tidak mengganggu apa-apa, kan? Hanya ingin tahu apa yang Anda lakukan sekarang.",
  ui_story_5004_50040401_199_dialog_content = "Tidak, tidak ada yang khusus, hanya berbaring di tempat tidur... Sangat nyaman!",
  ui_story_5004_50040401_200_dialog_content = "Jadi, menurut Anda, apakah kita harus bergabung dengan Ocean Sovereign?",
  ui_story_5004_50040401_201_dialog_content = "Tentu! Anda mendengar apa yang dikatakan Fleur, bukan?",
  ui_story_5004_50040401_202_dialog_content = "Kami bisa tinggal di resor secara gratis, tetapi kami harus membayar semua yang lain—makanan, pakaian renang, semua aktivitas.",
  ui_story_5004_50040401_203_dialog_content = "Jika kita hanya menghabiskan uang tanpa menghasilkan apapun, maka...",
  ui_story_5004_50040401_204_dialog_content = "Saya, saya tidak terlalu percaya diri dengan atletik ...",
  ui_story_5004_50040401_205_dialog_content = "Jangan khawatir, Anda mendapatkan saya dan semua orang. Kami akan bekerja sebagai tim.",
  ui_story_5004_50040401_206_dialog_content = "Jangan lupa, tidak ada yang memiliki keunggulan dalam hal memerintah, PlayerName!",
  ui_story_5004_50040401_207_dialog_content = "Anda mungkin benar tentang itu...",
  ui_story_5004_50040401_208_dialog_content = "Tapi bagaimana jika hadiahnya bukan Nightium?",
  ui_story_5004_50040401_209_dialog_content = "Tidak apa-apa, kita bisa memberikannya kepada Sheol untuk dijual.",
  ui_story_5004_50040401_210_dialog_content = "Jangan khawatir, PlayerName. Beristirahatlah dan kami pasti menang!",
  ui_story_5004_50040401_211_dialog_content = "Jika itu yang Anda rasakan, ayo lakukan!",
  ui_story_5004_50040401_212_option_content = "Panggil Carleen",
  ui_story_5004_50040401_213_dialog_content = "PlayerName? Ada yang salah?",
  ui_story_5004_50040401_214_dialog_content = "Maaf. Aku hanya ingin tahu apa yang kamu lakukan, Carleen.",
  ui_story_5004_50040401_215_dialog_content = "Bersiap-siap untuk tidur, sesuai dengan jadwal harian saya.",
  ui_story_5004_50040401_216_dialog_content = "Kamu selalu sangat disiplin.",
  ui_story_5004_50040401_217_dialog_content = "Oh, apa perasaanmu di Ocean Sovereign?",
  ui_story_5004_50040401_218_dialog_content = "Kami pasti akan menang.",
  ui_story_5004_50040401_219_dialog_content = "Mengapa Anda mengatakan itu ketika kami bahkan belum memutuskan untuk masuk?",
  ui_story_5004_50040401_220_dialog_content = "Kenapa tidak? Kami diundang karena suatu alasan. Sudah menjadi takdir kita untuk menjawab tantangan tersebut.",
  ui_story_5004_50040401_221_dialog_content = "Seorang pejuang sejati tidak pernah mundur dari apapun.",
  ui_story_5004_50040401_222_dialog_content = "Saya tahu Anda mungkin bingung atau cemas, PlayerName.",
  ui_story_5004_50040401_223_dialog_content = "Tetapi Anda harus percaya bahwa Anda dapat mengatasi rintangan dan menempa jalan Anda sendiri.",
  ui_story_5004_50040401_224_dialog_content = "Anda istimewa bagi semua Aurorian, termasuk saya sendiri.",
  ui_story_5004_50040401_225_dialog_content = "Apakah kamu membuatku gila?",
  ui_story_5004_50040401_226_dialog_content = "Tentu saja, saya memberi Anda semangat.",
  ui_story_5004_50040401_227_dialog_content = "Tidak heran Anda adalah Kapten Penjaga Lumopolis. Saya merasa terinspirasi.",
  ui_story_5004_50040401_228_dialog_content = "Bagus. Sekarang istirahatlah.",
  ui_story_5004_50040401_229_dialog_content = "Oke. Aku akan masuk karena sudah diputuskan kita akan memasuki Ocean Sovereign!",
  ui_story_5004_50040401_230_dialog_content = "Omong-omong, apakah itu tempat tidur single di semua kamar?",
  ui_story_5004_50040401_230X1_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5004_50040401_230X2_dialog_content = "Aduh!",
  ui_story_5004_50040401_230X3_dialog_content = "Maaf! Apakah kamu baik-baik saja?",
  ui_story_5004_50040401_230X4_dialog_content = "Mengapa Anda berdiri di ambang pintu dengan piring di tangan? Itu hanya meminta masalah!",
  ui_story_5004_50040401_230X5_dialog_content = "Huff, huff... Kamu lari terlalu cepat, Raphael...",
  ui_story_5004_50040401_230X6_dialog_content = "Saya sedang mengantarkan makanan penutup yang dipesan oleh tamu di ruangan ini.",
  ui_story_5004_50040401_230X7_dialog_content = "Jika tidak ada yang lain, aku harus pergi. Sedang sibuk di dapur.",
  ui_story_5004_50040401_230X8_dialog_content = "Kok di luar berisik?",
  ui_story_5004_50040401_230X9_dialog_content = "<color=#e8d9bb>Tok, tok!</color>",
  ui_story_5004_50040401_231_dialog_content = "Bagaimana dengan Beryl dan...",
  ui_story_5004_50040401_232_dialog_content = "Kami di sini untuk bergaul dengan Anda, PlayerName! Hei, apakah kamu ngemil di belakang punggung kami!",
  ui_story_5004_50040401_233_dialog_content = "Rafael? Tidak, aku tidak punya apa-apa...",
  ui_story_5004_50040401_234_dialog_content = "S-selamat malam…",
  ui_story_5004_50040401_235_dialog_content = "Anda di sini juga, Beryl?",
  ui_story_5004_50040401_236_dialog_content = "Apakah Anda tidak memiliki sesuatu untuk dikatakan kepada PlayerName, Beryl?",
  ui_story_5004_50040401_237_dialog_content = "Hmm…",
  ui_story_5004_50040401_238_dialog_content = "Apakah kamu malu? Bisakah saya mengatakannya untuk Anda?",
  ui_story_5004_50040401_239_dialog_content = "Ya…",
  ui_story_5004_50040401_240_dialog_content = "Oke.",
  ui_story_5004_50040401_241_dialog_content = "Jadi, Beryl sangat ingin berada di Ocean Sovereign.",
  ui_story_5004_50040401_242_dialog_content = "Tentu.",
  ui_story_5004_50040401_243_dialog_content = "Tapi dia tidak bisa berada di Ocean Sovereign.",
  ui_story_5004_50040401_244_dialog_content = "Apa?",
  ui_story_5004_50040401_245_dialog_content = "Tidak bisakah kamu menggunakan kepalamu itu, PlayerName?",
  ui_story_5004_50040401_246_dialog_content = "Jangan salahkan PlayerName, Raphael. Saya tidak mengatur pikiran saya dengan benar.",
  ui_story_5004_50040401_247_dialog_content = "PlayerName, apakah Anda ingat hadiah yang disebutkan Bonacie?",
  ui_story_5004_50040401_248_dialog_content = "Oh, apakah Beryl butuh uang? Sebenarnya saya...",
  ui_story_5004_50040401_249_dialog_content = "Tidak, ini adalah gelar Warrior of the Beach!",
  ui_story_5004_50040401_250_dialog_content = "...",
  ui_story_5004_50040401_251_dialog_content = "Ekspresi apa itu? Apakah Anda memiliki masalah dengan mimpi gadis muda yang polos?",
  ui_story_5004_50040401_252_dialog_content = "Saya tidak akan berani! Saya hanya keluar zona sebentar.",
  ui_story_5004_50040401_253_dialog_content = "Apakah kamu serius, Beryl?",
  ui_story_5004_50040401_254_dialog_content = "Baik...!",
  ui_story_5004_50040401_255_dialog_content = "Partisipasi tidak masalah. Semua orang juga berpikiran sama.",
  ui_story_5004_50040401_256_dialog_content = "Sungguh?",
  ui_story_5004_50040401_257_dialog_content = "Baiklah!",
  ui_story_5004_50040401_258_dialog_content = "Tapi apa maksudmu Anda tidak bisa berada di dalamnya?",
  ui_story_5004_50040401_259_dialog_content = "Nah, Beryl...",
  ui_story_5004_50040401_260_dialog_content = "Saya dapat memberi tahu PlayerName sendiri. Terima kasih, Rafael.",
  ui_story_5004_50040401_261_dialog_content = "Fiuh…",
  ui_story_5004_50040401_262_dialog_content = "Anda melihat apa yang bisa saya lakukan hari ini...",
  ui_story_5004_50040401_263_dialog_content = "Benar, itu luar biasa kuat.",
  ui_story_5004_50040401_264_dialog_content = "Tapi aku juga bisa dengan mudah kehilangan kendali... Ini berbahaya...",
  ui_story_5004_50040401_265_dialog_content = "Semakin banyak kekuatan yang saya keluarkan, semakin mempengaruhi saya secara fisik dan emosional ...",
  ui_story_5004_50040401_266_dialog_content = "Saya menghabiskan terlalu banyak untuk mengeluarkan semua Eclipsites itu, saya tidak dapat terlibat dalam kegiatan yang ketat selama beberapa hari ke depan.",
  ui_story_5004_50040401_267_dialog_content = "Saya mengerti. Oke, Anda melakukannya untuk membantu kami, jadi kami semua akan membantu Anda!",
  ui_story_5004_50040401_268_dialog_content = "Saya akan berbicara dengan yang lain dan menempatkan Anda di tim sebagai cadangan.",
  ui_story_5004_50040401_269_dialog_content = "Anda harus memutuskan apakah dan kapan Anda cukup fit untuk mengikuti kontes.",
  ui_story_5004_50040401_270_dialog_content = "Kamu tidak keberatan?",
  ui_story_5004_50040401_271_dialog_content = "Ya!",
  ui_story_5004_50040401_272_dialog_content = "Saya ingin bertanya, Anda menyebutkan itu memiliki dampak emosional. Saya ingin tahu secara spesifik.",
  ui_story_5004_50040401_273_dialog_content = "Saya menjadi sangat sedih dan tertekan, yang pada gilirannya meningkatkan kekuatan saya ... dan membuat saya lebih mudah kehilangan kendali.",
  ui_story_5004_50040401_274_dialog_content = "Itu satu lingkaran setan!",
  ui_story_5004_50040401_275_dialog_content = "Ya.",
  ui_story_5004_50040401_276_dialog_content = "Saya harap Anda dapat menghilangkan kesedihan dan depresi suatu hari nanti, dan menemukan keberanian untuk mengendalikan kekuatan itu.",
  ui_story_5004_50040401_277_dialog_content = "Saya menantikan perubahan ketika itu terjadi.",
  ui_story_5004_50040501_1_dialog_content = "...",
  ui_story_5004_50040501_2_dialog_content = "...",
  ui_story_5004_50040501_3_dialog_content = "Tidak, masih belum terbiasa tidur jauh dari Colossus.",
  ui_story_5004_50040501_4_option_content = "Cobalah untuk bangun dari tempat tidur",
  ui_story_5004_50040501_5_dialog_content = "<color=#e8d9bb>Tok, tok!</color>",
  ui_story_5004_50040501_6_dialog_content = "Apakah Anda bangun, PlayerName?",
  ui_story_5004_50040501_7_option_content = "Cobalah untuk bangun dari tempat tidur lagi",
  ui_story_5004_50040501_8_dialog_content = "Ya. Tunggu sementara aku bangun.",
  ui_story_5004_50040501_9_dialog_content = "<color=#e8d9bb>Klik.</color>",
  ui_story_5004_50040501_10_dialog_content = "Pagi, PlayerName. Waktu untuk bangun.",
  ui_story_5004_50040501_11_dialog_content = "Carleen dan yang lainnya sedang menunggu di ruang makan!",
  ui_story_5004_50040501_12_dialog_content = "Pagi, PlayerName. Anda tidak terlihat seperti Anda memiliki tidur malam yang baik.",
  ui_story_5004_50040501_13_dialog_content = "Pagi. Aku tidak terbiasa tidur jauh dari Colossus...",
  ui_story_5004_50040501_14_dialog_content = "Tapi tidak apa-apa, saya menikmati pengalaman khusus seperti ini.",
  ui_story_5004_50040501_15_dialog_content = "Saya telah melalui banyak hal yang tidak pernah saya duga sejak saya bertemu Vice dan Carleen.",
  ui_story_5004_50040501_16_dialog_content = "Kamu terdengar dewasa saat berbicara seperti itu, PlayerName.",
  ui_story_5004_50040501_17_dialog_content = "Apakah ada keajaiban di angin laut?",
  ui_story_5004_50040501_18_dialog_content = "Haha... Atau mungkin hanya karena kurang tidur semalam.",
  ui_story_5004_50040501_19_dialog_content = "Bagaimana dengan kalian berdua, Raphael dan Beryl?",
  ui_story_5004_50040501_20_option_content = "Bagaimana Anda tidur?",
  ui_story_5004_50040501_21_dialog_content = "Cukup bagus, meskipun agak ramai di tempat tidur.",
  ui_story_5004_50040501_22_dialog_content = "(Saya tahu itu adalah tempat tidur tunggal.)",
  ui_story_5004_50040501_23_dialog_content = "Fakta menarik tentang Beryl, PlayerName! Dia suka berpegangan pada sesuatu saat dia tidur, bukankah itu menggemaskan?",
  ui_story_5004_50040501_24_dialog_content = "Menggendong bantal saat tidur itu biasa... kan?",
  ui_story_5004_50040501_25_option_content = "Apakah itu tempat tidur ganda di kamar Anda?",
  ui_story_5004_50040501_26_dialog_content = "Tidak. Ini agak terlalu kecil...",
  ui_story_5004_50040501_27_dialog_content = "Karena selain kita berdua, ada bantal raksasa.",
  ui_story_5004_50040501_28_dialog_content = "itu saya...",
  ui_story_5004_50040501_29_dialog_content = "Saya tidak menyangka Beryl adalah tipe orang yang memegang sesuatu saat tidur.",
  ui_story_5004_50040501_30_dialog_content = "Itu normal untuk memegang bantal saat tidur!",
  ui_story_5004_50040501_31_dialog_content = "Ya, bantal untuk paruh pertama malam...",
  ui_story_5004_50040501_32_dialog_content = "Bisakah kita berhenti membicarakannya?",
  ui_story_5004_50040501_33_dialog_content = "Selamat pagi semuanya! Apakah Anda memiliki istirahat yang baik?",
  ui_story_5004_50040501_34_dialog_content = "Hei, pagi, Fleur!",
  ui_story_5004_50040501_35_dialog_content = "Itu baik-baik saja. Fasilitas yang besar dan tempat tidur yang sangat nyaman.",
  ui_story_5004_50040501_36_dialog_content = "Tapi aku masih membiasakan diri.",
  ui_story_5004_50040501_37_dialog_content = "Hahaha, saya sudah sering mendengar itu dari pelanggan, tapi saya yakin Anda akan menyiasatinya.",
  ui_story_5004_50040501_38_dialog_content = "Orang-orang merasa lebih aman di rumah saat ini, terutama dengan semua Eclipsites berkeliaran.",
  ui_story_5004_50040501_39_dialog_content = "Anda membuat poin yang adil, Fleur. Oh, Carleen menyebutkan ada <color=#FFB400>toko pakaian renang</color> di sini.",
  ui_story_5004_50040501_40_dialog_content = "Apakah Anda tahu bagaimana mencapainya, Fleur?",
  ui_story_5004_50040501_41_dialog_content = "Tentu saja, itu di <color=#FFB400>sisi timur laut dari ruang makan</color>.",
  ui_story_5004_50040501_42_dialog_content = "Bagus, kita akan memukulnya setelah sarapan!",
  ui_story_5004_50040501_43_dialog_content = "Ya!",
  ui_story_5004_50040601_44_dialog_content = "Apakah biasanya butuh waktu lama untuk memilih sesuatu?",
  ui_story_5004_50040601_45_dialog_content = "Mereka menyuruhku menunggu di <color=#FFB400>pantai</color>, tapi itu lebih dari satu jam yang lalu.",
  ui_story_5004_50040601_46_dialog_content = "Sinar matahari cukup intens, tetapi tidak buruk untuk berjemur.",
  ui_story_5004_50040601_47_dialog_content = "Vice dan yang lainnya seperti teman lamaku... Tidak ada lagi Eclipsites atau rencana jahat mereka...",
  ui_story_5004_50040601_48_dialog_content = "Nikmati waktu senggang dan bermalas-malasan... betapa santainya!",
  ui_story_5004_50040601_49_dialog_content = "...",
  ui_story_5004_50040601_50_dialog_content = "Bahkan pasirnya hangat dan nyaman, mungkin aku harus menggambar sesuatu.",
  ui_story_5004_50040601_51_dialog_content = "Apa yang kamu gambar, PlayerName? Seekor gurita?",
  ui_story_5004_50040601_52_dialog_content = "Apa? Tidak! Ini kucing! Kucing!",
  ui_story_5004_50040601_53_dialog_content = "Jadi tentakel yang bengkok sebenarnya adalah kumis?",
  ui_story_5004_50040601_54_dialog_content = "Biarkan saya membantu Anda menggambar kumis yang lebih baik!",
  ui_story_5004_50040601_55_dialog_content = "Jangan gunakan kakimu, Vice! Hebat, sekarang kumisnya lebih tebal dari lenganku!",
  ui_story_5004_50040601_56_dialog_content = "...",
  ui_story_5004_50040601_57_dialog_content = "Apa?",
  ui_story_5004_50040601_58_dialog_content = "Emm... tidak buruk.",
  ui_story_5004_50040601_59_dialog_content = "Tidak buruk apa?",
  ui_story_5004_50040601_60_dialog_content = "Kamu bertingkah aneh, PlayerName.",
  ui_story_5004_50040601_61_dialog_content = "Sudahlah, aku hanya akan menikmati pemandangan.",
  ui_story_5004_50040601_62_dialog_content = "Musim panas bukanlah musim panas sampai Anda mengenakan baju renang di tepi pantai.",
  ui_story_5004_50040601_63_dialog_content = "Baju renang Anda tidak cocok untuk menjadi baju perang, jika Anda bertanya kepada saya.",
  ui_story_5004_50040601_64_dialog_content = "PlayerName! Saya akan menunjukkan kepada Anda seperti apa seorang ksatria yang tidak takut dengan ombak besar!",
  ui_story_5004_50040601_65_dialog_content = "(Meskipun ada perbedaan pendapat, Carleen juga tampak bersemangat...)",
  ui_story_5004_50040601_66_dialog_content = "(Begitulah, dia membiarkan saya menatapnya dengan pakaian renang.)",
  ui_story_5004_50040601_67_dialog_content = "Bagaimana menurutmu, PlayerName?",
  ui_story_5004_50040601_68_dialog_content = "Apa maksudmu apa yang aku pikirkan?",
  ui_story_5004_50040601_69_dialog_content = "Pakaian renang, tentu saja. Menurut Anda siapa yang akan menaklukkan pantai?",
  ui_story_5004_50040601_70_option_content = "Vice lucu dan lincah dalam pakaian renangnya.",
  ui_story_5004_50040601_72_dialog_content = "Apakah itu yang Anda suka, PlayerName?",
  ui_story_5004_50040601_73_dialog_content = "Tapi Vice dikenal energik di sekolah.",
  ui_story_5004_50040601_74_dialog_content = "Apa pun mulai dari menarik dua kali lipat untuk memenuhi tujuan pelatihan hingga menjejalkan sepanjang malam untuk ujian, dia melakukan semuanya.",
  ui_story_5004_50040601_75_dialog_content = "Tentu! Tidak ada yang cocok untuk saya dalam hal itu!",
  ui_story_5004_50040601_76_option_content = "Baju renang Carleen canggih dan elegan.",
  ui_story_5004_50040601_78_dialog_content = "Aku pikir juga begitu!",
  ui_story_5004_50040601_79_dialog_content = "Anda tidak dapat memancarkan keanggunan mulia yang dia lakukan tanpa menjalani pelatihan etiket ketat yang dilakukan Carleen.",
  ui_story_5004_50040601_80_dialog_content = "Illumina mengembangkan disiplin militer. Ini berbeda dari Lumopolis.",
  ui_story_5004_50040601_81_dialog_content = "Itu benar, Vice menggangguku di kelas sains kita...",
  ui_story_5004_50040601_82_dialog_content = "Heheh, saya hanya lebih berbakat di bidang itu.",
  ui_story_5004_50040601_83_dialog_content = "Tapi mengerikan dalam segala hal yang berhubungan dengan seni.",
  ui_story_5004_50040601_84_dialog_content = "Itu karena Lumopolis tidak menawarkan kelas menggambar teknik.",
  ui_story_5004_50040601_85_dialog_content = "Anda menyebutnya seni? Anda tidak melihatnya di tempat lain selain Illumina!",
  ui_story_5004_50040601_86_dialog_content = "Kalau begitu, aku mungkin berbakat dalam musik! Saya memang membantu PlayerName untuk memulai Colossus sebelumnya!",
  ui_story_5004_50040601_87_dialog_content = "Ya, Anda melakukannya. Dan saya berterima kasih sekali lagi atas nama Soroz, Letnan Vice.",
  ui_story_5004_50040601_88_dialog_content = "Terima kasih kepada Anda, semua orang sekarang mendapat kesempatan untuk bermain-main di tepi laut.",
  ui_story_5004_50040601_89_dialog_content = "Maaf membuat kalian menunggu!",
  ui_story_5004_50040601_90_dialog_content = "Rafael! Anda tidak dalam pakaian renang.",
  ui_story_5004_50040601_91_dialog_content = "Saya bertugas sebagai dokter. Tidak etis bagi saya untuk berganti pakaian renang dan bergaul dengan pasien di bawah perawatan saya.",
  ui_story_5004_50040601_92_dialog_content = "Saya mengerti. Jadi di mana Beryl?",
  ui_story_5004_50040601_93_dialog_content = "Beril?",
  ui_story_5004_50040601_94_dialog_content = "Ayo, Beryl!",
  ui_story_5004_50040601_95_dialog_content = "Tidak... Ini canggung...",
  ui_story_5004_50040601_96_dialog_content = "Saya belum pernah memakai apa pun yang menunjukkan kulit sebanyak ini sebelumnya ...",
  ui_story_5004_50040601_97_dialog_content = "Jangan malu, kamu terlihat sangat imut!",
  ui_story_5004_50040601_98_dialog_content = "Apa itu benar, PlayerName?",
  ui_story_5004_50040601_99_dialog_content = "Ya. Seluruh temperamen Anda telah berubah di dalamnya, dengan cara yang baik, dan itu cocok untuk Anda.",
  ui_story_5004_50040601_100_dialog_content = "Itu benar, bahkan aku tidak dapat menyangkal bahwa kamu akan menjadi ksatria yang baik sekarang.",
  ui_story_5004_50040601_101_dialog_content = "Custom-fit harus membuatnya lebih mudah untuk bergerak.",
  ui_story_5004_50040601_102_dialog_content = "Saya setuju. Ini jauh lebih menggemaskan daripada pakaian biasa Beryl.",
  ui_story_5004_50040601_103_dialog_content = "Ayo berenang bersama kami dengan setelan lucu itu!",
  ui_story_5004_50040601_104_dialog_content = "Lihat, semua orang berpikir kau cantik di dalamnya, Beryl!",
  ui_story_5004_50040601_105_dialog_content = "Belum lagi bagaimana semua orang berpakaian!",
  ui_story_5004_50040601_106_dialog_content = "Hmm…",
  ui_story_5004_50040601_107_dialog_content = "Tidak apa-apa, kurasa.",
  ui_story_5004_50040601_108_dialog_content = "Berhentilah terlalu khawatir, Beryl!",
  ui_story_5004_50040601_108X1_dialog_content = "<color=#e8d9bb>Jepret.</color>",
  ui_story_5004_50040601_108X2_dialog_content = "<color=#e8d9bb>Jepret, jepret.</color>",
  ui_story_5004_50040601_108X3_dialog_content = "Apakah itu petugas dari kemarin?",
  ui_story_5004_50040601_108X4_dialog_content = "Yang memegang kamera? Itu seharusnya kamera, saya melihat sesuatu yang serupa di Lumopolis sebelumnya!",
  ui_story_5004_50040601_108X5_dialog_content = "Itu aneh. Mengapa seseorang yang memotret bersembunyi di sudut?",
  ui_story_5004_50040601_108X6_dialog_content = "Mungkin pemandangan untuk tujuan promosi? Biarkan saya melihat apakah saya dapat meminjam kamera untuk mengambil gambar!",
  ui_story_5004_50040601_108X7_dialog_content = "Oh, gadis-gadis berbaju renang harus memberiku bonus...",
  ui_story_5004_50040601_108X8_dialog_content = "Permisi!",
  ui_story_5004_50040601_108X9_dialog_content = "Aduh!",
  ui_story_5004_50040601_108X10_dialog_content = "Apa...? Anda melemparkannya ke arah saya bahkan sebelum saya bertanya!",
  ui_story_5004_50040601_108X11_dialog_content = "Saya kira Anda tidak keberatan meminjamkan saya ini, terima kasih!",
  ui_story_5004_50040601_108X12_dialog_content = "Kamu menakuti saya...",
  ui_story_5004_50040601_108X13_dialog_content = "Aku butuh itu kembali...",
  ui_story_5004_50040601_108X14_dialog_content = "Petugas itu tampaknya enggan, Raphael. Mungkin Anda harus mengembalikan kameranya.",
  ui_story_5004_50040601_108X15_dialog_content = "Beryl adalah gadis yang manis. Ini dia, jangan dilempar lagi.",
  ui_story_5004_50040601_108X16_dialog_content = "Terima kasih…",
  ui_story_5004_50040601_109_dialog_content = "Oke, ayo bersenang-senang, Beryl!",
  ui_story_5004_50040601_110_dialog_content = "Ayo pergi juga, PlayerName.",
  ui_story_5004_50040601_111_dialog_content = "Tentu!",
  ui_story_5004_50040701_1_dialog_content = "Mengapa mereka begitu bersemangat dan energik?",
  ui_story_5004_50040701_2_dialog_content = "(Vice berenang seperti dia memiliki baling-baling, meninggalkan semprotan besar di belakang.)",
  ui_story_5004_50040701_3_dialog_content = "(Carleen mengangkat semua jenis makhluk laut dari air dengan tombaknya.)",
  ui_story_5004_50040701_4_dialog_content = "(Dan melemparkan makhluk-makhluk itu bahkan lebih besar dari miliknya di darat.)",
  ui_story_5004_50040701_5_dialog_content = "(Bahkan Beryl dan Raphael dengan pusing mengambil kerang dan membuat istana pasir.)",
  ui_story_5004_50040701_6_dialog_content = "(Harus diakui, Beryl membangun istana pasir yang luar biasa mengesankan...)",
  ui_story_5004_50040701_7_dialog_content = "(Selain duri yang mencuat dan menara, ada menara jam raksasa.)",
  ui_story_5004_50040701_X7_dialog_content = "(Kastil terlihat seperti diperintah oleh beberapa kekuatan jahat...)",
  ui_story_5004_50040701_8_dialog_content = "Kemudian lagi, apakah saya... lemah?",
  ui_story_5004_50040701_9_dialog_content = "Saya hampir tidak berolahraga di Colossus.",
  ui_story_5004_50040701_10_dialog_content = "Saya terutama berdiri di sekitar dan memberi perintah saat dalam pertempuran ...",
  ui_story_5004_50040701_11_dialog_content = "Mungkin saya harus berlari beberapa putaran di pantai agar bugar.",
  ui_story_5004_50040701_12_dialog_content = "Hei, bukankah itu Tuan Besar Colossus, Komandan Masa Depan Illumina, Penjaga Lumopolis...",
  ui_story_5004_50040701_13_dialog_content = "Dan sahabat terbaik bos Rediesel Wrench berikutnya, PlayerName?",
  ui_story_5004_50040701_14_dialog_content = "Bangsat? Apa yang kamu lakukan di sini?",
  ui_story_5004_50040701_15_dialog_content = "Bukankah Anda seharusnya membantu Fleur?",
  ui_story_5004_50040701_16_dialog_content = "Omong-omong, saya tidak berpikir Anda bisa mengalahkan Sinsa dan menjadi bos baru.",
  ui_story_5004_50040701_17_dialog_content = "Anda seorang komandan yang baik, PlayerName, tetapi hakim karakter yang buruk.",
  ui_story_5004_50040701_18_dialog_content = "Sinsa sedang menurun, sementara saya, saya adalah bintang yang sedang naik daun!",
  ui_story_5004_50040701_X18_dialog_content = "...",
  ui_story_5004_50040701_19_dialog_content = "Banyak orang di Rediesel Wrench ada di pihak saya sekarang!",
  ui_story_5004_50040701_20_dialog_content = "Banyak? Seperti siapa?",
  ui_story_5004_50040701_21_dialog_content = "Ada Fleur...",
  ui_story_5004_50040701_22_dialog_content = "...",
  ui_story_5004_50040701_23_dialog_content = "Lalu?",
  ui_story_5004_50040701_24_dialog_content = "Fleur, Fleur, dan Fleur. Oh, aku harus membicarakannya dengan Regina!",
  ui_story_5004_50040701_25_dialog_content = "Saya tidak berpikir Regina tertarik dalam hal itu.",
  ui_story_5004_50040701_26_dialog_content = "Kemudian saya akan berbicara dengan Anda.",
  ui_story_5004_50040701_27_dialog_content = "Jadi Anda bisa mengumumkan bahwa Anda mendapat dukungan dari ras Caelestite?",
  ui_story_5004_50040701_28_dialog_content = "Ayolah, PlayerName, kau Caelestite terpintar yang kukenal!",
  ui_story_5004_50040701_29_dialog_content = "Ya, aku satu-satunya Caelestit lho!",
  ui_story_5004_50040701_30_dialog_content = "Sst.",
  ui_story_5004_50040701_31_dialog_content = "…?",
  ui_story_5004_50040701_32_dialog_content = "Kamu melihatnya<color=#FFB400> orang di sana</color>, PlayerName?",
  ui_story_5004_50040701_33_dialog_content = "Gadis itu?",
  ui_story_5004_50040701_34_dialog_content = "Ya. Dia menyelinap, mengobrak-abrik semuanya.",
  ui_story_5004_50040701_35_dialog_content = "Nah, dia mungkin mencari sesuatu yang hilang.",
  ui_story_5004_50040701_36_dialog_content = "Pernahkah Anda melihat seseorang mengangkat batu sebesar itu untuk mencari sesuatu yang hilang?",
  ui_story_5004_50040701_37_dialog_content = "Baiklah, mari kita periksa.",
  ui_story_5004_50040701_38_option_content = "Baiklah…",
  ui_story_5004_50040701_39_dialog_content = "Tapi kenapa kamu begitu penasaran dengannya?",
  ui_story_5004_50040701_40_dialog_content = "Bagaimana jika dia seorang pencuri?",
  ui_story_5004_50040701_41_dialog_content = "Bagaimana? Siapa yang akan menyembunyikan sesuatu di bawah batu itu?",
  ui_story_5004_50040701_42_dialog_content = "Saya tidak ingat rasa keadilan ini dari Anda di Rediesel Wrench.",
  ui_story_5004_50040701_43_dialog_content = "Ini berbeda sekarang, saya bekerja untuk Fleur! aku sekarang <color=#FFB400>Kepala Keamanan Pantai Surgawi</color>!",
  ui_story_5004_50040701_44_dialog_content = "(Jenius apa yang menyewa Rediesel Wrench untuk keamanan?)",
  ui_story_5004_50040701_45_option_content = "Saya tidak berpikir kita harus ikut campur dalam urusan orang lain.",
  ui_story_5004_50040701_46_dialog_content = "Saya tidak ingat rasa keadilan ini dari Anda di Rediesel Wrench.",
  ui_story_5004_50040701_47_dialog_content = "Ini berbeda sekarang, saya bekerja untuk Fleur! aku sekarang <color=#FFB400>Kepala Keamanan Pantai Surgawi</color>!",
  ui_story_5004_50040701_48_dialog_content = "(Jenius apa yang menyewa Rediesel Wrench untuk keamanan?)",
  ui_story_5004_50040701_49_dialog_content = "Diam dan ikuti aku.",
  ui_story_5004_50040701_50_dialog_content = "Hei, kamu, orang yang mencurigakan!",
  ui_story_5004_50040701_51_dialog_content = "...",
  ui_story_5004_50040701_52_dialog_content = "Hei!",
  ui_story_5004_50040701_53_dialog_content = "Jangan sentuh aku!",
  ui_story_5004_50040701_54_dialog_content = "Lihat itu, PlayerName? Dia memukulku lebih dulu!",
  ui_story_5004_50040701_55_dialog_content = "Tunggu, bukankah kamu menghindarinya? Jangan sampai kita melakukan kekerasan.",
  ui_story_5004_50040701_56_dialog_content = "Kamu siapa? Dan siapa kepala otot ini?",
  ui_story_5004_50040701_57_dialog_content = "Apa yang Anda pikir Anda lakukan meneriaki orang dan mencoba meraih bahu seorang wanita!",
  ui_story_5004_50040701_58_dialog_content = "Anda tidak ingin main-main dengan saya! Pergi main mata dengan orang lain!",
  ui_story_5004_50040701_59_dialog_content = "Minggir, PlayerName! Aku akan mengunci cewek ini di kursi belakang!",
  ui_story_5004_50040701_60_dialog_content = "Waktu yang tepat. Aku sedang mencari untuk mengeluarkan beberapa uap...",
  ui_story_5004_50040701_61_dialog_content = "Heh, sudah lama sejak aku melihatmu. Tidak mengira Anda akan berada di sekitar orang-orang biasa ini, <color=#FFB400>Smokey</color>.",
  ui_story_5004_50040701_62_dialog_content = "Anda masih menyebut diri Anda seorang bangsawan?",
  ui_story_5004_50040701_63_dialog_content = "Kamu siapa? Apa bagi Anda jika saya seorang bangsawan atau tidak?",
  ui_story_5004_50040701_64_dialog_content = "Apa, kamu tidak ingat aku?!",
  ui_story_5004_50040701_65_dialog_content = "Hei, aku belum selesai denganmu...",
  ui_story_5004_50040701_66_dialog_content = "Diam, kamu!",
  ui_story_5004_50040701_67_dialog_content = "Lihat lebih dekat kali ini!",
  ui_story_5004_50040701_68_dialog_content = "Tidak tahu siapa kamu, jadi menjauhlah dariku.",
  ui_story_5004_50040701_69_dialog_content = "aku <color=#FFB400>Genevieve</color>! <color=#FFB400>Genevieve</color> dari <color=#FFB400>Vronskii</color>!",
  ui_story_5004_50040701_70_dialog_content = "Tunggu, itu membunyikan bel ...",
  ui_story_5004_50040701_71_dialog_content = "Petyaburg...",
  ui_story_5004_50040701_72_dialog_content = "Benar, Petyaburg!",
  ui_story_5004_50040701_73_dialog_content = "<size=30>PlayerName, ada apa dengan keduanya...</size>",
  ui_story_5004_50040701_74_dialog_content = "<size=30>Bagaimana saya tahu?</size>",
  ui_story_5004_50040701_75_dialog_content = "Aku ingat sekarang! Genevieve! Anda telah tumbuh jauh lebih tinggi.",
  ui_story_5004_50040701_76_dialog_content = "Apa? Betapa menghina Anda!",
  ui_story_5004_50040701_77_dialog_content = "Saya dan keluarga saya dihina karena Anda!",
  ui_story_5004_50040701_78_dialog_content = "Apa yang kau bicarakan? Aku benar-benar tidak ingat itu.",
  ui_story_5004_50040701_79_dialog_content = "Aku semakin sakit kepala sekarang karena mencoba mengingat.",
  ui_story_5004_50040701_80_dialog_content = "Ah, aku kehilangan ingatanku. Apakah itu tidak apa apa?",
  ui_story_5004_50040701_81_dialog_content = "Yah, aku harus pergi. Selamat tinggal, Nona Genevieve yang sekarang cantik!",
  ui_story_5004_50040701_82_dialog_content = "Anda tidak akan kemana-mana!",
  ui_story_5004_50040701_83_dialog_content = "...",
  ui_story_5004_50040701_84_dialog_content = "Kenapa kau menatapku begitu?",
  ui_story_5004_50040701_85_dialog_content = "Hei, berhenti menempel padaku! Saya tidak pernah memukul seorang wanita tetapi saya akan memikirkan sesuatu yang lain.",
  ui_story_5004_50040701_86_dialog_content = "Tidak pantas orang lain melihat kita seperti ini.",
  ui_story_5004_50040701_87_dialog_content = "Saya tidak ingin siapa pun mengambilnya dengan cara yang salah!",
  ui_story_5004_50040701_88_dialog_content = "Smokey!",
  ui_story_5004_50040701_89_dialog_content = "Aku tidak akan pernah memaafkanmu!",
  ui_story_5004_50040701_90_dialog_content = "Saya merasakan pertarungan akan datang, PlayerName.",
  ui_story_5004_50040701_91_dialog_content = "Mengapa Anda menantikan itu?",
  ui_story_5004_50040701_92_dialog_content = "Anda tidak mengerti. Berkelahi adalah cara penting untuk berkomunikasi dan membuktikan diri di Rediesel Wrench.",
  ui_story_5004_50040701_93_dialog_content = "Terserah... Saya pikir gadis pirang akan menang.",
  ui_story_5004_50040701_94_dialog_content = "Mengapa Anda berpikir demikian?",
  ui_story_5004_50040701_95_dialog_content = "firasat Caelestit.",
  ui_story_5004_50040701_96_dialog_content = "Anda keluar dari liga Anda di sini. Lihatlah Smokey, gadis berambut perak.",
  ui_story_5004_50040701_97_dialog_content = "Dia memiliki gerak kaki yang baik dan tidak menunjukkan cacat dalam gerakannya.",
  ui_story_5004_50040701_98_dialog_content = "Matanya penuh percaya diri, jadi ini bukan pertama kalinya dia berkeliling blok.",
  ui_story_5004_50040701_99_dialog_content = "Sementara si pirang di sana, dia mungkin agresif, tetapi tidak bisa mengendalikan emosimu berarti kamu tidak bisa mengendalikan kekuatanmu.",
  ui_story_5004_50040701_100_dialog_content = "Saya pikir dia masih memiliki jalan panjang untuk menguasai Luminatics-nya.",
  ui_story_5004_50040701_101_dialog_content = "Itu dalam... Dari mana kau belajar itu?",
  ui_story_5004_50040701_102_dialog_content = "Wooga!",
  ui_story_5004_50040701_103_dialog_content = "Keluar dari jalanku!",
  ui_story_5004_50040701_103X_dialog_content = "Ada Eclipsites di sini juga?",
  ui_story_5004_50040701_103X1_dialog_content = "Tidak ada apa-apa. Anggap saja Eclipsites sebagai makanan khas lokal.",
  ui_story_5004_50040701_104_dialog_content = "Hmm, Genevieve itu mendapatkan satu atau dua langkah.",
  ui_story_5004_50040701_105_dialog_content = "Hei, Eclipsite di belakangmu!",
  ui_story_5004_50040701_106_dialog_content = "Katakanlah, bukankah kamu keamanan, Brock? Anda hanya akan menontonnya?",
  ui_story_5004_50040701_107_dialog_content = "Oh benar, aku lupa!",
  ui_story_5004_50040701_108_dialog_content = "Oke, Anda Eclipsites kotor, waktu untuk mengubur kalian semua di pasir!",
  ui_story_5004_50040701_109_dialog_content = "Maju dengan kecepatan penuh!",
  ui_story_5004_50040701_110_dialog_content = "Itu hanya butuh satu detik!",
  ui_story_5004_50040701_111_dialog_content = "Tentu saja, apa lagi yang Anda harapkan?",
  ui_story_5004_50040701_112_dialog_content = "Kau baik-baik saja?",
  ui_story_5004_50040701_113_dialog_content = "Siapa yang menyuruhmu ikut campur?",
  ui_story_5004_50040701_114_dialog_content = "Smokey lolos karena kamu!",
  ui_story_5004_50040701_115_dialog_content = "Maaf!",
  ui_story_5004_50040701_116_dialog_content = "Jangan bicara padaku! Aku sangat marah sekarang...",
  ui_story_5004_50040701_117_dialog_content = "Aku harus mencari tahu apa yang dia lakukan dan menggagalkan plotnya sepenuhnya!",
  ui_story_5004_50040701_118_dialog_content = "Terima kasih dan selamat tinggal!",
  ui_story_5004_50040701_119_dialog_content = "Dia sudah pergi.",
  ui_story_5004_50040701_120_dialog_content = "Lihat itu, PlayerName? Masalah antara dua wanita jauh lebih mengerikan daripada Eclipsite mana pun.",
  ui_story_5004_50040701_121_dialog_content = "Saya sarankan Anda tidak melibatkan diri.",
  ui_story_5004_50040701_122_dialog_content = "Bahkan tidak pernah mempertimbangkannya.",
  ui_story_5004_50040701_123_dialog_content = "Enak!",
  ui_story_5004_50040701_124_dialog_content = "Anda mendapatkannya di sisi bibir Anda. Biarkan aku menghapusnya.",
  ui_story_5004_50040701_125_dialog_content = "Oh, terima kasih.",
  ui_story_5004_50040701_126_dialog_content = "Saya tidak bisa mengendalikan diri, ruang makan di Illumina tidak pernah menyajikan hal sebaik ini!",
  ui_story_5004_50040701_127_dialog_content = "Terutama ketika wanita dengan tangan gemetar akan menjatuhkan kembali daging yang sudah langka ke dalam panci saat dia mengambilkan makanan untukku.",
  ui_story_5004_50040701_128_dialog_content = "Saya masih tumbuh, Anda tahu!",
  ui_story_5004_50040701_129_dialog_content = "Tidak heran Anda praktis tinggal di kafe ketika Anda belajar di Lumopolis.",
  ui_story_5004_50040701_132_dialog_content = "Anda tidak perlu menunggu kami, Fleur. Bergabunglah dengan kami, Anda adalah teman kami.",
  ui_story_5004_50040701_133_dialog_content = "Saya tidak bisa melakukan itu. Anda tamu kami dan itu tugas saya untuk menunggu Anda.",
  ui_story_5004_50040701_134_dialog_content = "Namun…",
  ui_story_5004_50040701_135_dialog_content = "Jangan pedulikan dia, PlayerName.",
  ui_story_5004_50040701_136_dialog_content = "Semua orang tahu itu sifatnya, dan dia senang akan hal itu.",
  ui_story_5004_50040701_137_dialog_content = "Apa yang ingin kamu minum, Brock?",
  ui_story_5004_50040701_138_dialog_content = "Sesuatu yang sedingin es!",
  ui_story_5004_50040701_139_dialog_content = "Mengerti. Segera datang.",
  ui_story_5004_50040701_140_dialog_content = "...",
  ui_story_5004_50040701_141_dialog_content = "Mengapa wajahmu memerah, PlayerName?",
  ui_story_5004_50040701_142_dialog_content = "Apakah itu? Saya kira tidak demikian...",
  ui_story_5004_50040701_143_dialog_content = "Sepertinya Caelestites juga tidak kebal terhadap efeknya.",
  ui_story_5004_50040701_144_dialog_content = "Imun? Apa yang kau bicarakan?",
  ui_story_5004_50040701_145_dialog_content = "Lebih baik Anda bertanya kepada orang itu secara langsung.",
  ui_story_5004_50040701_146_dialog_content = "Jadi, apa yang terjadi dengan dua wanita dari sore ini?",
  ui_story_5004_50040701_147_dialog_content = "Bagaimana saya tahu? Aku juga tidak mengenal mereka.",
  ui_story_5004_50040701_148_dialog_content = "Ini sangat mencurigakan. Orang yang menendangku jelas sedang mencari sesuatu.",
  ui_story_5004_50040701_149_dialog_content = "Saya harus mengubur kunci mobil di suatu tempat.",
  ui_story_5004_50040701_150_dialog_content = "Tidak ada yang mau mencuri mobil Anda!",
  ui_story_5004_50040701_151_dialog_content = "Orang lain mencari sesuatu? Beryl dan saya bertemu dengan seseorang seperti itu sore ini!",
  ui_story_5004_50040701_152_dialog_content = "Benar, Beril?",
  ui_story_5004_50040701_153_dialog_content = "Ya. Rambut putih keabu-abuan, memakai warna, benar-benar tidak bisa didekati dan sedikit menakutkan...",
  ui_story_5004_50040701_154_dialog_content = "(Kedengarannya seperti orang yang sama.)",
  ui_story_5004_50040701_155_dialog_content = "Tidak sopan cara dia melihat-lihat, PlayerName.",
  ui_story_5004_50040701_156_dialog_content = "Dan dia menginjak istana pasir yang dibangun Beryl selama tiga jam!",
  ui_story_5004_50040701_157_dialog_content = "Tingginya lebih dari 9 kaki dan agung! Ini, ini besar!",
  ui_story_5004_50040701_158_dialog_content = "Tidak apa-apa, dia meminta maaf.",
  ui_story_5004_50040701_159_dialog_content = "Tapi kau menghabiskan sepanjang sore membuat kastil itu, Beryl!",
  ui_story_5004_50040701_160_dialog_content = "Tetap saja, aku senang bisa santai dan tanpa beban seperti ini.",
  ui_story_5004_50040701_161_dialog_content = "Saya merasa kastil itu selalu ada di pikiran saya. Aku bisa melihatnya saat aku memejamkan mata.",
  ui_story_5004_50040701_162_dialog_content = "Jika Raphael menyukainya, saya bisa membangun yang lain besok.",
  ui_story_5004_50040701_163_dialog_content = "Betulkah? Biarkan saya membantu lain kali!",
  ui_story_5004_50040701_164_dialog_content = "Tentu.",
  ui_story_5004_50040701_165_dialog_content = "Kami masih belum tahu siapa itu dan apa motifnya.",
  ui_story_5004_50040701_166_dialog_content = "Jatuhkan saja dan jangan terlalu memikirkannya, Brock.",
  ui_story_5004_50040701_167_dialog_content = "Tapi aku berjanji pada Fleur aku akan melakukan pekerjaan yang bagus untuk mengamankan tempat itu.",
  ui_story_5004_50040701_168_dialog_content = "(Apakah itu sebabnya Anda berlari ke saya pada kesempatan pertama yang Anda dapatkan?)",
  ui_story_5004_50040701_169_dialog_content = "Saya memang meminta Brock untuk datang.",
  ui_story_5004_50040701_170_dialog_content = "Ini minuman Anda dengan es ekstra. Menikmati!",
  ui_story_5004_50040701_171_dialog_content = "Sudah kubilang aku menepati kata-kataku... Ack!",
  ui_story_5004_50040701_172_dialog_content = "Apa-apaan ini?!",
  ui_story_5004_50040701_173_dialog_content = "Maaf, kami tidak memiliki barang-barang yang biasa Anda pakai di sekitar sini, jadi saya menggantinya.",
  ui_story_5004_50040701_174_dialog_content = "Jadi hal seperti apa yang biasa kamu lakukan, Brock? Orang-orang Rediesel Wrench yakin adalah sesuatu yang lain!",
  ui_story_5004_50040701_175_dialog_content = "Yang ini untukmu, PlayerName.",
  ui_story_5004_50040701_176_dialog_content = "Ini adalah sentuhan khusus kami sendiri sebagai sambutan.",
  ui_story_5004_50040701_177_dialog_content = "Istimewa... tidak ada yang beracun di sana, kan?",
  ui_story_5004_50040701_178_dialog_content = "Jangan khawatir, ini bebas racun dan alkohol. Siapapun bisa menikmatinya.",
  ui_story_5004_50040701_X178_dialog_content = "Anda benar-benar bijaksana!",
  ui_story_5004_50040701_179_dialog_content = "Juga, jika Anda setuju, saya ingin mengobrol dengan Anda secara pribadi sesegera mungkin, PlayerName.",
  ui_story_5004_50040701_180_dialog_content = "Aku punya waktu.",
  ui_story_5004_50040701_181_dialog_content = "(Keseimbangan yang luar biasa antara manis dan asam, aroma jeruk mencerahkan seluruh minuman dan menambahkan banyak lapisan ke dalamnya.)",
  ui_story_5004_50040701_182_dialog_content = "(Minuman yang enak dan rumit...)",
  ui_story_5004_50040901_1_dialog_content = "Tidak, harus bangun...",
  ui_story_5004_50040901_2_dialog_content = "Tertidur di tumpukan bagian mekanik lagi. Punggung saya sakit karena berbaring di persneling.",
  ui_story_5004_50040901_3_dialog_content = "Saya mungkin menggambar cetak biru ini tadi malam...",
  ui_story_5004_50040901_4_dialog_content = "Percuma saja. Itu harus di tempat sampah.",
  ui_story_5004_50040901_5_dialog_content = "Kurasa aku harus bergantung pada <color=#FFB400>pengetahuan tentang Caelestit</color>...",
  ui_story_5004_50040901_6_dialog_content = "Robot-robot dari Illumina dan Lumopolis itu tidak cukup. Dengan analisis awal, saya tidak dapat menciptakan apa yang benar-benar saya inginkan.",
  ui_story_5004_50040901_7_dialog_content = "Mandi dulu sebelum janjian dengan PlayerName.",
  ui_story_5004_50040901_8_dialog_content = "Jika saya tidak bisa menyelesaikan Ocean Sovereign, saya tidak akan bisa lepas dari efek <color=#FFB400>sifat khusus</color>.",
  ui_story_5004_50040901_9_dialog_content = "(Saya seharusnya menjadi mekanik biasa untuk Illumina.)",
  ui_story_5004_50040901_10_dialog_content = "(Tetapi karena sifat khusus yang tidak aktif dalam gen saya ...)",
  ui_story_5004_50040901_11_dialog_content = "(Ketika saya masih di sekolah ...)",
  ui_story_5004_50040901_12_dialog_content = "fleur, <size=45>Fleur!</size>",
  ui_story_5004_50040901_13_dialog_content = "Halo! Dan halo juga untukmu!",
  ui_story_5004_50040901_14_dialog_content = "Bisakah Anda menunjukkan cara mengatasi masalah ini, Fleur?",
  ui_story_5004_50040901_15_dialog_content = "Tentu. Jangan ragu untuk bertanya kepada saya.",
  ui_story_5004_50040901_16_dialog_content = "Mengapa Anda mengganggu Fleur yang malang sepanjang waktu?",
  ui_story_5004_50040901_17_dialog_content = "Apakah Anda mencoba untuk pindah ke Fleur?",
  ui_story_5004_50040901_18_dialog_content = "Lalu apa? <size=45>Fleur bukan milikmu!</size>",
  ui_story_5004_50040901_19_dialog_content = "Hei, kalian berhenti menyudutkan Fleur sepanjang hari!",
  ui_story_5004_50040901_20_dialog_content = "Dia tidak tertarik pada kalian. Benar, Fleur?",
  ui_story_5004_50040901_21_dialog_content = "Apa? Apakah Anda suka perempuan atau laki-laki, Fleur? Jawab aku!",
  ui_story_5004_50040901_22_dialog_content = "Saya suka semua orang.",
  ui_story_5004_50040901_23_dialog_content = "Dia memiliki bakat untuk mesin, bekerja keras, dan baik kepada orang-orang.",
  ui_story_5004_50040901_24_dialog_content = "Dia luar biasa.",
  ui_story_5004_50040901_25_dialog_content = "Tapi sifat khusus itu membuatnya sulit untuk berada di dekatnya.",
  ui_story_5004_50040901_26_dialog_content = "Baik itu jantan atau betina, bahkan hewan pun berbondong-bondong mendatanginya.",
  ui_story_5004_50040901_27_dialog_content = "Jangan sebutkan itu <color=#FFB400>kecelakaan</color> menimbulkan banyak korban.",
  ui_story_5004_50040901_28_dialog_content = "Mengapa kita tidak mengirimnya ke yang baru <color=#FFB400>Kota bawah 38</color>? Setidaknya ada lebih sedikit Aurorian di sana...",
  ui_story_5004_50040901_29_dialog_content = "Menang-menang, dia tidak terganggu, dan kami keluar dari masalah.",
  ui_story_5004_50040901_30_dialog_content = "Selamat, Fleur. Anda akan dikirim ke Undercity 38 sebagai spesialis konstruksi.",
  ui_story_5004_50040901_31_dialog_content = "Ini adalah kesempatan seumur hidup dan bukti kepercayaan Illumina pada Anda.",
  ui_story_5004_50040901_32_dialog_content = "Anda akan memiliki banyak ruang untuk menunjukkan apa yang dapat Anda lakukan, dan kami tahu Anda dapat membuat tanda di sana!",
  ui_story_5004_50040901_33_dialog_content = "(Itu benar-benar saat yang menyenangkan, mudah dan tenang.)",
  ui_story_5004_50040901_34_dialog_content = "Istri saya akan datang ke Undercity 38 minggu depan. Kami belum bertemu selama bertahun-tahun!",
  ui_story_5004_50040901_35_dialog_content = "Kita tidak bisa bersama pasangan kita karena pria itu ada di sini. Bahkan putri kami tidak bisa datang!",
  ui_story_5004_50040901_36_dialog_content = "Hewan peliharaan kita terus pergi ke tempatnya!",
  ui_story_5004_50040901_37_dialog_content = "Jauhi dia kecuali jika Anda ingin jatuh di bawah mantranya!",
  ui_story_5004_50040901_38_dialog_content = "Tenang aja. Fleur bukanlah ancaman bagi semua orang.",
  ui_story_5004_50040901_39_dialog_content = "Ha! Semua orang di Illumina tahu tentang <color=#FFB400>kecelakaan</color> dia menyebabkan di sekolah!",
  ui_story_5004_50040901_40_dialog_content = "Orang-orang terluka karena dia! Tidak satu, ada banyak! Mengapa Anda menutupi untuknya?",
  ui_story_5004_50040901_42_dialog_content = "Terima kasih atas kontribusi Anda untuk Undercity 38, Fleur.",
  ui_story_5004_50040901_43_dialog_content = "Tapi sudah saatnya Anda kembali ke Gannon. orang adalah...",
  ui_story_5004_50040901_44_dialog_content = "Tidak apa-apa, saya mengerti.",
  ui_story_5004_50040901_45_dialog_content = "Tapi aku tidak ingin kembali.",
  ui_story_5004_50040901_46_dialog_content = "Saya tidak ingin meninggalkan Undercity 38. Saya memiliki waktu yang bahagia dan tenang di sini.",
  ui_story_5004_50040901_47_dialog_content = "Tidak ada kerumunan orang di sekitar saya, dan saya dapat melakukan penelitian saya dengan tenang.",
  ui_story_5004_50040901_48_dialog_content = "Anda bilang saya akan membuat tanda saya di sini ...",
  ui_story_5004_50040901_49_dialog_content = "...",
  ui_story_5004_50040901_50_dialog_content = "Maaf, tapi sekarang berbeda. Tolong jangan paksa kami untuk membawamu kembali.",
  ui_story_5004_50040901_51_dialog_content = "Apa yang bisa saya lakukan jika kembali?",
  ui_story_5004_50040901_52_dialog_content = "Saya akan dikarantina atau tetap di Departemen Riset sebagai subjek penelitian?",
  ui_story_5004_50040901_53_dialog_content = "Maaf...",
  ui_story_5004_50040901_54_dialog_content = "Kami melakukan semua yang kami bisa.",
  ui_story_5004_50040901_55_dialog_content = "Tapi ada kesempatan sekarang!",
  ui_story_5004_50040901_56_dialog_content = "Selamat datang di Tir' Hotel, Fleur! Saya kira Anda sudah membaca surat itu, bukan?",
  ui_story_5004_50040901_57_dialog_content = "Ya. Saya dapat membantu Anda dengan Penguasa Laut, tetapi apakah Anda benar-benar mampu menghilangkan sifat khusus saya?",
  ui_story_5004_50040901_58_dialog_content = "Jangan khawatir, saya menemukan informasi di reruntuhan. Jika legenda itu benar, maka ya, saya benar.",
  ui_story_5004_50040901_59_dialog_content = "Ah, pemuda ini pasti Fleur. Anda akan menjadi manajer lobi dan bertanggung jawab atas persiapan Ocean Sovereign.",
  ui_story_5004_50040901_59X1_dialog_content = "Mengerti. Saya akan mulai sekarang.",
  ui_story_5004_50040901_59X2_dialog_content = "Kami memulai dengan baik. Oh, apa itu tentang legenda yang baru saja Anda sebutkan?",
  ui_story_5004_50040901_59X3_dialog_content = "Saya membuat itu. Omong-omong, selama saya mendapatkannya di sini, apa bedanya, bukan?",
  ui_story_5004_50040901_59X4_dialog_content = "Hehe, tentu saja. Selama Anda mendapatkan semua orang di daftar ...",
  ui_story_5004_50040901_59X5_dialog_content = "Penguasa Laut... Aku akan memanfaatkan kesempatan ini.",
  ui_story_5004_50040901_60_dialog_content = "Saya siap...",
  ui_story_5004_50040901_61_dialog_content = "Pergi, Fleur!",
  ui_story_5004_50040901_62_dialog_content = "Fleur!",
  ui_story_5004_50040901_63_dialog_content = "<size=45>Pak Fleur!</size>",
  ui_story_5004_50040901_64_dialog_content = "Pagi semuanya.",
  ui_story_5004_50040901_65_dialog_content = "Baumu sangat harum, Tn. Fleur!",
  ui_story_5004_50040901_66_dialog_content = "Apakah Anda di kamar mandi? Aku mendengar air mengalir!",
  ui_story_5004_50040901_67_dialog_content = "Oh, eh, keberatan memberi jalan untukku?",
  ui_story_5004_50040901_68_dialog_content = "Bolehkah aku masuk ke kamarmu?",
  ui_story_5004_50040901_69_dialog_content = "Maaf, saya lebih suka semua bagian mekanis di kamar saya tetap berada di tempatnya...",
  ui_story_5004_50040901_70_dialog_content = "Fleury, instruktur yoga bilang aku bisa berolahraga denganmu di kelas jika aku mendaftar. Benarkah itu?",
  ui_story_5004_50040901_71_dialog_content = "Betulkah? Itu terdengar seperti penipuan ...",
  ui_story_5004_50040901_72_dialog_content = "Semuanya, harap tenang, terima kasih. Aku punya seseorang untuk dilihat, jadi tolong beri jalan...",
  ui_story_5004_50040901_73_dialog_content = "<anim type=Shake><size=45>Apa?</size></anim>",
  ui_story_5004_50040901_74_dialog_content = "Siapa ini? Bajingan kecil yang licik!",
  ui_story_5004_50040901_75_dialog_content = "Tn. Fleur, bukankah lebih baik bergaul dengan kita?",
  ui_story_5004_50040901_76_dialog_content = "(Sialan, sepertinya PlayerName harus menunggu.)",
  ui_story_5004_50041001_1_dialog_content = "Saya mengerti. Saya mengerti sekarang.",
  ui_story_5004_50041001_2_dialog_content = "Terima kasih atas kesabaran dan pengampunan Anda. Saya sangat menghargai itu!",
  ui_story_5004_50041001_3_dialog_content = "Jangan menyebutkannya. Tapi Fleur, apakah Anda benar-benar akan membuat robot sendiri?",
  ui_story_5004_50041001_4_dialog_content = "Ya, itu keinginan saya.",
  ui_story_5004_50041001_5_dialog_content = "<color=#e8d9bb>Tok, tok.</color>",
  ui_story_5004_50041001_6_dialog_content = "Bisakah saya masuk, PlayerName?",
  ui_story_5004_50041001_7_dialog_content = "Tentu.",
  ui_story_5004_50041001_8_dialog_content = "Oh, Fleur juga ada di sini.",
  ui_story_5004_50041001_9_dialog_content = "Anda adalah kepala Komite Kedaulatan Laut. Bermalas-malasan adalah hal terakhir bagimu, bukan?",
  ui_story_5004_50041001_10_dialog_content = "aku tidak. Saya di sini hanya untuk meminta pendapat PlayerName tentang beberapa masalah desain.",
  ui_story_5004_50041001_11_dialog_content = "Aku harus kembali dan memeriksa rencana lagi. Selamat tinggal.",
  ui_story_5004_50041001_12_dialog_content = "Ada keputusan untuk bergabung dengan Ocean Sovereign, PlayerName? Hadiahnya termasuk...",
  ui_story_5004_50041001_13_dialog_content = "Kami masuk.",
  ui_story_5004_50041001_14_dialog_content = "Apa?",
  ui_story_5004_50041001_15_dialog_content = "Masalah apapun? Saya mendiskusikannya dengan teman-teman saya, dan mereka...",
  ui_story_5004_50041001_16_dialog_content = "Tidak terduga. Saya pikir Anda akan memakan waktu lebih lama dari ini, bukan?",
  ui_story_5004_50041001_17_dialog_content = "Bagaimanapun, ini adalah festival. Apa yang harus dipikirkan?",
  ui_story_5004_50041001_18_dialog_content = "Jadi, Anda tidak takut itu mungkin konspirasi, PlayerName?",
  ui_story_5004_50041001_19_dialog_content = "Konspirasi? Lalu kita keluar!",
  ui_story_5004_50041001_20_dialog_content = "Hahaha, betapa menggemaskan. Bahkan aku, seorang anggota True Order, tidak akan mengungkapkannya secara terbuka jika itu adalah konspirasi!",
  ui_story_5004_50041001_21_dialog_content = "Itu pujian, karena Anda membuat keputusan yang tepat, bukan?",
  ui_story_5004_50041001_22_dialog_content = "(Mengapa semua orang dengan The True Order begitu aneh?)",
  ui_story_5004_50041001_23_dialog_content = "Karena Anda masuk, tolong tanda tangani kertas ini.",
  ui_story_5004_50041001_24_dialog_content = "Di sini, gunakan pena ini.",
  ui_story_5004_50041001_25_dialog_content = "Hei, itu sangat halus.",
  ui_story_5004_50041001_26_dialog_content = "Dan dingin, seperti es.",
  ui_story_5004_50041001_27_dialog_content = "Itu terbuat dari kristal yang sangat langka, terlihat sangat mahal, bukan?",
  ui_story_5004_50041001_28_dialog_content = "Dan memang, itu dihargai setengah dari harga hotel ini.",
  ui_story_5004_50041001_29_dialog_content = "Anda dapat mengambilnya sebagai hadiah, PlayerName. Anda tertarik, bukan?",
  ui_story_5004_50041001_30_dialog_content = "Tidak, aku tidak mungkin menerima hadiah yang begitu berharga!",
  ui_story_5004_50041001_31_dialog_content = "Tidak apa-apa, itu digali dari reruntuhan.",
  ui_story_5004_50041001_32_dialog_content = "Itulah Ordo Sejati yang saya tahu, menggali reruntuhan di mana-mana.",
  ui_story_5004_50041001_33_dialog_content = "Bagaimana menyanjung. Oh, saya mendengar panel kontrol untuk Colossus Anda menyerupai... piano?",
  ui_story_5004_50041001_34_dialog_content = "Apakah saya memiliki keberuntungan untuk melihatnya? Saya seorang musisi, dan Anda memiliki piano yang tidak biasa, bukan?",
  ui_story_5004_50041001_35_dialog_content = "Tur dapat diatur. Ini, kertasnya sudah ditandatangani!",
  ui_story_5004_50041001_36_dialog_content = "Saya mengerti. Oke, sudah siap, Anda sekarang resmi menjadi kontestan!",
  ui_story_5004_50041001_37_dialog_content = "Pertandingan pertama akan berlangsung sore ini. Anda harus istirahat sebelum itu.",
  ui_story_5004_50041001_38_dialog_content = "Saya menantikan kesuksesan Anda.",
  ui_story_5004_50041001_39_dialog_content = "Hei, itu terlalu halus, bukan?",
  ui_story_5004_50041001_40_dialog_content = "Apakah rasa bersalah yang saya rasakan saat ini?",
  ui_story_5004_50041001_X40_dialog_content = "Hmm... tidak.",
  ui_story_5004_50041001_X40X1_dialog_content = "Jadi, inilah kami, termasuk orang Caelestit.",
  ui_story_5004_50041001_X40X2_dialog_content = "Tidak menyangka PlayerName menandatangani dengan pena orang itu dengan begitu mudah...",
  ui_story_5004_50041001_X40X3_dialog_content = "Bertanya-tanya apa yang orang itu rencanakan ... Sudahlah, Eclipsites itu tidak akan berarti apa-apa.",
  ui_story_5004_50041001_41_dialog_content = "Paruh pertama <color=#FFB400>Pergerakan</color>, cukup mudah.",
  ui_story_5004_50041001_42_dialog_content = "PlayerName benar-benar sosok yang menarik.",
  ui_story_5004_50041101_1_dialog_content = "<color=#e8d9bb>Sementara itu...</color>",
  ui_story_5004_50041101_2_dialog_content = "Sangat bagus, Anda telah menangkap kuncinya.",
  ui_story_5004_50041101_3_dialog_content = "Anda akan selangkah lebih dekat dengan dewa dengan kekuatan Caelestit.",
  ui_story_5004_50041101_4_dialog_content = "Saya tunjukkan jalannya, Anda memberi saya buahnya.",
  ui_story_5004_50041101_5_dialog_content = "Anda tidak lagi harus melayani massa yang tidak bersih... Anda akan mencapai puncak musik yang sebenarnya.",
  ui_story_5004_50041101_6_dialog_content = "Mengerti. Ini persis apa yang saya inginkan!",
  ui_story_5004_50041101_7_dialog_content = "Aneh setiap kali aku melihatmu bergumam pada dirimu sendiri. Jadi apa yang suara di kepalamu katakan kali ini?",
  ui_story_5004_50041101_8_dialog_content = "Saya telah memberikan Anda paruh pertama Gerakan, karena Anda memasukkan semua orang dalam daftar yang terlibat dalam kontes, seperti yang kita sepakati.",
  ui_story_5004_50041101_9_dialog_content = "Apakah suara itu mengganggu Anda tentang mendapatkan babak kedua?",
  ui_story_5004_50041101_10_dialog_content = "Eclipsites sedang menggali, tetapi tidak ada gunanya bahkan jika Anda mendapatkannya.",
  ui_story_5004_50041101_11_dialog_content = "Anda masih membutuhkan kekuatan seorang Caelestit untuk membangunkannya.",
  ui_story_5004_50041101_12_dialog_content = "Itu bukan urusan Anda.",
  ui_story_5004_50041101_13_dialog_content = "Agar kita jelas, tujuan saya adalah Gerakan Ilahi yang lengkap, bukan bersekongkol dengan Anda Eclipsites.",
  ui_story_5004_50041101_14_dialog_content = "Ini terjadi hanya karena Anda memberikan babak pertama dan menjanjikan saya babak kedua.",
  ui_story_5004_50041101_15_dialog_content = "Itu membuat ini menjadi kepentingan bersama, bukan kemitraan permanen, mengerti?",
  ui_story_5004_50041101_15X_dialog_content = "Omong-omong, Eclipsites yang kamu kirim dimusnahkan oleh PlayerName dan para Aurorian itu.",
  ui_story_5004_50041101_16_dialog_content = "Tikus yang tidak berharga.",
  ui_story_5004_50041101_17_dialog_content = "Anda keji, Aurorian kotor!",
  ui_story_5004_50041101_18_dialog_content = "Santai saja.",
  ui_story_5004_50041101_19_dialog_content = "Anda tidak ingin lubang tikus Anda ditemukan dan dirusak, bukan?",
  ui_story_5004_50041101_20_dialog_content = "Apakah Anda sendiri tidak punya rencana konyol? Seperti menggambar turis dengan Ocean Sovereign, lalu menjajakan foto baju renang untuk mendanai usaha Anda, bukan?",
  ui_story_5004_50041101_21_dialog_content = "Penipuan yang tidak masuk akal itu muncul pada turis. Pelajaran yoga, yang lucu.",
  ui_story_5004_50041101_22_dialog_content = "Tapi saya cukup yakin sebagian besar uang masih disalurkan kembali ke bos yang sebenarnya, bukan?",
  ui_story_5004_50041101_23_dialog_content = "Sebagai boneka, Anda hanyalah alat.",
  ui_story_5004_50041101_24_dialog_content = "Saya bertanya-tanya bagaimana tanpa ampun sesama Eclipsites Anda akan mengejek Anda karena bekerja untuk seorang Aurorian.",
  ui_story_5004_50041101_25_dialog_content = "Beraninya kamu! Kita...",
  ui_story_5004_50041101_26_dialog_content = "Tuan Prini!",
  ui_story_5004_50041101_27_dialog_content = "Ini belum berakhir, Anda akan lihat!",
  ui_story_5004_50041101_28_dialog_content = "Lihat tamu keluar, Tuan Thaddius.",
  ui_story_5004_50041101_29_dialog_content = "Silakan, lewat sini.",
  ui_story_5004_50041101_30_dialog_content = "Perkenankan saya untuk memberi tahu Anda tentang kursus yoga terbaru saya saat saya mengantar Anda pulang.",
  ui_story_5004_50041101_31_dialog_content = "Kesempurnaan adalah keadaan pikiran. Keanggunan adalah cara hidup. Toleransi adalah pola pikir. Kehidupan yang indah dimulai dengan yoga.",
  ui_story_5004_50041101_32_dialog_content = "Yoga adalah perjalanan Anda dari duniawi menjadi luar biasa.",
  ui_story_5004_50041101_33_dialog_content = "Yoga adalah seni spiritual transendensi.",
  ui_story_5004_50041101_34_dialog_content = "...",
  ui_story_5004_50041201_1_dialog_content = "Apakah ini situs kompetisi?",
  ui_story_5004_50041201_2_dialog_content = "Stand wasit, net... Pada dasarnya cocok dengan deskripsi di arsip Soroz.",
  ui_story_5004_50041201_2X1_dialog_content = "Eh, yang di sana itu apa?",
  ui_story_5004_50041201_2X2_dialog_content = "Jangan pedulikan itu. Ini hanya perangkat kontrol kerusakan biasa.",
  ui_story_5004_50041201_2X3_dialog_content = "Ini untuk mencegah Anda merusak perlengkapan di sekitarnya dalam panasnya pertempuran.",
  ui_story_5004_50041201_2X4_dialog_content = "(Pertempuran? Saya pikir ini adalah permainan bola voli?)",
  ui_story_5004_50041201_2X5_dialog_content = "Fiuh, selesai.",
  ui_story_5004_50041201_3_dialog_content = "Oke, wasit juga dalam posisi.",
  ui_story_5004_50041201_4_dialog_content = "Selamat datang di pertandingan bola voli Ocean Sovereign perdana, ujian kekuatan dan keberanian!",
  ui_story_5004_50041201_5_dialog_content = "Di sebelah kanan saya adalah tim yang dipimpin oleh PlayerName.",
  ui_story_5004_50041201_6_dialog_content = "Hei, Fleur, kamu bersama PlayerName, bukan?",
  ui_story_5004_50041201_7_dialog_content = "Fleur di sini juga?",
  ui_story_5004_50041201_8_dialog_content = "Saya sudah lama tidak berolahraga dengan Brock, dan Bonacie telah mendorong saya.",
  ui_story_5004_50041201_9_dialog_content = "Tapi orang banyak mungkin akan lepas kendali dengan dia di sini...",
  ui_story_5004_50041201_10_dialog_content = "Fleur!",
  ui_story_5004_50041201_11_dialog_content = "tidak menyenangkan!",
  ui_story_5004_50041201_12_dialog_content = "Aku pikir juga begitu...",
  ui_story_5004_50041201_13_dialog_content = "Aku bukan yang terbaik dalam olahraga...",
  ui_story_5004_50041201_14_dialog_content = "Jangan khawatir, PlayerName. Saya sangat baik di bola voli!",
  ui_story_5004_50041201_15_dialog_content = "Benar, Vice sangat baik dalam pendidikan jasmani dan olahraga di sekolah.",
  ui_story_5004_50041201_16_dialog_content = "Mereka tidak memanggilnya <color=#FFB400>gadis besi</color> untuk apa-apa.",
  ui_story_5004_50041201_17_dialog_content = "Anda dapat yakin, PlayerName. Kami punya ini.",
  ui_story_5004_50041201_18_dialog_content = "(Ada apa dengan sekolah Lumopolis dan nama panggilan aneh??)",
  ui_story_5004_50041201_19_dialog_content = "Betulkah? Itu bagus kalau begitu. Tunjukkan pada kami apa yang Anda dapatkan, Vice!",
  ui_story_5004_50041201_20_dialog_content = "Hanya keberuntungan saya, saya di tim Anda.",
  ui_story_5004_50041201_21_dialog_content = "Hei, kamu yang kemarin... Kamu juga mendaftar untuk ini?",
  ui_story_5004_50041201_22_dialog_content = "Dia gadis yang merusak istana pasir Beryl!",
  ui_story_5004_50041201_23_dialog_content = "Terus? Saya tidak bisa bergabung? Bonacie mengundang saya!",
  ui_story_5004_50041201_24_dialog_content = "Selain itu, nama saya Smokey, dan saya sudah meminta maaf untuk istana pasir.",
  ui_story_5004_50041201_25_dialog_content = "Mari kita tidak berkelahi. Kami berada di tim yang sama sekarang. Kami harus bekerja sama dan menang.",
  ui_story_5004_50041201_26_dialog_content = "Apakah itu gadis jahat yang kamu sebutkan kemarin? Sepertinya dia tidak tahu cara bermain bagus ...",
  ui_story_5004_50041201_27_dialog_content = "Ya. Tetapi <color=#FFB400>yang lain</color> Saya sebutkan bahkan lebih sulit untuk bergaul.",
  ui_story_5004_50041201_28_dialog_content = "Di sebelah kiri saya adalah Genevieve dan penggemar setianya!",
  ui_story_5004_50041201_29_dialog_content = "Hmph!",
  ui_story_5004_50041201_30_dialog_content = "Itu dia!",
  ui_story_5004_50041201_31_dialog_content = "<anim type=Shake><size=45>Hore, hore, hore!</size></anim>",
  ui_story_5004_50041201_32_dialog_content = "Heh, lihat itu, Smokey?",
  ui_story_5004_50041201_33_dialog_content = "Seorang bangsawan sejati dicintai oleh orang-orang biasa ke mana pun dia pergi.",
  ui_story_5004_50041201_34_dialog_content = "Mereka mengakui kedudukan saya yang lebih tinggi karena karakter mulia saya dan tunduk pada otoritas saya!",
  ui_story_5004_50041201_35_dialog_content = "Itu adalah sesuatu yang tidak akan pernah kamu mengerti, Smokey!",
  ui_story_5004_50041201_36_dialog_content = "Baik, baik, apa pun.",
  ui_story_5004_50041201_37_dialog_content = "Siapa yang mau memahami omong kosong membosankan semacam itu.",
  ui_story_5004_50041201_38_dialog_content = "Hei, jangan menahan diri, kalian. Mari kita mulai!",
  ui_story_5004_50041201_39_dialog_content = "Apakah Anda mengejek? Saya akan menunjukkan kepada Anda ...",
  ui_story_5004_50041201_40_dialog_content = "Tunggu, permainannya bahkan belum dimulai!",
  ui_story_5004_50041201_41_dialog_content = "Cih.",
  ui_story_5004_50041201_42_dialog_content = "Wow, refleks yang luar biasa!",
  ui_story_5004_50041201_43_dialog_content = "!!!",
  ui_story_5004_50041201_44_dialog_content = "(Bola mengarah lurus ke arahku setelah Smokey menghindar.)",
  ui_story_5004_50041201_45_dialog_content = "(Meskipun ini hanya permainan bola voli, pada saat itulah saya benar-benar berharap saya memiliki kekuatan tempur.)",
  ui_story_5004_50041201_46_dialog_content = "(Lonjakan pembunuh itu lebih menakutkan daripada menghadapi Eclipsites secara langsung.)",
  ui_story_5004_50041201_47_dialog_content = "(Saya memejamkan mata saat hidup saya berkelebat dalam pikiran saya.)",
  ui_story_5004_50041201_48_dialog_content = "(Mudah-mudahan, Vice bisa mengeluarkan saya dari laut sesegera mungkin.)",
  ui_story_5004_50041201_49_dialog_content = "Penasaran seperti apa rasanya air laut?",
  ui_story_5004_50041201_50_dialog_content = "PlayerName!",
  ui_story_5004_50041201_51_dialog_content = "Vice, kau baik-baik saja?",
  ui_story_5004_50041201_52_dialog_content = "Saya baik-baik saja, meskipun itu hampir membuat saya keluar dari batas.",
  ui_story_5004_50041201_53_dialog_content = "Hei, permainan belum dimulai. Itu melanggar aturan, Genevieve!",
  ui_story_5004_50041201_54_dialog_content = "PlayerName, Anda membaca manual yang saya berikan, bukan?",
  ui_story_5004_50041201_55_dialog_content = "Siapa yang punya waktu untuk membaca buku tebal yang penuh dengan iklan sponsor?",
  ui_story_5004_50041201_56_dialog_content = "Kalau begitu jangan salahkan aku.",
  ui_story_5004_50041201_57_dialog_content = "Ayo! Tunjukkan semua yang Anda miliki ke surga!",
  ui_story_5004_50041201_58_dialog_content = "(Betapa naifnya saya untuk berpikir bahwa ini adalah permainan bola voli yang saya tahu.)",
  ui_story_5004_50041201_59_dialog_content = "(Ini adalah pertempuran pantai penuh.)",
  ui_story_5004_50041202_1_dialog_content = "Saya belum selesai...",
  ui_story_5004_50041202_2_dialog_content = "Hanya ini kemampuanmu?",
  ui_story_5004_50041202_3_dialog_content = "Maaf, PlayerName. Saya akan membawa Moon Cocoon jika saya tahu ...",
  ui_story_5004_50041202_4_dialog_content = "Tidak masalah. Moon Cocoon hanya akan menusuk bolanya. Kami masih punya Brock dan yang lainnya. Kalian simpan kekuatanmu.",
  ui_story_5004_50041202_5_dialog_content = "Hei kalian, masukkan beberapa otot ke dalamnya!",
  ui_story_5004_50041202_6_dialog_content = "Diam di sana!",
  ui_story_5004_50041202_7_dialog_content = "Hei, perhatikan bola!",
  ui_story_5004_50041202_8_dialog_content = "Terima kasih, Brok!",
  ui_story_5004_50041202_9_dialog_content = "Kumpulkan kembali dan berikan bola kepada Genevieve!",
  ui_story_5004_50041202_10_dialog_content = "<size=45>Benar!</size>",
  ui_story_5004_50041202_11_dialog_content = "Genevieve mengabaikanku. Apa aku bukan ancaman baginya?",
  ui_story_5004_50041202_12_dialog_content = "Ketika situasinya seburuk ini, saatnya untuk mengeluarkan <color=#FFB400>senjata besar</color>!",
  ui_story_5004_50041202_13_dialog_content = "Tunggu, apa yang baru saja kamu lakukan?",
  ui_story_5004_50041202_14_dialog_content = "Apakah itu <color=#FFB400>lengan mekanik</color>?",
  ui_story_5004_50041202_15_dialog_content = "Heh, tidak, itu jelas hanya <color=#FFB400>tangan saya</color>.",
  ui_story_5004_50041202_16_dialog_content = "Ini disebut Doom RX100. Saya membuatnya dengan Tiny One, dan saya memastikan untuk meningkatkan daya tiga kali!",
  ui_story_5004_50041202_17_dialog_content = "Doom, Anda menyebutnya? Bukankah itu nama lengan robot Jona?",
  ui_story_5004_50041202_18_dialog_content = "Satu-satunya perbedaan adalah merah di kepalan tangan. Bagaimana itu bertenaga tiga kali lipat??",
  ui_story_5004_50041202_19_dialog_content = "Tangan kananku terbakar dalam nyala api kemenangan!",
  ui_story_5004_50041202_20_dialog_content = "Berhenti bermain! Tidak mungkin lengan itu akan bekerja!",
  ui_story_5004_50041202_21_dialog_content = "Keakuratan dan kekuatan ciptaan saya tidak akan kalah dari siapa pun!",
  ui_story_5004_50041202_22_dialog_content = "Tentu saja, itu mekanis!",
  ui_story_5004_50041202_23_dialog_content = "Ini sangat kuat, dapat menjatuhkan target sejauh belasan kaki tanpa bola.",
  ui_story_5004_50041202_24_dialog_content = "Saya sebenarnya khawatir itu mungkin terlalu kuat ...",
  ui_story_5004_50041202_25_dialog_content = "Tentu saja sekali lagi, ini mekanis. Lepaskan sebelum kita didiskualifikasi!",
  ui_story_5004_50041202_26_dialog_content = "Masih tidak pergi? Brock, kamu tidak mengerti ...",
  ui_story_5004_50041202_27_dialog_content = "Awas!",
  ui_story_5004_50041202_28_dialog_content = "Sebuah pembukaan!",
  ui_story_5004_50041202_29_dialog_content = "<color=#e8d9bb>*brak-brak!*</color>",
  ui_story_5004_50041202_30_dialog_content = "Aduh, aduh...",
  ui_story_5004_50041202_31_dialog_content = "Aku sudah selesai... Langit... sangat indah...",
  ui_story_5004_50041202_32_dialog_content = "Brock terlempar tepat ke pasir! Apakah ini benar-benar permainan bola voli biasa?!",
  ui_story_5004_50041202_33_dialog_content = "Permainan pertama selesai. Waktu untuk istirahat singkat.",
  ui_story_5004_50041202_34_dialog_content = "Silakan menikmati kata dari sponsor kami selama istirahat!",
  ui_story_5004_50041202_X33_dialog_content = "3",
  ui_story_5004_50041202_X34_dialog_content = "2",
  ui_story_5004_50041202_X35_dialog_content = "1",
  ui_story_5004_50041202_35_dialog_content = "Izinkan kami untuk memperkenalkan paket musiman terpanas dari Cloudrover Guild.",
  ui_story_5004_50041202_36_dialog_content = "Ketuk ikon sekarang untuk mendapatkan penawaran spesial eksklusif dari Bonacie, dan 10 bonus Flare Bintang Spesial!",
  ui_story_5004_50041202_37_dialog_content = "Ditambah tangki pistol air tiup yang sempurna untuk pantai!",
  ui_story_5004_50041202_38_dialog_content = "Buruan, persediaan terbatas hanya 5.000... tidak, sisa 1.001 sekarang!",
  ui_story_5004_50041202_39_dialog_content = "Dapatkan satu sekarang sebelum semuanya hilang!",
  ui_story_5004_50041202_40_dialog_content = "Ya ampun, itu terjual habis hanya dalam 10 detik!",
  ui_story_5004_50041202_41_dialog_content = "Nah, pantau terus Bonacie Shopping Network. Sampai jumpa lain waktu!",
  ui_story_5004_50041202_42_dialog_content = "Ini bukan waktunya untuk menonton iklan!",
  ui_story_5004_50041202_43_dialog_content = "Jadi hanya aku dan Smokey yang tersisa??",
  ui_story_5004_50041202_44_dialog_content = "Hei kamu, berhentilah bermalas-malasan dan lakukan sesuatu!",
  ui_story_5004_50041202_45_dialog_content = "Apa? Betulkah? Saya pikir Anda semua akan lebih berguna dari ini.",
  ui_story_5004_50041202_46_dialog_content = "Anda ternyata sekelompok pecundang!",
  ui_story_5004_50041202_47_dialog_content = "Tapi mereka memblokir banyak hit untuk Anda!",
  ui_story_5004_50041202_48_dialog_content = "Tanpa mereka, Anda pasti sudah mati!",
  ui_story_5004_50041202_49_dialog_content = "Apakah Anda benar-benar akan menyerah sekarang dan menyia-nyiakan semua pengorbanan mereka?",
  ui_story_5004_50041202_50_dialog_content = "Oke, fiinn. Tapi bukankah kamu hanya menonton di sela-sela selama ini juga?",
  ui_story_5004_50041202_51_dialog_content = "Yang mengatakan, saya tidak ingin berutang siapa pun.",
  ui_story_5004_50041202_52_dialog_content = "Hanya berdiri kembali dan menonton dengan seksama. Pastikan untuk mengomentari gerakan saya yang luar biasa!",
  ui_story_5004_50041202_53_dialog_content = "Komentar? Oke, saya bisa melakukannya! Apa pun yang diperlukan untuk membuat Anda benar-benar bermain!",
  ui_story_5004_50041202_54_dialog_content = "Kemudian diselesaikan!",
  ui_story_5004_50041202_55_dialog_content = "Eh...",
  ui_story_5004_50041202_56_dialog_content = "Genevieve!",
  ui_story_5004_50041202_57_dialog_content = "Apa itu? Siap mengakui kekalahan?",
  ui_story_5004_50041202_58_dialog_content = "Izinkan saya bertanya kepada Anda, apakah Anda benar-benar peduli untuk dilampaui oleh orang lain?",
  ui_story_5004_50041202_59_dialog_content = "Saya lakukan, benar-benar! Keluarga saya dan harga diri saya tidak akan mentolerir saya kalah dari siapa pun, terutama Anda!",
  ui_story_5004_50041202_60_dialog_content = "Anda merampok saya dari kemuliaan saya. Saya telah mengikuti jejak Anda selama bertahun-tahun.",
  ui_story_5004_50041202_61_dialog_content = "Hanya untuk hari ketika aku akhirnya bisa mengalahkanmu dan melihat rasa sakit dan penyesalan di wajahmu!",
  ui_story_5004_50041202_62_dialog_content = "Yah, itu memalukan.",
  ui_story_5004_50041202_63_dialog_content = "Apa?",
  ui_story_5004_50041202_64_dialog_content = "Karena aku juga benci kalah!",
  ui_story_5004_50041202_65_dialog_content = "Lalu tunjukkan padaku apa yang kamu dapatkan!",
  ui_story_5004_50041202_66_dialog_content = "Mari kita lihat apakah Anda benar-benar bisa mengalahkan saya!",
  ui_story_5004_50041202_67_dialog_content = "<anim type=Shake><size=45>SUPER HELLSTORM SPIKE!</size></anim>",
  ui_story_5004_50041202_68_dialog_content = "!!!",
  ui_story_5004_50041202_69_dialog_content = "Astaga! Bola dilalap api neraka dan meluncur di udara menuju Genevieve!",
  ui_story_5004_50041202_70_dialog_content = "(Saya benar-benar melakukan play-by-play! Ini memalukan...)",
  ui_story_5004_50041202_71_dialog_content = "Genevieve!",
  ui_story_5004_50041202_72_dialog_content = "Penggemar Genevieve telah membentuk lingkaran untuk melindunginya. Apakah ini akan berhasil?",
  ui_story_5004_50041202_73_dialog_content = "Seperti meteorit, bola meluncur ke arah kerumunan!!",
  ui_story_5004_50041202_74_dialog_content = "Genevieve yang malang dan para penggemarnya meledak di luar batas! Bahkan lapangan sekarang memiliki kawah yang dalam di dalamnya!",
  ui_story_5004_50041202_75_dialog_content = "Pemenangnya adalah... PlayerName Tim!",
  ui_story_5004_50041202_76_dialog_content = "Smokey menunjuk ke arah langit, pose kemenangan khasnya! Sungguh lonjakan yang luar biasa!",
  ui_story_5004_50041202_77_dialog_content = "Anda membuat komentator yang layak. Anda mampu menangkap setidaknya setengah dari kehebatan saya dalam komentar Anda.",
  ui_story_5004_50041202_78_dialog_content = "Terima kasih... tapi bukankah berkomentar adalah tugas seseorang yang TIDAK ada dalam permainan??",
  ui_story_5004_50041202_79_dialog_content = "Bagaimanapun, saya harus mengatakan itu benar-benar luar biasa! Anda mendapatkan semuanya dalam satu kesempatan!",
  ui_story_5004_50041202_80_dialog_content = "(Dia monster! Kenapa tiba-tiba aku merasa sedih untuk Genevieve?)",
  ui_story_5004_50041301_1_dialog_content = "Aduh... aku lelah.",
  ui_story_5004_50041301_2_dialog_content = "Sementara saya tidak berbuat banyak, masih melelahkan melarikan diri dari bola ...",
  ui_story_5004_50041301_3_dialog_content = "Saya tidak menyangka akan sehebat ini dan ini baru hari pertama.",
  ui_story_5004_50041301_4_dialog_content = "Genevieve kuat, tetapi Smokey ada di level lain.",
  ui_story_5004_50041301_5_dialog_content = "Ada apa dengan mereka berdua?",
  ui_story_5004_50041301_6_dialog_content = "Beryl dan Raphael pergi memancing sesudahnya. Mereka sepertinya bersenang-senang.",
  ui_story_5004_50041301_7_dialog_content = "Beryl memang terlihat lelah, tapi dia seharusnya baik-baik saja dengan Raphael.",
  ui_story_5004_50041301_8_dialog_content = "Oh, harus berterima kasih kepada Vice karena telah mengambil gambar untukku.",
  ui_story_5004_50041301_9_dialog_content = "Aku mungkin masih berada di Intense Care sekarang jika bukan karena dia.",
  ui_story_5004_50041301_10_dialog_content = "<color=#e8d9bb>Tok, tok.</color>",
  ui_story_5004_50041301_11_dialog_content = "Apakah Anda bangun, PlayerName?",
  ui_story_5004_50041301_12_dialog_content = "Aku datang.",
  ui_story_5004_50041301_13_dialog_content = "Ada apa, Carleen?",
  ui_story_5004_50041301_14_dialog_content = "Saya hanya memeriksa apakah Anda sudah masuk, PlayerName.",
  ui_story_5004_50041301_15_dialog_content = "Tidak sering aku berada di pantai. Saya tidak ingin terkurung di kamar sepanjang malam.",
  ui_story_5004_50041301_16_dialog_content = "Mau jalan-jalan denganku?",
  ui_story_5004_50041301_17_dialog_content = "Tentu, saya akan dengan senang hati melakukannya!",
  ui_story_5004_50041301_19_dialog_content = "Ayo pergi!",
  ui_story_5004_50041301_20_dialog_content = "Oke.",
  ui_story_5004_50041301_21_dialog_content = "Ini terasa sedikit canggung.",
  ui_story_5004_50041301_22_dialog_content = "PlayerName.",
  ui_story_5004_50041301_23_dialog_content = "Apa? Aku di sini!",
  ui_story_5004_50041301_24_dialog_content = "Tentang Aviduz dan Schummer... Aku selalu ingin menunjukkan rasa terima kasihku secara formal.",
  ui_story_5004_50041301_25_dialog_content = "Tidak apa-apa, jangan menyebutkannya.",
  ui_story_5004_50041301_26_dialog_content = "Maksudku, kau dan Vice telah banyak membantuku juga.",
  ui_story_5004_50041301_27_dialog_content = "Ya. Mengingatnya di pantai yang begitu indah...",
  ui_story_5004_50041301_28_dialog_content = "Hampir terasa seperti mimpi, bukan begitu?",
  ui_story_5004_50041301_29_dialog_content = "Aku bahkan tidak yakin aku tidak sedang bermimpi sekarang.",
  ui_story_5004_50041301_30_dialog_content = "Pertama kali saya melihat Anda, saya tidak percaya Anda menghabiskan lebih dari satu dekade sendirian ...",
  ui_story_5004_50041301_31_dialog_content = "Kau Caelestit pertama yang pernah kutemui sampai saat itu... Sungguh menakjubkan bagiku melihat seseorang yang bisa melihat Light Trail.",
  ui_story_5004_50041301_32_dialog_content = "Anda telah membuktikan berkali-kali bahwa Anda adalah pemimpin yang hebat.",
  ui_story_5004_50041301_33_dialog_content = "Anda mungkin tidak dapat melawan Eclipsites secara langsung, tetapi Anda tidak pernah mundur dari mereka.",
  ui_story_5004_50041301_34_dialog_content = "...",
  ui_story_5004_50041301_35_dialog_content = "Bahkan menempatkan diri Anda dalam bahaya bagi orang lain.",
  ui_story_5004_50041301_36_dialog_content = "Dedikasi dan ketidakegoisan Anda untuk menyelamatkan orang lain, bahkan dengan mempertaruhkan nyawa Anda sendiri, adalah bukti karakter Anda yang luar biasa.",
  ui_story_5004_50041301_37_dialog_content = "Keberanian yang Anda tunjukkan lebih terhormat daripada para bangsawan yang hanya peduli pada diri mereka sendiri dalam krisis.",
  ui_story_5004_50041301_38_dialog_content = "...",
  ui_story_5004_50041301_39_dialog_content = "Apakah Anda mendengarkan, PlayerName?",
  ui_story_5004_50041301_40_dialog_content = "Ah, aku sudah bicara terlalu banyak, bukan?",
  ui_story_5004_50041301_41_dialog_content = "Saya mendengarkan dan saya menerima semua yang Anda katakan. Senang berbicara denganmu dalam angin sepoi-sepoi ini.",
  ui_story_5004_50041301_42_dialog_content = "Dan semua yang terlihat...",
  ui_story_5004_50041301_43_dialog_content = "Laut, langit berbintang...",
  ui_story_5004_50041301_44_dialog_content = "Dan…",
  ui_story_5004_50041301_45_dialog_content = "...",
  ui_story_5004_50041301_46_dialog_content = "Semuanya sangat bagus.",
  ui_story_5004_50041301_47_dialog_content = "...",
  ui_story_5004_50041301_48_dialog_content = "...",
  ui_story_5004_50041301_49_dialog_content = "(Saya bisa merasakan perubahan suasana hati yang halus...)",
  ui_story_5004_50041301_50_dialog_content = "Ya memang! Anda tidak akan melihat ini di Lumopolis.",
  ui_story_5004_50041301_51_dialog_content = "Langit malam yang luas biasanya memiliki suasana kemegahan dengan ombak tenang yang menerpa pasir.",
  ui_story_5004_50041301_52_dialog_content = "(Untung Carleen melewatkannya...)",
  ui_story_5004_50041301_53_dialog_content = "Ikan seharusnya terasa enak di laut yang indah ini, bukan begitu?",
  ui_story_5004_50041301_54_dialog_content = "Haruskah kita menangkap ikan dan mencari tahu?",
  ui_story_5004_50041301_55_dialog_content = "Itu ide yang bagus, tapi aku tidak pernah mengambil kelas memasak.",
  ui_story_5004_50041301_56_dialog_content = "Yah, kita bisa membawa ikan itu kembali ke hotel dan meminta koki yang tampak aneh untuk memanggangnya untuk kita.",
  ui_story_5004_50041301_57_dialog_content = "Atau bawa kembali ke Lumopolis. Saya tahu beberapa restoran yang tenang dan beraroma.",
  ui_story_5004_50041301_58_dialog_content = "Luar biasa! Sepakat!",
  ui_story_5004_50041301_59_dialog_content = "Tapi kita mungkin tidak harus melakukannya sekarang. Sudah sangat larut dan mungkin berbahaya untuk masuk ke air...",
  ui_story_5004_50041301_60_dialog_content = "Dan Anda mungkin lelah dari pertandingan bola voli hari ini juga, Carleen.",
  ui_story_5004_50041301_61_dialog_content = "BENAR. Lain kali, kalau begitu.",
  ui_story_5004_50041301_62_dialog_content = "eh...?",
  ui_story_5004_50041301_63_dialog_content = "Kenapa, PlayerName?",
  ui_story_5004_50041301_64_dialog_content = "Saya pikir patung di bawah sana hanya bersinar.",
  ui_story_5004_50041301_65_dialog_content = "Saya tidak melihat itu. Mungkin itu kelelahan di pihak Anda?",
  ui_story_5004_50041301_66_dialog_content = "Atau mungkin Anda masih memiliki Spike Super Hellstorm Smokey di pikiran Anda?",
  ui_story_5004_50041301_67_dialog_content = "Anda ingat apa namanya?",
  ui_story_5004_50041301_68_dialog_content = "Bagaimanapun, saya mungkin hanya melihat sesuatu.",
  ui_story_5004_50041301_69_dialog_content = "Ayo kembali.",
  ui_story_5004_50041301_70_dialog_content = "Keturunan Caelestite... Kekuatan kristal... dan juga \"itu\" masih bekerja...",
  ui_story_5004_50041301_71_dialog_content = "Sekelompok Aurorian bodoh yang menawarkan Lumina dengan sukarela...",
  ui_story_5004_50041301_72_dialog_content = "Lalu…",
  ui_story_5004_50041301_73_dialog_content = "Beril.",
  ui_story_5004_50041301_74_dialog_content = "Giliran saya dalam permainan catur.",
  ui_story_5004_50041501_1_dialog_content = "<color=#e8d9bb>Beberapa hari yang lalu.</color>",
  ui_story_5004_50041501_2_dialog_content = "Sial!",
  ui_story_5004_50041501_3_dialog_content = "<color=#e8d9bb>Smokey merobek surat itu dengan marah dan membuangnya ke samping.</color>",
  ui_story_5004_50041501_4_dialog_content = "Apa anak itu menipuku?",
  ui_story_5004_50041501_5_dialog_content = "Jangan pukul aku. Aku akan membayarmu apa saja!",
  ui_story_5004_50041501_6_dialog_content = "Bukankah kamu mencoba memeras seorang gadis beberapa detik yang lalu?",
  ui_story_5004_50041501_7_dialog_content = "Apa sekarang? Ayo, mari kita lihat keangkuhanmu itu lagi!",
  ui_story_5004_50041501_8_dialog_content = "Anda pikir Anda menjalankan tempat ini?",
  ui_story_5004_50041501_9_dialog_content = "<size=45>Anda pikir saya bercanda</size> ketika saya mengatakan sama sekali tidak melecehkan wanita mana pun?",
  ui_story_5004_50041501_10_dialog_content = "Saya... Saya bukan orang lokal! Tolong kasihanilah aku dan lepaskan aku. Saya tidak akan menyebabkan masalah di sini lagi!",
  ui_story_5004_50041501_11_dialog_content = "Bukan lokal? Oke, poin untuk orisinalitas.",
  ui_story_5004_50041501_12_dialog_content = "Jadi saya akan memberi Anda tiga puluh detik untuk memberi tahu saya dari mana Anda berasal, apa yang Anda lakukan di sini, dan siapa yang mengirim Anda.",
  ui_story_5004_50041501_13_dialog_content = "Jika Anda memberi tahu saya apa yang ingin saya dengar, saya akan membiarkan Anda pergi.",
  ui_story_5004_50041501_14_dialog_content = "Kalau tidak...",
  ui_story_5004_50041501_15_dialog_content = "Aku akan mematahkan jarimu setiap tiga puluh detik. Mengerti?",
  ui_story_5004_50041501_16_dialog_content = "Jari pertama dimulai pada 30, 29...",
  ui_story_5004_50041501_17_dialog_content = "Tidak, biarkan aku pergi! Saya hanya melakukan pengiriman!",
  ui_story_5004_50041501_18_dialog_content = "Aku bukan orang jahat! Anda tidak bisa menyalahkan saya untuk gadis yang memakai begitu sedikit!",
  ui_story_5004_50041501_19_dialog_content = "Aku hanya di sebuah tugas. Tidak ada yang mengirim saya!",
  ui_story_5004_50041501_20_dialog_content = "10, 9, 8...",
  ui_story_5004_50041501_21_dialog_content = "Aku sudah memberitahumu semuanya! Apa lagi yang kamu harapkan dariku?",
  ui_story_5004_50041501_22_dialog_content = "Jepret, retak.",
  ui_story_5004_50041501_23_dialog_content = "<size=45><anim type=Shake>Wow! Tangan saya!</anim></size>",
  ui_story_5004_50041501_24_dialog_content = "Anda gila! Itu dua jari! Apa yang salah denganmu?!",
  ui_story_5004_50041501_25_dialog_content = "Anda gila! Gila! Aww...",
  ui_story_5004_50041501_26_dialog_content = "Satu jari karena waktu habis, satu lagi untuk berbohong.",
  ui_story_5004_50041501_27_dialog_content = "Saya benar-benar ... dikirim ke sini hanya untuk pengiriman, sial ...",
  ui_story_5004_50041501_28_dialog_content = "Berikan kepadaku.",
  ui_story_5004_50041501_29_dialog_content = "Tidak mungkin!",
  ui_story_5004_50041501_30_dialog_content = "Apa kamu yakin? Saatnya jari ketiga... 5, 4...",
  ui_story_5004_50041501_31_dialog_content = "aku tidak bisa! Mereka akan membunuhku!",
  ui_story_5004_50041501_32_dialog_content = "NOL.",
  ui_story_5004_50041501_33_dialog_content = "<size=45><anim type=Shake>Ahhhh!</anim></size> Huff...",
  ui_story_5004_50041501_34_dialog_content = "Dan Anda pikir saya tidak akan melakukannya?",
  ui_story_5004_50041501_35_dialog_content = "Mau mati sekarang atau mati nanti, itu pilihanmu.",
  ui_story_5004_50041501_36_dialog_content = "Oke, oke, lepaskan saja!",
  ui_story_5004_50041501_37_dialog_content = "Di sini, semua milikmu, kamu gila!",
  ui_story_5004_50041501_38_dialog_content = "Hanya sebuah surat? Apa yang ada di dalamnya?",
  ui_story_5004_50041501_39_dialog_content = "Saya sarankan Anda mengembalikannya kepada saya. Ini untuk seseorang yang besar. Itu tidak akan berhasil bagi kami berdua jika Anda memilikinya!",
  ui_story_5004_50041501_40_dialog_content = "Sangat terlambat.",
  ui_story_5004_50041501_41_dialog_content = "Sekarang saya penasaran ingin melihat apa ini.",
  ui_story_5004_50041501_42_dialog_content = "Apa Pantai Surgawi ini?",
  ui_story_5004_50041501_43_dialog_content = "Apakah ini peta harta karun?",
  ui_story_5004_50041501_44_dialog_content = "Kamu membacanya?! Sekarang kita sudah mati!",
  ui_story_5004_50041501_45_dialog_content = "<size=45>Akulah yang mengajukan pertanyaan!</size>",
  ui_story_5004_50041501_46_dialog_content = "Saya juga tidak tahu. Yang saya tahu adalah mereka banyak yang berbahaya!",
  ui_story_5004_50041501_47_dialog_content = "Mereka tampaknya merencanakan semacam ritual untuk memanggil malapetaka atas dunia!",
  ui_story_5004_50041501_48_dialog_content = "Kembalikan padaku, aku tidak ingin masalah!",
  ui_story_5004_50041501_49_dialog_content = "Hmm, aku tidak memukulmu di kepala, kan?",
  ui_story_5004_50041501_50_dialog_content = "Omong kosong apa yang kamu keluarkan sekarang?",
  ui_story_5004_50041501_51_dialog_content = "Semakin banyak yang Anda katakan, semakin saya ingin terlibat.",
  ui_story_5004_50041501_52_dialog_content = "Saya telah memutuskan untuk melihatnya sendiri!",
  ui_story_5004_50041501_53_dialog_content = "<color=#e8d9bb>Seperti yang dikatakan surat itu ...</color>",
  ui_story_5004_50041501_54_dialog_content = "<color=#e8d9bb>Apa yang saya cari adalah tiga dinding ratapan</color>",
  ui_story_5004_50041501_55_dialog_content = "<color=#e8d9bb>Apa yang saya cari adalah kelahiran kembali dari abu</color>",
  ui_story_5004_50041501_56_dialog_content = "<color=#e8d9bb>Hujan darah turun saat fajar</color>",
  ui_story_5004_50041501_57_dialog_content = "<color=#e8d9bb>Melukis matahari terbenam dengan air mata melolong</color>",
  ui_story_5004_50041501_58_dialog_content = "<color=#e8d9bb>Sampai saat penghakiman, akhir zaman</color>",
  ui_story_5004_50041501_59_dialog_content = "<color=#e8d9bb>Ketika Raja akan terbangun</color>",
  ui_story_5004_50041501_60_dialog_content = "Apa ini omong kosong? Sebuah teka-teki?",
  ui_story_5004_50041501_61_dialog_content = "Jangan bilang aku datang ke sini untuk apa-apa...",
  ui_story_5004_50041501_62_dialog_content = "<color=#e8d9bb>Tok, tok.</color>",
  ui_story_5004_50041501_63_dialog_content = "Masuk.",
  ui_story_5004_50041501_64_dialog_content = "Halo. Nona Smokey Manticore dari Umbraton, saya kira?",
  ui_story_5004_50041501_65_dialog_content = "Kau mengenalku?",
  ui_story_5004_50041501_66_dialog_content = "Tentu saja. Saya tahu siapa Anda, saya mengerti mengapa Anda ada di sini, dan bahwa surat di tangan Anda bukan milik Anda.",
  ui_story_5004_50041501_67_dialog_content = "Katakan apa yang Anda inginkan.",
  ui_story_5004_50041501_68_dialog_content = "Ha ha ha!",
  ui_story_5004_50041501_69_dialog_content = "…?",
  ui_story_5004_50041501_70_dialog_content = "Maaf, tapi itu cukup lucu, bukan?",
  ui_story_5004_50041501_71_dialog_content = "Mengapa saya menginginkan sesuatu? Saya di sini hanya untuk mengundang Anda ke Ocean Sovereign sebagai tuan rumah.",
  ui_story_5004_50041501_72_dialog_content = "Itu saja?",
  ui_story_5004_50041501_73_dialog_content = "Tepat sekali.",
  ui_story_5004_50041501_74_dialog_content = "Anda berasal dari The True Order. Aku tidak percaya kalian.",
  ui_story_5004_50041501_75_dialog_content = "Bahkan jika saya dengan The True Order, saya masih diperbolehkan menjadi tuan rumah, bukan?",
  ui_story_5004_50041501_76_dialog_content = "Selain itu, materialisme diperlukan untuk mengejar Kebenaran, dan pekerjaan ini memberikan bayaran yang sangat baik.",
  ui_story_5004_50041501_77_dialog_content = "Jadi, apakah Anda ingin bergabung? Mungkin hadiah pemenang termasuk hal yang Anda cari.",
  ui_story_5004_50041501_78_dialog_content = "Bahkan jika Anda kalah ...",
  ui_story_5004_50041501_79_dialog_content = "Berhenti di sana. Saya tidak akan kalah, dan saya tidak tertarik dengan konsekuensi kekalahan.",
  ui_story_5004_50041501_80_dialog_content = "Apakah pesuruh itu salah satu dari orang-orang Anda?",
  ui_story_5004_50041501_81_dialog_content = "Bagaimana saya tahu itu?",
  ui_story_5004_50041501_82_dialog_content = "Saya sudah di sini, jadi sebaiknya Anda berterus terang.",
  ui_story_5004_50041501_83_dialog_content = "Saya ingin melihat apa yang Anda coba tarik di bawah hidung saya.",
  ui_story_5004_50041601_1_dialog_content = "Maksudmu kondisi Beryl karena Lumina yang tidak stabil?",
  ui_story_5004_50041601_2_dialog_content = "Ya, saya telah menghubungi Beretta beberapa hari terakhir dan dia menemukan kasus serupa.",
  ui_story_5004_50041601_3_dialog_content = "Lalu ada file di Gautiers...",
  ui_story_5004_50041601_4_dialog_content = "Tapi itu dijaga ketat dan rahasia hanya untuk Tuan Kota dan segelintir orang lainnya.",
  ui_story_5004_50041601_5_dialog_content = "Apakah Beryl seorang Gautier?",
  ui_story_5004_50041601_6_dialog_content = "Benar! Dia berbicara tentang keluarganya ketika kami mengobrol di malam hari dan menyebutkan beberapa keluarga lain ...",
  ui_story_5004_50041601_7_dialog_content = "Pyrrhus-sesuatu... Aku tidak bisa mengingatnya sekarang.",
  ui_story_5004_50041601_8_dialog_content = "Tidak masalah. Sepertinya kalian berdua terhubung dengan sangat baik.",
  ui_story_5004_50041601_9_dialog_content = "Tentu saja. Kami para gadis cenderung berbicara satu sama lain tentang segala hal! Dan Beryl lebih banyak bicara daripada yang Anda pikirkan!",
  ui_story_5004_50041601_10_dialog_content = "Saya mengerti. Yah, tolong jaga dia baik-baik.",
  ui_story_5004_50041601_11_dialog_content = "Tidak masalah! Saya akan berbicara dengan Carleen dan melihat apa yang bisa kita lakukan. Saya akan memberi tahu Anda jika ada sesuatu yang muncul!",
  ui_story_5004_50041601_12_dialog_content = "Aku akan kembali ke Beryl sekarang! Sampai jumpa di pertandingan!",
  ui_story_5004_50041601_13_dialog_content = "Oke, hati-hati.",
  ui_story_5004_50041601_14_dialog_content = "Ugh!",
  ui_story_5004_50041601_15_dialog_content = "Kau baik-baik saja?",
  ui_story_5004_50041601_16_dialog_content = "Saya baik-baik saja. Permisi!",
  ui_story_5004_50041601_17_dialog_content = "Smokey?",
  ui_story_5004_50041601_18_dialog_content = "Anda PlayerName, kan? Saya ingin memperkenalkan diri secara resmi.",
  ui_story_5004_50041601_19_dialog_content = "Saya Smokey dari Umbraton.",
  ui_story_5004_50041601_20_dialog_content = "...",
  ui_story_5004_50041601_21_dialog_content = "...",
  ui_story_5004_50041601_22_dialog_content = "Itu saja?",
  ui_story_5004_50041601_23_dialog_content = "Ya.",
  ui_story_5004_50041601_24_dialog_content = "Jadi, Smokey, apa yang membawamu ke sini?",
  ui_story_5004_50041601_25_dialog_content = "Karena kita rekan satu tim, kupikir aku harus mengenalmu.",
  ui_story_5004_50041601_26_dialog_content = "Dilihat dari pertandingan terakhir kami, kami bisa mengalami masalah pada akhirnya jika kami terus hanya mengandalkan saya.",
  ui_story_5004_50041601_27_dialog_content = "(Apa kamu yakin?)",
  ui_story_5004_50041601_28_dialog_content = "Jadi saya pikir saya harus mulai bergaul dengan tim.",
  ui_story_5004_50041601_29_dialog_content = "Nah, mari kita pergi untuk itu. Sampai jumpa.",
  ui_story_5004_50041601_30_dialog_content = "Tunggu.",
  ui_story_5004_50041601_31_dialog_content = "Ya?",
  ui_story_5004_50041601_32_dialog_content = "Maafkan saya karena terus terang, tapi apa yang terjadi antara Anda dan Genevieve?",
  ui_story_5004_50041601_33_dialog_content = "Aku tahu kau akan menanyakan itu padaku.",
  ui_story_5004_50041601_34_dialog_content = "Tapi saya ragu Anda akan menemukan jawaban saya memuaskan.",
  ui_story_5004_50041601_35_dialog_content = "Kami berdua lahir di Petyaburg. Saya seorang Manticore, dia seorang Vronsky.",
  ui_story_5004_50041601_36_dialog_content = "Bagaimana aku harus mengatakannya... Kedua keluarga adalah saingan, meskipun kami bergaul cukup baik ketika kami masih kecil.",
  ui_story_5004_50041601_37_dialog_content = "Dia cukup imut, mengikutiku saat itu, jauh lebih baik daripada dia sekarang.",
  ui_story_5004_50041601_38_dialog_content = "Saya kira karena saya masih muda, saya pemberontak dan pencari sensasi.",
  ui_story_5004_50041601_39_dialog_content = "Saya pamer sedikit di salah satu tes Genevieve.",
  ui_story_5004_50041601_X39_dialog_content = "Dan menarik perhatian para juri, membuatnya kehilangan kesempatan untuk menjadi bangsawan Lumopolis.",
  ui_story_5004_50041601_40_dialog_content = "Hal itu membuat dirinya dan keluarganya malu.",
  ui_story_5004_50041601_41_dialog_content = "Aku hanya mencari beberapa kegembiraan. Siapa yang tahu mereka akan sangat sensitif?",
  ui_story_5004_50041601_42_dialog_content = "Makanya aku kabur dari rumah. Para bangsawan hanyalah masalah.",
  ui_story_5004_50041601_43_dialog_content = "Oh, begitu…",
  ui_story_5004_50041601_44_dialog_content = "Harus pergi. Mari kita lakukan lebih baik di pertandingan sore.",
  ui_story_5004_50041701_1_dialog_content = "Waow…",
  ui_story_5004_50041701_2_dialog_content = "Gugup, PlayerName?",
  ui_story_5004_50041701_3_dialog_content = "Sedikit…",
  ui_story_5004_50041701_4_dialog_content = "Jangan. Komandan Hiiro mengajari saya itu <color=#FFB400>ketika ada jalan, pasti ada kemauan</color>.",
  ui_story_5004_50041701_5_dialog_content = "Saya percaya Anda sedang memikirkan <color=#FFB400>bila ada kemauan disitu ada jalan</color>.",
  ui_story_5004_50041701_6_dialog_content = "Benar, benar. Saya bertanya-tanya apakah itu berarti Komandan Hiiro pernah tersesat di Rediesel Wrench sebelumnya ...",
  ui_story_5004_50041701_7_dialog_content = "(Hiiro akan membuatmu menulisnya 100 kali jika dia mendengarnya!)",
  ui_story_5004_50041701_8_dialog_content = "Saya membawa Kepompong Bulan hari ini. Serahkan pekerjaan berat itu padaku.",
  ui_story_5004_50041701_9_dialog_content = "Lalu aku akan menembakkan misil dari luar batas untuk mendukung semua orang!",
  ui_story_5004_50041701_10_dialog_content = "Tidak tidak! Ini mungkin pertempuran, tapi kita masih harus mengikuti aturan dasar.",
  ui_story_5004_50041701_11_dialog_content = "Simpan misil untuk Eclipsites, Raphael.",
  ui_story_5004_50041701_12_dialog_content = "Bagaimanapun, Anda adalah Malaikat Lumopolis.",
  ui_story_5004_50041701_13_dialog_content = "BENAR. Aku harus menyelamatkan mereka untuk perlindungan Beryl juga.",
  ui_story_5004_50041701_14_dialog_content = "Aku hanya akan menghiburmu dengan Beryl!",
  ui_story_5004_50041701_15_dialog_content = "Oh, Vice, menurutku busur tidak cocok untuk posisi yang kau mainkan.",
  ui_story_5004_50041701_16_dialog_content = "Benar, itu sebabnya saya meminta Beryl untuk menambahkan bilah kristal untuk busur!",
  ui_story_5004_50041701_17_dialog_content = "Kami mencoba tetapi kami tidak melakukan apa pun yang memadai sampai pagi ini ...",
  ui_story_5004_50041701_18_dialog_content = "Akan sangat bagus jika itu berguna ...",
  ui_story_5004_50041701_19_dialog_content = "Tampaknya kokoh dan cukup tajam. Saya dapat mengatakan bahwa Beryl telah berusaha keras dalam hal ini.",
  ui_story_5004_50041701_20_dialog_content = "(Beryl adalah anak yang hebat...)",
  ui_story_5004_50041701_21_dialog_content = "Terima kasih. Ayo keluar dan raih kemenangan!",
  ui_story_5004_50041701_22_dialog_content = "Ya! Sangat bisa diandalkan dan bersemangat seperti biasa, Vice!",
  ui_story_5004_50041701_23_dialog_content = "(Tapi apakah Anda yakin ingin menggunakan pisau saat Anda menjadi pemanah?)",
  ui_story_5004_50041701_24_dialog_content = "Mungkin seharusnya tidak berubah menjadi perang karena itu hanya catur.",
  ui_story_5004_50041701_25_dialog_content = "Bagus jika itu masalahnya, tetapi baik Smokey maupun Genevieve tidak mudah menyerah.",
  ui_story_5004_50041701_26_dialog_content = "Jadi kita harus siap untuk apa pun.",
  ui_story_5004_50041701_27_dialog_content = "Ahem, saya melihat semua orang di sini.",
  ui_story_5004_50041701_28_dialog_content = "Tolong pegang kudamu sebentar.",
  ui_story_5004_50041701_29_dialog_content = "Dikatakan permainan catur yang diakui secara kritis berasal dari sini.",
  ui_story_5004_50041701_30_dialog_content = "Suatu ketika, seorang raja yang bijaksana dan penyayang di sini berharap rakyatnya bisa cerdas dan pandai.",
  ui_story_5004_50041701_31_dialog_content = "Jadi dia menciptakan permainan untuk mengasah pemikiran kritis dan pikiran taktis mereka.",
  ui_story_5004_50041701_32_dialog_content = "Dari sana diperoleh pasukan tangguh yang menyerang ketakutan bahkan hingga ke Eclipsites, melindungi kerajaan dari bahaya.",
  ui_story_5004_50041701_33_dialog_content = "Tapi itu semua di masa lalu.",
  ui_story_5004_50041701_34_dialog_content = "Untuk mengenang raja itu, kami akan memulai kontes kedua, permainan catur, versi langsung!",
  ui_story_5004_50041701_35_dialog_content = "Saya sekarang mengumumkan bahwa permainan catur kecerdasan dan akan dimulai sekarang!",
  ui_story_5004_50041701_36_dialog_content = "PlayerName!",
  ui_story_5004_50041701_37_dialog_content = "Nih!",
  ui_story_5004_50041701_38_dialog_content = "Waspada dan ambil komando. Kami akan melakukan yang terbaik untuk mencetak kemenangan.",
  ui_story_5004_50041701_39_dialog_content = "(Fokus... Aku bisa melakukan ini. Lagipula, aku sudah memainkan beberapa permainan catur dengan Barton sebelumnya.)",
  ui_story_5004_50041701_40_dialog_content = "(Biarkan aku mengingat kembali saat kita bermain...)",
  ui_story_5004_50041701_41_dialog_content = "Kami menang karena <color=#FFB400>para jenderal membuka jalan bagi kita</color>.",
  ui_story_5004_50041701_42_dialog_content = "Akan kuatasi!",
  ui_story_5004_50041701_43_dialog_content = "Anda akan bangga, Barton... Saya jenderal dan saya akan membuka jalan!",
  ui_story_5004_50041701_44_dialog_content = "Giliran saya!",
  ui_story_5004_50041701_45_dialog_content = "Raja bergerak satu!",
  ui_story_5004_50041701_46_dialog_content = "...",
  ui_story_5004_50041701_47_dialog_content = "Uh, PlayerName, saya tidak tahu cara bermain catur...",
  ui_story_5004_50041701_48_dialog_content = "Tapi saya tidak berpikir Anda harus bergerak maju kecuali Anda bertujuan untuk mendapatkan dukungan.",
  ui_story_5004_50041701_49_dialog_content = "Heh!",
  ui_story_5004_50041701_50_dialog_content = "Saya tahu siapa Anda dan tahu bahwa orang-orang Anda adalah komandan yang berbakat, Caelestite.",
  ui_story_5004_50041701_51_dialog_content = "Tapi saya rasa Anda tidak memahami nuansa permainan seperti catur!",
  ui_story_5004_50041701_52_dialog_content = "Untuk mencocokkan Aurorian yang Anda miliki dengan Anda, saya secara khusus mempekerjakan yang lebih kuat <color=#FFB400>prajurit</color>!",
  ui_story_5004_50041701_53_dialog_content = "Astaga, dia terlalu banyak bicara. Saya pikir kami sepakat untuk tidak memberikan kami.",
  ui_story_5004_50041701_54_dialog_content = "Hei bos, ini jelas melanggar kontrak sebagaimana tercantum dalam Bagian III, Klausul 9.",
  ui_story_5004_50041701_55_dialog_content = "Ini adalah pembayaran tambahan 135% sesuai kesepakatan.",
  ui_story_5004_50041701_56_dialog_content = "Diam, saya akan membayar Anda apa yang pantas Anda dapatkan! Sekarang dapatkan mereka!",
  ui_story_5004_50041701_57_dialog_content = "PlayerName, link dengan saya. Saya akan memandu Anda melalui ini.",
  ui_story_5004_50041701_58_dialog_content = "Oke terima kasih!",
  ui_story_5004_50041701_59_dialog_content = "Rasakan ini!",
  ui_story_5004_50041701_60_dialog_content = "Wow, teknik pedang orang ini hampir sama terampilnya dengan Komandan Hiiro!",
  ui_story_5004_50041701_61_dialog_content = "Dan gaya bertarungnya... Apakah kamu...?",
  ui_story_5004_50041701_62_dialog_content = "Yah, kurasa tidak perlu menyembunyikan identitasku sekarang.",
  ui_story_5004_50041701_63_dialog_content = "Pak Taki?!",
  ui_story_5004_50041701_64_dialog_content = "Taki?",
  ui_story_5004_50041701_65_dialog_content = "Sedang apa kau di sini?",
  ui_story_5004_50041701_66_dialog_content = "Maaf, Nak, tapi itulah yang Odd Jobs lakukan—mengambil pekerjaan berbayar apa pun yang tidak amoral!",
  ui_story_5004_50041701_67_dialog_content = "Dan saya tidak akan mudah karena ini hanya permainan!",
  ui_story_5004_50041701_68_dialog_content = "Saya sarankan Anda menyerah sekarang, PlayerName. Saya tidak ingin menyakiti orang yang tidak bersenjata!",
  ui_story_5004_50041701_69_dialog_content = "Pak Taki, ini akan sulit untuk bisnis saya jika Anda terkena!",
  ui_story_5004_50041701_70_dialog_content = "Ada pembukaan!",
  ui_story_5004_50041701_71_dialog_content = "Aduh!",
  ui_story_5004_50041701_72_dialog_content = "Tidak terlalu sulit, Carleen. Kelapa akan segera pecah!",
  ui_story_5004_50041701_72X1_dialog_content = "Apa? Itu tutup kepala, bukan kelapa asli!",
  ui_story_5004_50041701_72X2_dialog_content = "Oh ya... Drat, itu benar-benar terlihat seperti kelapa.",
  ui_story_5004_50041701_73_dialog_content = "Aku tahu itu kamu, Jomu.",
  ui_story_5004_50041701_74_dialog_content = "Aku punya alasan... Maksudku, aku bisa menjelaskan! Saya mengambil pekerjaan itu <color=#FFB400>untukmu</color>, Bos!",
  ui_story_5004_50041701_75_dialog_content = "Hah? Untuk saya?",
  ui_story_5004_50041701_76_dialog_content = "Ya! Jika saya mendapatkan bonus dari Genevieve, saya dapat mengembangkan bisnis saya.",
  ui_story_5004_50041701_77_dialog_content = "Mungkin Anda bahkan dapat membeli barang-barang seperti <color=#FFB400>Lumocrystal</color> dengan Nightium dari saya di masa depan.",
  ui_story_5004_50041701_78_dialog_content = "Saya akan memberi Anda penawaran khusus dan edisi terbatas bulanan <color=#FFB400>kotak kecil yang lucu</color> dengan itu.",
  ui_story_5004_50041701_79_dialog_content = "PlayerName, yang lain memakai <color=#FFFFFF>tutup kepala</color> terlihat mencurigakan juga!",
  ui_story_5004_50041701_80_dialog_content = "Cabut saja mereka!",
  ui_story_5004_50041701_81_dialog_content = "Tepat! Anda punya ini, Vice dan Carleen!",
  ui_story_5004_50041701_82_dialog_content = "Gergaji saya kehabisan diesel! Selamat tinggal!",
  ui_story_5004_50041701_83_dialog_content = "Saya keluar. Sampai jumpa!",
  ui_story_5004_50041701_84_dialog_content = "Cuit!",
  ui_story_5004_50041701_85_dialog_content = "Ck, aku tahu itu, sekelompok orang yang tidak bisa diandalkan.",
  ui_story_5004_50041701_86_dialog_content = "Ahh, sepertinya kompetisi sedang menemui jalan buntu, ya?",
  ui_story_5004_50041701_87_dialog_content = "Kami memiliki desertir di satu sisi, tapi akan ada skakmat di sisi lain.",
  ui_story_5004_50041701_88_dialog_content = "Hei, pindahkan aku selanjutnya!",
  ui_story_5004_50041701_89_dialog_content = "Baik promosi atau skakmat, saya akan mendapatkan Genevieve selama saya dekat dengannya.",
  ui_story_5004_50041701_90_dialog_content = "Saya kira tidak demikian. Kita perlu Carleen kembali untuk membela Vice dan berkumpul kembali!",
  ui_story_5004_50041701_91_dialog_content = "Kami kehabisan waktu. Semangat mereka rendah, jadi kita harus mengambil kesempatan ini! Tidak ada waktu bagi Anda untuk menyelamatkan pacar kecil Anda.",
  ui_story_5004_50041701_92_dialog_content = "Apa? Dia tidak...",
  ui_story_5004_50041701_93_dialog_content = "Dengarkan aku dan kita akan menang! Buru-buru!",
  ui_story_5004_50041701_94_dialog_content = "Oke.",
  ui_story_5004_50041701_95_dialog_content = "Genevieve!",
  ui_story_5004_50041701_96_dialog_content = "Ayo, Smokey!",
  ui_story_5004_50041701_97_dialog_content = "Ha.",
  ui_story_5004_50041701_98_dialog_content = "Dimulai dengan gerakan paling kuat?!",
  ui_story_5004_50041701_99_dialog_content = "Heh!",
  ui_story_5004_50041701_100_dialog_content = "Mereka cocok! Bagaimana? Apakah Genevieve memiliki keterampilan bertarung yang bagus?",
  ui_story_5004_50041701_101_dialog_content = "Aku ceroboh terakhir kali. Jangan menipu diri sendiri dengan berpikir bahwa Anda bisa mengalahkan saya setiap saat!",
  ui_story_5004_50041701_102_dialog_content = "Anda lebih baik sekarang, tetapi jangan pernah berpikir untuk melewati saya!",
  ui_story_5004_50041701_103_dialog_content = "Ini tidak bisa berlanjut. Mereka berimbang, dan venue akan hangus!",
  ui_story_5004_50041701_104_dialog_content = "Sepertinya saya harus turun tangan, bukan?",
  ui_story_5004_50041701_105_dialog_content = "Mari hidupkan segalanya dengan beberapa aturan baru!",
  ui_story_5004_50041701_106_dialog_content = "Permainan alternatif!",
  ui_story_5004_50041701_107_dialog_content = "Ada sepotong Crystal King di suatu tempat di lapangan. Saya menyembunyikannya sebelum pertandingan.",
  ui_story_5004_50041701_108_dialog_content = "Aturannya sangat sederhana. Raja mana pun yang menemukannya lebih dulu, pihak yang menang!",
  ui_story_5004_50041701_109_dialog_content = "Saya kira beginilah jadinya... Lakukanlah! Penggemarku!",
  ui_story_5004_50041701_110_dialog_content = "Menyerang! Menyerang!",
  ui_story_5004_50041701_111_dialog_content = "Untuk Lady Genevieve!",
  ui_story_5004_50041701_112_dialog_content = "Saya bertanya-tanya kapan mereka akan muncul.",
  ui_story_5004_50041701_113_dialog_content = "Tunggu sebentar, apa masalahnya dengan pistol semprot? Dan mengapa para penggemar bergabung dengan permainan?",
  ui_story_5004_50041701_114_dialog_content = "Anda benar-benar harus membaca manual. Saya mengirimi Anda yang baru, bukan?",
  ui_story_5004_50041701_115_dialog_content = "Manual baru dua kali lebih tebal dari yang lama!",
  ui_story_5004_50041701_116_dialog_content = "Nah, pertandingan sebelumnya memang sensasional, banyak sponsor baru yang mendaftar.",
  ui_story_5004_50041701_117_dialog_content = "Karena Genevieve menahan terlalu lama, game ini dianggap seri.",
  ui_story_5004_50041701_118_dialog_content = "Sekarang kita berada di permainan alternatif, di mana hanya senjata semprot yang bisa digunakan!",
  ui_story_5004_50041701_119_dialog_content = "Bagaimanapun, PlayerName, Anda tidak akan pergi jauh tergantung pada orang lain untuk membacakan Anda Battle Manual ...",
  ui_story_5004_50041701_120_dialog_content = "Saya tidak bisa membayangkan bahwa itu berubah dari kompetisi serius menjadi permainan suasana musim panas!",
  ui_story_5004_50041701_121_dialog_content = "Dan kami bahkan tidak membawa senjata semprot...",
  ui_story_5004_50041701_122_dialog_content = "Hei, apa yang ada di tanganmu?",
  ui_story_5004_50041701_123_dialog_content = "Berlindung dan menyerang balik, Vice!",
  ui_story_5004_50041701_124_dialog_content = "Mengerti! Anda juga berlindung, PlayerName!",
  ui_story_5004_50041701_125_dialog_content = "Saya tidak punya senjata!",
  ui_story_5004_50041701_126_dialog_content = "Tangkap, PlayerName!",
  ui_story_5004_50041701_127_dialog_content = "Terima kasih, Beryl!",
  ui_story_5004_50041701_128_dialog_content = "Usaha yang bagus!",
  ui_story_5004_50041701_129_dialog_content = "Ugh!",
  ui_story_5004_50041701_130_dialog_content = "Pikirkan sesuatu, Smokey!",
  ui_story_5004_50041701_131_dialog_content = "Saya kira sudah waktunya untuk menunjukkan kepada Anda apa yang saya dapatkan!",
  ui_story_5004_50041701_132_dialog_content = "Di mana Anda mendapatkan ini? <color=#FFB400>pistol semprot super berat</color>?!",
  ui_story_5004_50041701_133_dialog_content = "Jangan berpikir Anda bisa menang dengan angka belaka!",
  ui_story_5004_50041701_134_dialog_content = "Sial! Lindungi Lady Genevieve dengan segala cara!",
  ui_story_5004_50041701_135_dialog_content = "Aku tidak bisa melanjutkan, Kapten...",
  ui_story_5004_50041701_136_dialog_content = "Aduh!",
  ui_story_5004_50041701_136X1_dialog_content = "Beraninya kau menargetkan penggemarku!",
  ui_story_5004_50041701_136X2_dialog_content = "Saya tidak akan menunjukkan belas kasihan!",
  ui_story_5004_50041701_136X3_dialog_content = "Ah, aku tidak bisa melihat!",
  ui_story_5004_50041701_136X4_dialog_content = "Mundur, Vice, aku akan melindungimu.",
  ui_story_5004_50041701_136X5_dialog_content = "Saya akan menunjukkan kepada Anda kekuatan Pemburu Mawar saya!",
  ui_story_5004_50041701_136X6_dialog_content = "Hei!",
  ui_story_5004_50041701_136X7_dialog_content = "Ah, aku juga tidak bisa melihat.",
  ui_story_5004_50041701_136X8_dialog_content = "Anda bisa melakukannya, Carleen. Ini bukan di bawah laut.",
  ui_story_5004_50041701_136X9_dialog_content = "Bukankah kalian berdua pengguna air Luminatics? Bagaimana Anda bisa menyerah begitu mudah untuk menyemprotkan senjata?",
  ui_story_5004_50041701_136X10_dialog_content = "Ha ha ha! Menyerah kecuali jika Anda ingin basah kuyup!",
  ui_story_5004_50041701_136X11_dialog_content = "Kamu terlalu menyebalkan!",
  ui_story_5004_50041701_136X12_dialog_content = "Asap? Aku tahu penggemarku tidak bisa menahanmu lama-lama.",
  ui_story_5004_50041701_136X13_dialog_content = "Semuanya, targetkan Smokey sementara aku mengurus keduanya!",
  ui_story_5004_50041701_138_dialog_content = "Ya, Nona!",
  ui_story_5004_50041701_139_dialog_content = "Pondok, pondok, pondok!",
  ui_story_5004_50041701_140_dialog_content = "Tsk, aku tidak bisa membidik dengan semua air ini!",
  ui_story_5004_50041701_141_dialog_content = "Mereka menetralisir Smokey! Lakukan sesuatu, Brock!",
  ui_story_5004_50041701_142_dialog_content = "Apa yang dapat saya? Anda bahkan tidak membaca aturan, jadi mengapa saya?",
  ui_story_5004_50041701_143_dialog_content = "Aku benar-benar tidak siap. Apakah Anda ingin saya meninju mereka dengan tinju saya?",
  ui_story_5004_50041701_144_dialog_content = "Brock, PlayerName! Lihat apa yang saya temukan di saku saya?",
  ui_story_5004_50041701_145_dialog_content = "Tahan air <color=#FFB400>tenda luar ruangan</color>! Kalian ingin berlindung?",
  ui_story_5004_50041701_146_dialog_content = "Tidak ada yang ingin menjejalkan ke dalam tenda dengan Anda!",
  ui_story_5004_50041701_147_dialog_content = "Tapi bukankah menenangkan mendengar suara percikan air di tenda?",
  ui_story_5004_50041701_148_dialog_content = "aku punya <color=#FFB400>kursi luar ruangan</color> juga. Mau duduk?",
  ui_story_5004_50041701_149_dialog_content = "Tidak!",
  ui_story_5004_50041701_150_dialog_content = "Hei, kalian berhenti berkemah di sana!",
  ui_story_5004_50041701_151_dialog_content = "Anda Brock, kan?",
  ui_story_5004_50041701_152_dialog_content = "Ya. Apa yang kamu inginkan?",
  ui_story_5004_50041701_153_dialog_content = "Saya akan membuat celah, dan Anda melemparkan PlayerName ke tengah untuk menggali bagian itu!",
  ui_story_5004_50041701_154_dialog_content = "APA???",
  ui_story_5004_50041701_155_dialog_content = "Mengapa saya harus mendengarkan Anda?",
  ui_story_5004_50041701_156_dialog_content = "Anda bahkan tidak bisa melakukan itu? Lalu masuk ke tenda konyol itu dan bersembunyi!",
  ui_story_5004_50041701_157_dialog_content = "Anda... Baik, ini mungkin sedikit menyakitkan, PlayerName!",
  ui_story_5004_50041701_158_dialog_content = "Wah, pasti ada cara lain!",
  ui_story_5004_50041701_159_dialog_content = "3... 2...",
  ui_story_5004_50041701_160_dialog_content = "Turunkan aku dan mari kita pikirkan ini! Bangsat!",
  ui_story_5004_50041701_161_dialog_content = "1!",
  ui_story_5004_50041701_162_dialog_content = "Anda lebih baik memiliki tujuan yang baik!",
  ui_story_5004_50041701_163_dialog_content = "...",
  ui_story_5004_50041701_164_dialog_content = "...",
  ui_story_5004_50041701_165_dialog_content = "PlayerName…",
  ui_story_5004_50041701_166_dialog_content = "Bangun!",
  ui_story_5004_50041701_167_dialog_content = "Ibu?",
  ui_story_5004_50041701_168_dialog_content = "Bangun, PlayerName.",
  ui_story_5004_50041701_169_dialog_content = "Brock?!",
  ui_story_5004_50041701_170_dialog_content = "Kami menang. Brock melemparkan Anda melalui perisai air penggemar. Kepalamu membentur tanah dan membuat lubang, potongan itu tepat di bawahmu, jadi... kau menemukannya, kita menang.",
  ui_story_5004_50041701_171_dialog_content = "Anda langsung pingsan, tetapi penggemar Genevieve frustrasi. Mereka menembakmu sebelum Genevieve bisa memerintahkan mereka untuk berhenti.",
  ui_story_5004_50041701_172_dialog_content = "Maaf, Anda hampir tenggelam, hanya Brock yang memiliki pengalaman pelatihan CPR.",
  ui_story_5004_50041701_173_dialog_content = "Oke. Bolehkah aku istirahat sebentar?",
  ui_story_5004_50041901_1_dialog_content = "...",
  ui_story_5004_50041901_2_dialog_content = "Jenewa.",
  ui_story_5004_50041901_3_dialog_content = "Tanggung jawab untuk menghidupkan kembali nama Vronsky ada di pundak Anda.",
  ui_story_5004_50041901_4_dialog_content = "...",
  ui_story_5004_50041901_5_dialog_content = "Anda harus menjalani pelatihan yang ketat, meskipun Anda adalah anak-anak sekarang.",
  ui_story_5004_50041901_6_dialog_content = "Itu semua untuk kebaikanmu sendiri.",
  ui_story_5004_50041901_7_dialog_content = "Ya, ayah, ibu, saya mengerti.",
  ui_story_5004_50041901_8_dialog_content = "Ini adalah mentor Luminatika dan etiket Anda. Dia adalah seorang bangsawan terkemuka di Lumopolis.",
  ui_story_5004_50041901_9_dialog_content = "Anda harus mengikuti mentor Anda dan belajar keras untuk Keluarga Vronsky.",
  ui_story_5004_50041901_10_dialog_content = "Ya, aku mengerti.",
  ui_story_5004_50041901_11_dialog_content = "Anda harus bisa melampaui gadis Manticore itu.",
  ui_story_5004_50041901_12_dialog_content = "Genevieve? Genevieve?",
  ui_story_5004_50041901_13_dialog_content = "Permisi bu.",
  ui_story_5004_50041901_14_dialog_content = "Ini tidak seperti Anda terganggu.",
  ui_story_5004_50041901_15_dialog_content = "Tadi malam saya begadang untuk menyelesaikan tugas yang Anda berikan kepada saya.",
  ui_story_5004_50041901_16_dialog_content = "Tugas itu selama seminggu penuh. Anda tidak perlu berlebihan dalam hal ini.",
  ui_story_5004_50041901_17_dialog_content = "...",
  ui_story_5004_50041901_18_dialog_content = "Apa yang Anda inginkan ketika Anda dewasa, Genevieve?",
  ui_story_5004_50041901_19_dialog_content = "Mencapai kehormatan dan kemuliaan bagi keluarga?",
  ui_story_5004_50041901_20_dialog_content = "Saya bertanya apa yang ingin Anda lakukan.",
  ui_story_5004_50041901_21_dialog_content = "Aku tidak tahu. Saya tidak yakin. Mungkin aku tidak pernah memikirkannya.",
  ui_story_5004_50041901_22_dialog_content = "Tentu. Mari kita tidak membicarakan hal ini.",
  ui_story_5004_50041901_23_dialog_content = "Anda pergi menemui gadis Manticore minggu lalu, bukan, Genevieve?",
  ui_story_5004_50041901_24_dialog_content = "Bagaimana Anda mengetahuinya?",
  ui_story_5004_50041901_25_dialog_content = "Ya, benar. Aku tidak akan memberitahu siapa pun.",
  ui_story_5004_50041901_26_dialog_content = "Terima kasih.",
  ui_story_5004_50041901_27_dialog_content = "Tapi kenapa kamu...",
  ui_story_5004_50041901_28_dialog_content = "Sudahlah, seharusnya aku tidak mengajukan pertanyaan seperti itu.",
  ui_story_5004_50041901_29_dialog_content = "...",
  ui_story_5004_50041901_30_dialog_content = "Tapi Genevieve, mungkin Anda tidak harus terobsesi untuk memenangkan kemuliaan bagi keluarga Anda.",
  ui_story_5004_50041901_31_dialog_content = "Kenapa tidak?",
  ui_story_5004_50041901_32_dialog_content = "Apakah Anda tahu mengapa SAYA ADALAH seorang bangsawan terkemuka?",
  ui_story_5004_50041901_33_dialog_content = "Terima kasih atas semua yang telah Anda ajarkan padanya selama bertahun-tahun.",
  ui_story_5004_50041901_34_dialog_content = "Genevieve adalah gadis yang berbakat dan juga pekerja keras.",
  ui_story_5004_50041901_35_dialog_content = "Dia telah menjadi jauh lebih mahir dalam sihir ritual daripada banyak bangsawan.",
  ui_story_5004_50041901_36_dialog_content = "Dan itulah alasan mengapa saya tidak punya apa-apa lagi untuk mengajarinya.",
  ui_story_5004_50041901_37_dialog_content = "Mau kemana, Bu?",
  ui_story_5004_50041901_38_dialog_content = "Untuk mengutip Anda, saya tidak tahu. Mungkin untuk mencari sesuatu, mungkin seseorang.",
  ui_story_5004_50041901_39_dialog_content = "Siapa tahu, perjalanan itu sendiri bisa bermanfaat.",
  ui_story_5004_50041901_40_dialog_content = "Selamat tinggal, Genevieve.",
  ui_story_5004_50041901_41_dialog_content = "Apa, Eclipsites mendekat?",
  ui_story_5004_50041901_42_dialog_content = "Kami tidak punya cukup uang untuk mempertahankan Petyaburg. Kita harus meminta bantuan Lumopolis.",
  ui_story_5004_50041901_43_dialog_content = "Keluarga Salar di Lumopolis telah setuju untuk membantu tetapi dengan satu syarat...",
  ui_story_5004_50041901_44_dialog_content = "Mereka ingin memeriksa keajaiban ritual anak-anak kita dan mengadopsinya sebagai garis keluarga mereka jika perlu.",
  ui_story_5004_50041901_45_dialog_content = "Bukan hal yang buruk jika kita memiliki hubungan yang kuat dengan keluarga yang begitu kuat. Itu hanya akan menguntungkan kita para Vronsky.",
  ui_story_5004_50041901_46_dialog_content = "Jenewa.",
  ui_story_5004_50041901_47_dialog_content = "Saya mengerti, ayah.",
  ui_story_5004_50041901_48_dialog_content = "Anda memang kuat, Genevieve.",
  ui_story_5004_50041901_49_dialog_content = "Anda dapat bertemu dengan yang lebih tua setelah ujian.",
  ui_story_5004_50041901_50_dialog_content = "Terima kasih.",
  ui_story_5004_50041901_51_dialog_content = "Hei!",
  ui_story_5004_50041901_52_dialog_content = "Smokey? Sedang apa kamu di sini?",
  ui_story_5004_50041901_53_dialog_content = "Saya mendengar ada semacam tes, jadi inilah saya!",
  ui_story_5004_50041901_54_dialog_content = "Jadi saya baru saja mencapai target dengan Luminatics, kan?",
  ui_story_5004_50041901_55_dialog_content = "Ya ampun, seperti...",
  ui_story_5004_50041901_56_dialog_content = "Kekuatan yang luar biasa! Bagaimana mungkin bagi seorang gadis muda?",
  ui_story_5004_50041901_57_dialog_content = "Siapa namamu? Anda dari keluarga mana?",
  ui_story_5004_50041901_58_dialog_content = "Apakah saya mendapatkan hadiah? Saya tidak ingin hal-hal yang biasa, Anda tahu.",
  ui_story_5004_50041901_59_dialog_content = "Dengarkan baik-baik, saya Smokey dari Manticores!",
  ui_story_5004_50041901_60_dialog_content = "Smokey dari Manticore...",
  ui_story_5004_50041901_61_dialog_content = "Apakah ada acara lain atau ini saja?",
  ui_story_5004_50041901_62_dialog_content = "Harap tunggu, penatua ingin berbicara dengan Anda.",
  ui_story_5004_50041901_63_dialog_content = "Saya tidak sabar, saya masih harus berbelanja pakaian!",
  ui_story_5004_50041901_64_dialog_content = "Apakah Anda ikut dengan saya, Jenewa?",
  ui_story_5004_50041901_65_dialog_content = "Kenapa kamu...",
  ui_story_5004_50041901_66_dialog_content = "Dengar, Genevieve...",
  ui_story_5004_50041901_67_dialog_content = "Anda melewatkan kesempatan seumur hidup.",
  ui_story_5004_50041901_68_dialog_content = "Tidak apa-apa, Salar masih mau membela Petyaburg.",
  ui_story_5004_50041901_69_dialog_content = "Tapi kita tidak punya kesempatan untuk aliansi.",
  ui_story_5004_50041901_70_dialog_content = "Anda bisa pergi sekarang.",
  ui_story_5004_50041901_71_dialog_content = "Maaf, ayah.",
  ui_story_5004_50041901_72_dialog_content = "(Mengapa kamu muncul, Smokey?)",
  ui_story_5004_50041901_73_dialog_content = "(Apakah Anda hanya ingin bersaing? Untuk mengalahkan saya? Atau...)",
  ui_story_5004_50041901_74_dialog_content = "Genevieve!",
  ui_story_5004_50041901_75_dialog_content = "Ada apa, ibu?",
  ui_story_5004_50041901_76_dialog_content = "Anda telah mendengar?",
  ui_story_5004_50041901_77_dialog_content = "Keluarga Salar membuat perjanjian dengan Manticore...",
  ui_story_5004_50041901_78_dialog_content = "Saya tahu tentang itu. Itu lamaran pernikahan.",
  ui_story_5004_50041901_79_dialog_content = "Tapi gadis Smokey itu pergi tanpa jejak!",
  ui_story_5004_50041901_80_dialog_content = "Apa?",
  ui_story_5004_50041901_81_dialog_content = "Smokey kabur?",
  ui_story_5004_50041901_82_dialog_content = "Sial, kita seharusnya tidak memberi orang-orang udik di Petyaburg itu kesempatan!",
  ui_story_5004_50041901_83_dialog_content = "Buang-buang waktu. Lihat sisi baiknya, setidaknya kita tidak harus pergi ke pinggiran sekarang.",
  ui_story_5004_50041901_84_dialog_content = "Dengar! Per penatua, Petyaburg tidak lagi membutuhkan perlindungan dari Lumopolis! Berbalik! Pergi!",
  ui_story_5004_50041901_85_dialog_content = "Dan Petyaburg yang sudah malang jatuh ke penurunan lebih lanjut.",
  ui_story_5004_50041901_86_dialog_content = "Ibu meninggal karena kecelakaan, dan ayah jatuh sakit.",
  ui_story_5004_50041901_87_dialog_content = "Genevieve...",
  ui_story_5004_50041901_88_dialog_content = "Aku di sini, ayah.",
  ui_story_5004_50041901_89_dialog_content = "Keluarga yang Anda bersumpah untuk membela akan segera berakhir ...",
  ui_story_5004_50041901_90_dialog_content = "Apakah Anda kesal atau Anda lega? Sudahkah Anda merencanakan apa yang akan Anda lakukan selanjutnya?",
  ui_story_5004_50041901_91_dialog_content = "Entahlah, ayah... Ini terjadi terlalu cepat untuk kuproses.",
  ui_story_5004_50041901_92_dialog_content = "Anak yang malang…",
  ui_story_5004_50041901_93_dialog_content = "...",
  ui_story_5004_50041901_94_dialog_content = "Saya tidak berpikir saya akan kehilangan Anda juga, Anna.",
  ui_story_5004_50041901_95_dialog_content = "Meringkik...",
  ui_story_5004_50041901_96_dialog_content = "Apakah kuda ini milikmu, nona muda?",
  ui_story_5004_50041901_97_dialog_content = "Ya.",
  ui_story_5004_50041901_98_dialog_content = "Aku bisa menyelamatkannya, tapi kamu harus...",
  ui_story_5004_50041901_99_dialog_content = "Aku akan melakukannya, aku akan melakukannya! Aku butuh Ana! Aku ingin dia menemukan seseorang bersamaku!",
  ui_story_5004_50041901_100_dialog_content = "Smokey...",
  ui_story_5004_50041901_100X1_dialog_content = "Nah jika tidak Genevieve?",
  ui_story_5004_50041901_100X2_dialog_content = "Anda tahu siapa saya jadi langsung ke intinya. Saya tidak tertarik dengan obrolan.",
  ui_story_5004_50041901_100X3_dialog_content = "Oh, Anda akan tertarik dengan yang satu ini. Ini tentang Smokey.",
  ui_story_5004_50041901_100X4_dialog_content = "!!",
  ui_story_5004_50041901_100X5_dialog_content = "Anda tahu Smokey?",
  ui_story_5004_50041901_100X6_dialog_content = "Tentu saja. Aku bahkan tahu dia di Celestial Coast...",
  ui_story_5004_50041901_100X7_dialog_content = "Hei, jangan pergi, aku belum selesai!",
  ui_story_5004_50041901_102_dialog_content = "Genevieve.",
  ui_story_5004_50041901_103_dialog_content = "Nona Genevieve!",
  ui_story_5004_50041901_104_dialog_content = "Ya.",
  ui_story_5004_50041901_105_dialog_content = "Kami siap untuk menggairahkannya seperti yang Anda instruksikan.",
  ui_story_5004_50041901_106_dialog_content = "Baiklah, aku akan membawamu satu lawan satu.",
  ui_story_5004_50041901_107_dialog_content = "Aku akan mengalahkan... tidak, mengalahkanmu dengan nyanyianku!",
  ui_story_5004_50042001_1_dialog_content = "Sungguh panggung yang luar biasa. Apakah Fleur mendesainnya?",
  ui_story_5004_50042001_2_dialog_content = "Dilihat dari dekorasi Rediesel Wrench, kemungkinan besar.",
  ui_story_5004_50042001_3_dialog_content = "Dia sangat serbaguna.",
  ui_story_5004_50042001_4_dialog_content = "Anda tidak dalam hal ini, PlayerName?",
  ui_story_5004_50042001_5_dialog_content = "Aku melewatkannya. Menyanyi sama sekali bukan setelanku.",
  ui_story_5004_50042001_6_dialog_content = "Dan aku... tidak nyaman... dengan keramaian.",
  ui_story_5004_50042001_7_dialog_content = "Bukan aku juga. Aku sedang menonton Beryl.",
  ui_story_5004_50042001_8_dialog_content = "Ya, Raphael dan saya akan mendukung Anda dengan sangat keras!",
  ui_story_5004_50042001_9_dialog_content = "Serahkan sorakan itu padaku! Aku akan menutupi semua orang dengan rudal!",
  ui_story_5004_50042001_10_dialog_content = "Tidak, jangan! Silahkan!",
  ui_story_5004_50042001_11_dialog_content = "Oke, Anda punya ini kemudian!",
  ui_story_5004_50042001_12_dialog_content = "Bersiaplah untuk menikmati pertunjukan kami dan mendukung kami!",
  ui_story_5004_50042001_13_dialog_content = "Ini dia, kompetisi terakhir dari Ocean Sovereign, kontes kecerdasan dan kecantikan—Beach LIVE!",
  ui_story_5004_50042001_14_dialog_content = "Dengan masuknya sponsor, kami dapat mengundang dua A-lister terkemuka sebagai juri!",
  ui_story_5004_50042001_15_dialog_content = "Tuan S tanpa nama dari Lumopolis!",
  ui_story_5004_50042001_16_dialog_content = "Ehem.",
  ui_story_5004_50042001_17_dialog_content = "Dan Mr. Y anonim dari Umbraton!",
  ui_story_5004_50042001_18_dialog_content = "Halo semuanya.",
  ui_story_5004_50042001_19_dialog_content = "Bonacie mengundang dua juri. Hei, kenapa mereka terlihat akrab?",
  ui_story_5004_50042001_20_dialog_content = "Juri dan penonton langsung akan memilih pemenangnya!",
  ui_story_5004_50042001_21_dialog_content = "Pesaing pertama...",
  ui_story_5004_50042001_22_dialog_content = "adalah vokalis heavy metal bertopeng dari neraka...",
  ui_story_5004_50042001_23_dialog_content = "Nama saya Sneaky Slim, penyanyi misteri dari Umbraton!",
  ui_story_5004_50042001_24_dialog_content = "Bukan Seleukus? Nama dan helmnya praktis memberikannya!",
  ui_story_5004_50042001_25_dialog_content = "Sekarang, izinkan saya mengaum dari lubuk jiwa saya yang paling dalam!",
  ui_story_5004_50042001_26_dialog_content = "Dan memberi Anda performa heavy metal terberat seumur hidup!",
  ui_story_5004_50042001_27_dialog_content = "Turun dari panggung!",
  ui_story_5004_50042001_28_dialog_content = "Turun, turun!",
  ui_story_5004_50042001_29_dialog_content = "Ini pakaian renang LANGSUNG!",
  ui_story_5004_50042001_30_dialog_content = "Apa yang Anda lakukan tanpa baju renang?",
  ui_story_5004_50042001_31_dialog_content = "Iklan palsu! Iklan palsu!",
  ui_story_5004_50042001_32_dialog_content = "Saya di sini untuk anak perempuan dengan pakaian renang! Pengembalian dana! Pengembalian dana!",
  ui_story_5004_50042001_33_dialog_content = "Ini memalukan... Untungnya, saya tidak menyebutkan nama asli saya.",
  ui_story_5004_50042001_34_dialog_content = "Yah, saya kira saya akan melihat Anda semua beberapa hari lagi!",
  ui_story_5004_50042001_35_dialog_content = "Apakah sudah berakhir? Terlalu cepat...",
  ui_story_5004_50042001_36_dialog_content = "Sayang sekali, pria bertopeng kucing itu terlihat seperti penyanyi yang bagus...",
  ui_story_5004_50042001_37_dialog_content = "Jangan biarkan penampilannya menipumu, Beryl.",
  ui_story_5004_50042001_38_dialog_content = "Dia melakukan pekerjaan dengan baik, Seleucid yang hebat.",
  ui_story_5004_50042001_39_dialog_content = "Dia menurunkan harapan begitu banyak, gadis-gadis itu pasti akan mendapatkan skor yang lebih tinggi!",
  ui_story_5004_50042001_40_dialog_content = "Berikutnya adalah... Fleur dan Brock?",
  ui_story_5004_50042001_41_dialog_content = "<color=#e8d9bb>Brock membungkuk kepada penonton, berbalik dan mengulurkan tangan...</color>",
  ui_story_5004_50042001_42_dialog_content = "Ahhhh!",
  ui_story_5004_50042001_43_dialog_content = "Ohhhh!",
  ui_story_5004_50042001_44_dialog_content = "Apakah kamu melihat itu? Fleur tersenyum padaku!",
  ui_story_5004_50042001_45_dialog_content = "Tatapanmu langsung mengarah ke hatiku, Fleury! Ini terbakar untuk cinta!",
  ui_story_5004_50042001_46_dialog_content = "Cakak, kicau!",
  ui_story_5004_50042001_47_dialog_content = "Dan inilah burung camar! Bukankah kamu seharusnya berburu ikan?",
  ui_story_5004_50042001_48_dialog_content = "Apakah Anda yakin kami melakukannya?",
  ui_story_5004_50042001_49_dialog_content = "Tentu saja, temanku!",
  ui_story_5004_50042001_50_dialog_content = "Mengapa Brock menarik batang baja?!",
  ui_story_5004_50042001_51_dialog_content = "Tunggu sebentar. Dia tidak mencoba trik sulap itu, kan?",
  ui_story_5004_50042001_52_dialog_content = "Bisakah Rediesel Wrench yang paling padat menariknya?",
  ui_story_5004_50042001_53_dialog_content = "Kiyeah!",
  ui_story_5004_50042001_54_dialog_content = "<color=#e8d9bb>Batang baja merobek tirai dan menusuk kotak, sampai ujungnya menonjol dari ujung yang lain.</color>",
  ui_story_5004_50042001_55_dialog_content = "Fleur!",
  ui_story_5004_50042001_56_dialog_content = "Kotaknya bergoyang...",
  ui_story_5004_50042001_57_dialog_content = "Apakah Fleur baik-baik saja? Itu tidak terlihat bagus...",
  ui_story_5004_50042001_58_dialog_content = "Tenang, saya siap memberikan bantuan medis.",
  ui_story_5004_50042001_59_dialog_content = "Tidak ada yang akan mati, kan?",
  ui_story_5004_50042001_60_dialog_content = "(Apakah Brock menggumamkan doa?)",
  ui_story_5004_50042001_61_dialog_content = "Kotak itu berhenti bergerak... Raphael!",
  ui_story_5004_50042001_62_dialog_content = "Oke, bersiap untuk menembak!",
  ui_story_5004_50042001_63_dialog_content = "Tunggu!",
  ui_story_5004_50042001_64_dialog_content = "Yoo-Hoo!",
  ui_story_5004_50042001_65_dialog_content = "Wow, itu tidak bisa dipercaya!",
  ui_story_5004_50042001_66_dialog_content = "Luar biasa...",
  ui_story_5004_50042001_67_dialog_content = "Tidak, itu buang-buang energi. Saya siap menembak!",
  ui_story_5004_50042001_68_dialog_content = "Api? Dengan rudal Anda? Bagaimana bantuan medis itu?",
  ui_story_5004_50042001_69_dialog_content = "Tapi semua orang tampaknya menikmati pertunjukan dan bertepuk tangan.",
  ui_story_5004_50042001_70_dialog_content = "Saya pikir itu karena Fleur masih hidup.",
  ui_story_5004_50042001_71_dialog_content = "Tunggu, saya yakin saya menyatakan hanya menyanyi yang diperbolehkan untuk kontes, bukan?",
  ui_story_5004_50042001_72_dialog_content = "Tidak baik melanggar aturan, Brock dan Fleur. Apalagi ketika Anda mengenal mereka, bukan?",
  ui_story_5004_50042001_73_dialog_content = "Haha, maaf soal itu. Kami hanya ingin membawa kegembiraan kepada orang banyak dan membuat lebih banyak kegembiraan.",
  ui_story_5004_50042001_74_dialog_content = "Tapi saya tidak bisa menyanyi, jadi saya pikir saya akan melakukan ini.",
  ui_story_5004_50042001_75_dialog_content = "Siapa wanita yang menceramahi Fleur seperti itu!",
  ui_story_5004_50042001_76_dialog_content = "Fleur! Kami mencintai kamu!",
  ui_story_5004_50042001_77_dialog_content = "(Tidak buruk jika ini berubah menjadi pertunjukan bakat.)",
  ui_story_5004_50042001_78_dialog_content = "(Meskipun sangat disayangkan bahwa Seleucid mundur lebih awal.)",
  ui_story_5004_50042001_79_dialog_content = "(Namun, dengan topeng kucingnya, dia lebih cocok untuk acara penyanyi bertopeng.)",
  ui_story_5004_50042001_80_dialog_content = "Aturan adalah aturan. Dengan ini saya mendiskualifikasi Fleur.",
  ui_story_5004_50042001_81_dialog_content = "Kenapa harus nyanyi?!",
  ui_story_5004_50042001_82_dialog_content = "Anda dipersilakan untuk tampil di kamar kami kapan saja, Fleur!",
  ui_story_5004_50042001_83_dialog_content = "Guk, guk!",
  ui_story_5004_50042001_84_dialog_content = "Meong!",
  ui_story_5004_50042001_85_dialog_content = "Dan inilah hewan-hewan itu! Sifat khusus Fleur sangat menakutkan ...",
  ui_story_5004_50042001_86_dialog_content = "Kontestan Nomor Delapan!",
  ui_story_5004_50042001_87_dialog_content = "Genevieve Vronskii!",
  ui_story_5004_50042001_88_dialog_content = "Heh, ini adalah level pesaing yang saya hadapi.",
  ui_story_5004_50042001_89_dialog_content = "Saya akan mengambil kesempatan untuk mengesankan para juri dan penonton dan mendapatkan skor tertinggi!",
  ui_story_5004_50042001_90_dialog_content = "(Pesaing yang lebih aneh ...)",
  ui_story_5004_50042001_91_dialog_content = "(Apakah giliran Vice belum?)",
  ui_story_5004_50042001_92_dialog_content = "Genevieve aktif sekarang, PlayerName.",
  ui_story_5004_50042001_93_dialog_content = "Ya, dia mungkin kompetisi terbesar yang kita punya.",
  ui_story_5004_50042001_94_dialog_content = "Jatuh dari badai petir♪",
  ui_story_5004_50042001_95_dialog_content = "…!!",
  ui_story_5004_50042001_96_dialog_content = "Apakah itu penghakiman tanpa ampun atau keselamatan yang membebaskan♪",
  ui_story_5004_50042001_97_dialog_content = "Memudar dari cakrawala yang jauh♪",
  ui_story_5004_50042001_98_dialog_content = "Itu adalah sosokmu yang tidak bisa dipahami♪",
  ui_story_5004_50042001_99_dialog_content = "Kerinduan yang berlama-lama dengan angin kencang dan hujan",
  ui_story_5004_50042001_100_dialog_content = "Menentang vulgaritas♪",
  ui_story_5004_50042001_101_dialog_content = "Merobek jalan di depan dengan semangat dan dorongan hati♪",
  ui_story_5004_50042001_102_dialog_content = "Menutup mata terhadap apa yang disebut perang♪",
  ui_story_5004_50042001_103_dialog_content = "Itu... mengesankan.",
  ui_story_5004_50042001_104_dialog_content = "...",
  ui_story_5004_50042001_105_dialog_content = "Ohhhh, Genevieve!",
  ui_story_5004_50042001_106_dialog_content = "Sungguh pertunjukan yang emosional. Semua orang bisa merasakannya.",
  ui_story_5004_50042001_107_dialog_content = "Suara Genevieve masuk ke hatiku. Saya berharap dia mengadakan konser di Umbraton kapan-kapan.",
  ui_story_5004_50042001_108_dialog_content = "Kami memiliki hasilnya. Skor akhir untuk Genevieve adalah 9,6!",
  ui_story_5004_50042001_109_dialog_content = "Selamat, itu skor yang sangat tinggi, bukan?",
  ui_story_5004_50042001_110_dialog_content = "Terima kasih atas penampilannya, Genevieve.",
  ui_story_5004_50042001_111_dialog_content = "Jadi, kau lihat itu, Smokey?",
  ui_story_5004_50042001_112_dialog_content = "Menakjubkan...",
  ui_story_5004_50042001_113_dialog_content = "Nyanyian itu penuh dengan emosi.",
  ui_story_5004_50042001_114_dialog_content = "(Nyanyian Genevieve benar-benar keluar dari dunia ini, dia pasti membuat beberapa penggemar baru.)",
  ui_story_5004_50042001_115_dialog_content = "(Sekarang saya prihatin dengan Vice ...)",
  ui_story_5004_50042001_116_dialog_content = "Sekarang kita memiliki trio gadis, Kiss of the Manticore!",
  ui_story_5004_50042001_117_dialog_content = "Giliran Vice!",
  ui_story_5004_50042001_118_dialog_content = "Akhirnya! Oh, aku mulai gugup.",
  ui_story_5004_50042001_119_dialog_content = "Iya, aku juga!",
  ui_story_5004_50042001_120_dialog_content = "—",
  ui_story_5004_50042001_121_dialog_content = "♬",
  ui_story_5004_50042001_122_dialog_content = "Siapa yang tahu di mana gadis gelandangan itu akan berakhir hari ini♪",
  ui_story_5004_50042001_123_dialog_content = "Bertanya-tanya di sepanjang garis pantai di bawah cahaya suar di malam hari♪",
  ui_story_5004_50042001_124_dialog_content = "Oh!",
  ui_story_5004_50042001_125_dialog_content = "Hore, hore, hore!",
  ui_story_5004_50042001_126_dialog_content = "(Wow, bahkan penggemar Genevieve bersorak dan bertepuk tangan seperti orang gila.)",
  ui_story_5004_50042001_127_dialog_content = "Aroma ombak bergerak melintasi pantai di bawah bintang-bintang♪",
  ui_story_5004_50042001_128_dialog_content = "Merangkul dan memelihara bunga dalam tekad yang hening♪",
  ui_story_5004_50042001_129_dialog_content = "Memutuskan untuk mengatasi gelombang air untuk kemenangan akhir♪",
  ui_story_5004_50042001_130_dialog_content = "Carleen! Vice kecil! Smokey kecil! Kamu yang terbaik!",
  ui_story_5004_50042001_131_dialog_content = "Pegang tanganku dan lambaikan tangan ke arah mereka bersamaku, Beryl!",
  ui_story_5004_50042001_132_dialog_content = "Tentu!",
  ui_story_5004_50042001_133_dialog_content = "Tangkap cahaya dengan kebanggaan yang tak terpatahkan♪",
  ui_story_5004_50042001_134_dialog_content = "Rasakan deru hati di ambang ledakan♪",
  ui_story_5004_50042001_135_dialog_content = "Mengalahkan dengan kuat♪",
  ui_story_5004_50042001_136_dialog_content = "Dengan mata cerah dan dorongan tak terkendali menuju tujuan yang sebenarnya♪",
  ui_story_5004_50042001_137_dialog_content = "Isi daya terus maju♪",
  ui_story_5004_50042001_138_dialog_content = "Ke puncak dunia♪",
  ui_story_5004_50042001_139_dialog_content = "<color=#e8d9bb>Dengan mikrofon di satu tangan, Smokey membuat pistol dengan tangan yang lain dan gerakan menembak ke Genevieve, lalu menyelesaikan lagu dengan mengedipkan mata.</color>",
  ui_story_5004_50042001_140_dialog_content = "<color=#e8d9bb>Kiss of the Manticore, berakhir dengan sempurna.</color>",
  ui_story_5004_50042001_141_dialog_content = "...",
  ui_story_5004_50042001_142_dialog_content = "(Hmm, kapan dia sampai di sini?)",
  ui_story_5004_50042001_143_dialog_content = "Tidak buruk, meskipun itu adalah duo sebelumnya.",
  ui_story_5004_50042001_144_dialog_content = "Apa?",
  ui_story_5004_50042001_145_dialog_content = "(Dia pergi. Apakah dia mengejek? Apa yang dia maksud dengan itu?)",
  ui_story_5004_50042001_146_dialog_content = "Ciuman dari Manticore! Ciuman dari Manticore! Ciuman dari Manticore!",
  ui_story_5004_50042001_147_dialog_content = "Luar biasa, Ciuman Manticore!",
  ui_story_5004_50042001_148_dialog_content = "Semua orang menyukai pertunjukan. Bahkan Beryl tampaknya tergerak.",
  ui_story_5004_50042001_149_dialog_content = "Apakah Anda mendapatkan semua itu di video?",
  ui_story_5004_50042001_150_dialog_content = "Ya, My L... Pak!",
  ui_story_5004_50042001_151_dialog_content = "Itu grup yang menyenangkan.",
  ui_story_5004_50042001_154_dialog_content = "Ciuman Manticore...",
  ui_story_5004_50042001_155_dialog_content = "Mendapat 10 sempurna!",
  ui_story_5004_50042201_1_dialog_content = "Bersulang!",
  ui_story_5004_50042201_2_dialog_content = "Ha.",
  ui_story_5004_50042201_3_dialog_content = "Apa ide besar dengan semua jus!",
  ui_story_5004_50042201_4_dialog_content = "Tapi bukankah kamu juga minum jus?",
  ui_story_5004_50042201_5_dialog_content = "Tidak, terima kasih kepada Anda!",
  ui_story_5004_50042201_6_dialog_content = "Hahaha!",
  ui_story_5004_50042201_7_dialog_content = "Anda luar biasa, Carleen, Vice, dan Smokey!",
  ui_story_5004_50042201_8_dialog_content = "Anda bergerak di atas panggung seperti superstar!",
  ui_story_5004_50042201_9_dialog_content = "Bahkan Beryl pun sampai meneteskan air mata, bukan?",
  ui_story_5004_50042201_10_dialog_content = "Oh... Ya, itu adalah pertunjukan yang sangat menyentuh.",
  ui_story_5004_50042201_11_dialog_content = "Suara dan gerakan Anda sangat menawan.",
  ui_story_5004_50042201_12_dialog_content = "Pertunjukan yang sempurna, seperti yang disebut Beryl!",
  ui_story_5004_50042201_13_dialog_content = "Penasaran seperti apa hadiah misterinya?",
  ui_story_5004_50042201_14_dialog_content = "Ngomong-ngomong, aku juga penasaran.",
  ui_story_5004_50042201_15_dialog_content = "Aku bisa bertanya pada Bonacie, tapi dia akan memberiku senyuman misterius dan menyuruhku menunggu sampai besok.",
  ui_story_5004_50042201_16_dialog_content = "Ya, saya tertarik untuk melihat apa itu.",
  ui_story_5004_50042201_17_dialog_content = "Saya harap ini semacam sirup yang luar biasa. Jadi kita bisa menarik lebih banyak pelanggan!",
  ui_story_5004_50042201_18_dialog_content = "Mungkin saya harus membuka toko es serut di Lumopolis!",
  ui_story_5004_50042201_19_dialog_content = "Saya pikir Raphael mungkin mengejar Anda sebagai penjaja tanpa izin.",
  ui_story_5004_50042201_20_dialog_content = "Hee, untuk Vice, aku akan memberinya waktu satu menit!",
  ui_story_5004_50042201_21_dialog_content = "Hai, selamat untuk kalian semua.",
  ui_story_5004_50042201_22_dialog_content = "Terima kasih, Genevieve? Apakah Anda di sini hanya untuk memberi selamat kepada kami?",
  ui_story_5004_50042201_23_dialog_content = "Tentu saja, saya seorang bangsawan. Hmph.",
  ui_story_5004_50042201_24_dialog_content = "Untuk apa kau menganggapku, seorang gadis kecil yang mengeluh tentang kehilangannya?",
  ui_story_5004_50042201_25_dialog_content = "Anda tidak menangis? Anda telah tumbuh banyak, Jenewa. Dia sangat cengeng.",
  ui_story_5004_50042201_26_dialog_content = "Apa? Aku harus membunuhmu sekarang!",
  ui_story_5004_50042201_27_dialog_content = "Oke oke. Ayo duduk dan minum bersama kami. Biarkan masa lalu menjadi masa lalu?",
  ui_story_5004_50042201_28_dialog_content = "Smokey meraih lengan Genevieve dan menyeretnya ke kursi berikutnya.",
  ui_story_5004_50042201_29X1_dialog_content = "Coba ini!",
  ui_story_5004_50042201_29X2_dialog_content = "Ck, menyebalkan sekali.",
  ui_story_5004_50042201_29X3_dialog_content = "Apa ini…?",
  ui_story_5004_50042201_29X4_dialog_content = "Ya, bukankah rasanya seperti vintage di kedai Petyaburg itu, yang biasa kita kunjungi?",
  ui_story_5004_50042201_29X5_dialog_content = "Sebagian besar, saya kira. Sudah terlalu lama aku tidak bisa mengingatnya.",
  ui_story_5004_50042201_29X6_dialog_content = "Mengapa nama Kiss of the Manticore?",
  ui_story_5004_50042201_29X7_dialog_content = "Seperti minuman ini, Anda harus tahu alasannya. Saya tidak berpikir Anda akan melupakannya.",
  ui_story_5004_50042201_29X8_dialog_content = "...",
  ui_story_5004_50042201_30_dialog_content = "(Betapa rumitnya antara keduanya.)",
  ui_story_5004_50042201_31_dialog_content = "Saya ingin melihat trik sulap Fleur lagi.",
  ui_story_5004_50042201_32_dialog_content = "Aku masih tidak mengerti bagaimana dia melakukannya.",
  ui_story_5004_50042201_33_dialog_content = "Tentu saja, saya senang melakukannya untuk semua orang lagi.",
  ui_story_5004_50042201_34_dialog_content = "Bagaimana dengan tempat yang lebih pribadi kali ini?",
  ui_story_5004_50042201_35_dialog_content = "Kami harus melawan tidak hanya orang-orang tetapi juga kucing dan anjing, hanya untuk mengeluarkan Anda dari sana.",
  ui_story_5004_50042201_36_dialog_content = "Dan saya berterima kasih untuk itu. Biarkan aku menambal lukamu nanti.",
  ui_story_5004_50042201_37_dialog_content = "Robotnya juga hampir selesai, saya butuh bantuan Anda.",
  ui_story_5004_50042201_38_dialog_content = "Tidak masalah, tapi jangan mengganggu saya minum sekarang.",
  ui_story_5004_50042201_39_dialog_content = "Apakah droidnya hampir selesai?",
  ui_story_5004_50042201_40_dialog_content = "Departemen penelitian di Illumina membutuhkan beberapa bulan untuk membangunnya!",
  ui_story_5004_50042201_41_dialog_content = "Ini semua berkat Nona Bonacie. Saya mendapat akses ke banyak peralatan dan file bermanfaat yang bekerja untuknya.",
  ui_story_5004_50042201_42_dialog_content = "Ciptaan saya yang sempurna, NO. 1 battlebot di Rediesel Wrench...",
  ui_story_5004_50042201_43_dialog_content = "Akan lahir malam ini!",
  ui_story_5004_50042201_44_dialog_content = "(Pertama kali saya melihat Fleur seserius ini.)",
  ui_story_5004_50042201_45_dialog_content = "(Fleur harus benar-benar menyukai mesin dan robot.)",
  ui_story_5004_50042201_46_dialog_content = "Apa itu tadi...?",
  ui_story_5004_50042201_47_dialog_content = "Oh...",
  ui_story_5004_50042201_48_dialog_content = "Kamu berkeringat, Beryl!",
  ui_story_5004_50042201_49_dialog_content = "Bisakah Anda membawa saya kembali ke kamar, Raphael?",
  ui_story_5004_50042201_50_dialog_content = "Beryl tidak enak badan, PlayerName. Kita harus pergi.",
  ui_story_5004_50042201_51_dialog_content = "Apakah Beryl belum pulih? Dia terlalu memaksakan diri terakhir kali, tapi itu beberapa hari yang lalu.",
  ui_story_5004_50042201_52_dialog_content = "Kondisinya sepertinya belum membaik.",
  ui_story_5004_50042201_53_dialog_content = "Ini mungkin lebih rumit dari yang kita duga. Oh, apakah Raphael berbicara denganmu tentang file di Pyrrhus?",
  ui_story_5004_50042201_54_dialog_content = "Ya, saya mengirim permintaan untuk memberikan Beretta semua akses.",
  ui_story_5004_50042201_55_dialog_content = "Jika ada informasi yang berguna, kita hanya bisa mengandalkannya",
  ui_story_5004_50042301_1_dialog_content = "Jika ritualnya berhasil...",
  ui_story_5004_50042301_2_dialog_content = "Caelestite harus membuka segel Gerakan dan memainkannya.",
  ui_story_5004_50042301_3_dialog_content = "Kemuliaan Raja sekali lagi akan bersinar di pantai ini dan menghukum para Aurorian yang sombong.",
  ui_story_5004_50042301_4_dialog_content = "Dipahami! Yakinlah, saya tidak akan menyia-nyiakan usaha.",
  ui_story_5004_50042301_5_dialog_content = "Saya di sini.",
  ui_story_5004_50042301_6_dialog_content = "Tidak bisakah kamu mengetuk, Bonacie?",
  ui_story_5004_50042301_7_dialog_content = "Berhenti membuang-buang waktu. Apa yang Anda inginkan dengan saya?",
  ui_story_5004_50042301_8_dialog_content = "Gerakan akan segera digali dan segelnya...",
  ui_story_5004_50042301_9_dialog_content = "Saya tahu, saya tahu, Caelestite harus menghapusnya, bukan?",
  ui_story_5004_50042301_10_dialog_content = "Saya akan meminta PlayerName untuk melakukan itu.",
  ui_story_5004_50042301_11_dialog_content = "Tidakkah kamu penasaran dengan apa yang kami rencanakan?",
  ui_story_5004_50042301_12_dialog_content = "Tidak. Saya hanya ingin tangan saya di Gerakan.",
  ui_story_5004_50042301_13_dialog_content = "Dan salah satu Aurorian di pesta itu bisa mengalahkanmu tanpa berkeringat.",
  ui_story_5004_50042301_14_dialog_content = "Jika Anda benar-benar licik, saya harap mereka setidaknya meninggalkan mayat Anda dalam keadaan utuh.",
  ui_story_5004_50042301_15_dialog_content = "Tapi penipuan menghasilkan uang itu benar-benar menggelikan, bukan?",
  ui_story_5004_50042301_16_dialog_content = "Anda masih Aurorian yang sama menyebalkannya seperti yang pernah Anda alami!",
  ui_story_5004_50042301_17_dialog_content = "aku akan mendapatkanmu...",
  ui_story_5004_50042301_18_dialog_content = "Harap tenang, Tuan Prinny!",
  ui_story_5004_50042301_19_dialog_content = "Apa yang kamu lakukan di sini? Sudah waktunya bagi Anda untuk mengiklankan pelajaran yoga, bukan?",
  ui_story_5004_50042301_20_dialog_content = "Sudahlah, saya masih harus melihat PlayerName. Anda bisa bermain di antara Anda sendiri.",
  ui_story_5004_50042301_21_dialog_content = "Tunggu, tunggu sebentar, Bonacie!",
  ui_story_5004_50042301_22_dialog_content = "Saya ingin Anda mendengar slogan-slogan baru yang saya tulis!",
  ui_story_5004_50042301_23_dialog_content = "...",
  ui_story_5004_50042301_24_dialog_content = "Seharusnya aku yang memanipulasi si Aurorian, tapi akulah yang marah.",
  ui_story_5004_50042301_25_dialog_content = "Belum lagi antek-antek tak berguna yang menjadikan pelajaran palsu sebagai prioritas!",
  ui_story_5004_50042301_26_dialog_content = "Ah...",
  ui_story_5004_50042301_35_dialog_content = "Di sini, berbaring di tempat tidur, Beryl!",
  ui_story_5004_50042301_36_dialog_content = "Hmm, suhu tubuh Anda sangat tinggi, dan Anda berkeringat deras... Anda pasti merasa tidak enak.",
  ui_story_5004_50042301_37_dialog_content = "Aku... aku tergantung di sana...",
  ui_story_5004_50042301_38_dialog_content = "Biarkan aku mengambilkanmu handuk untuk menyeka keringat!",
  ui_story_5004_50042301_39_dialog_content = "Tidak apa-apa, tapi...",
  ui_story_5004_50042301_40_dialog_content = "Bisakah kamu berbaring denganku sebentar?",
  ui_story_5004_50042301_41_dialog_content = "Bukan masalah!",
  ui_story_5004_50042301_42_dialog_content = "Beryl yang malang, aku bisa merasakan panas keluar darimu. Handuk basah atau kompres es akan mendinginkan Anda sedikit, apakah Anda yakin tidak membutuhkannya?",
  ui_story_5004_50042301_43_dialog_content = "Tetap... Maukah? Ini akan dilakukan...",
  ui_story_5004_50042301_44_dialog_content = "Setelah upacara besok, kami akan meminta PlayerName untuk membawa kami ke Lumopolis bersama Soroz.",
  ui_story_5004_50042301_45_dialog_content = "Fasilitas di sana harus melakukan pekerjaan yang lebih baik untuk memantau kondisi Anda.",
  ui_story_5004_50042301_46_dialog_content = "Dan Anda akan menemukan Lumopolis penuh dengan orang-orang yang menarik, Beryl. Saya juga bisa memperkenalkan malaikat lain kepada Anda.",
  ui_story_5004_50042301_47_dialog_content = "Mereka semua akan sangat menyukaimu!",
  ui_story_5004_50042301_48_dialog_content = "Oh, kami memiliki malaikat bernama Uriel. Dia dulu lesu sepertimu, Beryl!",
  ui_story_5004_50042301_49_dialog_content = "Tapi seperti Anda, dia sangat dapat dipercaya dan dapat diandalkan!",
  ui_story_5004_50042301_50_dialog_content = "Anda pikir saya dapat dipercaya dan dapat diandalkan?",
  ui_story_5004_50042301_51_dialog_content = "Sama sekali! Dan kota ini memiliki banyak toko berkelas dan berbagai jenis restoran.",
  ui_story_5004_50042301_52_dialog_content = "Aku bisa mengajakmu berbelanja di tempat favoritku!",
  ui_story_5004_50042301_53_dialog_content = "Jika Anda suka membuat kue, kita bisa mengunjungi toko roti yang biasa saya kunjungi!",
  ui_story_5004_50042301_54_dialog_content = "Pemiliknya sangat baik dan mengajari saya membuat kue yang berbeda!",
  ui_story_5004_50042301_55_dialog_content = "Oh, dan Aula Musik Lumopolis! Mereka mendapatkan artis yang luar biasa untuk bermain di sana, meskipun tiketnya mungkin sulit didapat ...",
  ui_story_5004_50042301_56_dialog_content = "Anu…",
  ui_story_5004_50042301_57_dialog_content = "Ya, Beryl?",
  ui_story_5004_50042301_58_dialog_content = "Aku punya sesuatu yang aku tidak tahu apakah aku harus memberitahumu...",
  ui_story_5004_50042301_59_dialog_content = "Katakan padaku, katakan padaku!",
  ui_story_5004_50042301_60_dialog_content = "aku sangat takut...",
  ui_story_5004_50042301_61_dialog_content = "... bahwa saya ... tidak bisa pergi dari sini.",
  ui_story_5004_50042301_62_dialog_content = "Apa? Bagaimana bisa?",
  ui_story_5004_50042301_63_dialog_content = "Saya mengalami mimpi buruk, setiap malam...",
  ui_story_5004_50042301_64_dialog_content = "... Memiliki mimpi yang sama, itu terus memburuk ...",
  ui_story_5004_50042301_65_dialog_content = "Itu dimulai dengan saya hanya mendengar suara samar ...",
  ui_story_5004_50042301_66_dialog_content = "Itu terus berbicara kepada saya ... membuat saya mengingat banyak hal yang telah saya lupakan ...",
  ui_story_5004_50042301_67_dialog_content = "(Dari masa lalu Beryl? Mungkinkah tentang Gautiers dan Pyrrhuses?)",
  ui_story_5004_50042301_68_dialog_content = "Dia mengatakan banyak hal yang tidak kuingat dan yang tidak ingin kuingat... Aku takut.",
  ui_story_5004_50042301_69_dialog_content = "Suara itu akhirnya berulang padaku ...",
  ui_story_5004_50042301_70_dialog_content = "Bahwa tubuh saya akan menyerah dan kehilangan kendali, dengan pikiran saya jatuh ke dalam spiral tak berujung setelah membunuh semua orang.",
  ui_story_5004_50042301_71_dialog_content = "!!",
  ui_story_5004_50042301_72_dialog_content = "Saya berusaha sangat keras untuk menyingkirkan mimpi-mimpi itu dari kepala saya, tetapi mereka tidak mau pergi...",
  ui_story_5004_50042301_73_dialog_content = "Dan aku bisa merasakan tubuhku melemah...",
  ui_story_5004_50042301_74_dialog_content = "Oh, Beril...",
  ui_story_5004_50042301_75_dialog_content = "Anda seharusnya tidak percaya apa pun dalam mimpi seperti itu!",
  ui_story_5004_50042301_76_dialog_content = "Ah...",
  ui_story_5004_50042301_77_dialog_content = "Mimpi hanya itu, mimpi. Mereka tidak berarti apa-apa.",
  ui_story_5004_50042301_78_dialog_content = "Anda merasa tidak enak badan mungkin karena Anda telah melakukan sesuatu untuk semua orang selama dua hari terakhir, dan mungkin karena terlalu banyak kegembiraan.",
  ui_story_5004_50042301_79_dialog_content = "Adapun mimpi, saya akan memeriksa dengan PlayerName, mungkin kemampuan psikis itu dapat membantu menjernihkan Anda.",
  ui_story_5004_50042301_80_dialog_content = "Istirahat saja sementara aku pergi!",
  ui_story_5004_50042301_81_dialog_content = "Dengarkan aku dan santai. Kami akan kembali ke Lumopolis besok!",
  ui_story_5004_50042301_82_dialog_content = "Oke.",
  ui_story_5004_50042301_83_dialog_content = "Aku akan segera kembali, oke?",
  ui_story_5004_50042301_84_dialog_content = "Hampir saja...",
  ui_story_5004_50042301_85_dialog_content = "Tidak bisa membiarkan Anda kembali dalam waktu dekat.",
  ui_story_5004_50042301_86_dialog_content = "Apa? Apa kamu yakin?",
  ui_story_5004_50042301_87_dialog_content = "Ya. Dia hampir menabrakku.",
  ui_story_5004_50042301_88_dialog_content = "Jika itu benar, aku harus memberi tahu Ratu.",
  ui_story_5004_50042301_89_dialog_content = "Saya baru saja menyampaikan informasi penting, jadi tentang bonus saya bulan ini...",
  ui_story_5004_50042301_90_dialog_content = "Anda akan pergi sekarang.",
  ui_story_5004_50042301_91_dialog_content = "Tidak berguna!",
  ui_story_5004_50042301_92_dialog_content = "Harap tenang.",
  ui_story_5004_50042301_93_dialog_content = "Apakah Anda tahu apa yang saya lalui untuk meletakkan semua bagian di tempatnya? Sekarang karena semua kebodohanmu...",
  ui_story_5004_50042301_94_dialog_content = "Mereka menjauh!",
  ui_story_5004_50042301_95_dialog_content = "Kami meminta maaf!",
  ui_story_5004_50042301_96_dialog_content = "Orang-orang yang tidak berharga. Kurasa aku harus melakukannya sendiri.",
  ui_story_5004_50042301_97_dialog_content = "Sayang sekali bahwa bagian ini adalah yang paling saya hargai ...",
  ui_story_5004_50042301_98_dialog_content = "Hee...",
  ui_story_5004_50042401_1_dialog_content = "Ikutlah dengan saya sebentar, PlayerName!",
  ui_story_5004_50042401_2_dialog_content = "Berhenti menyeretku. Saya sedang mendiskusikan bagaimana mengembangkan bisnis es serut dengan Vice!",
  ui_story_5004_50042401_3_dialog_content = "Kita dapat meningkatkannya dengan uang yang kita menangkan besok, kemudian ke hal-hal yang lebih besar dan lebih baik!",
  ui_story_5004_50042401_4_dialog_content = "Berhenti memikirkan itu sekarang. Little Beryl sedang dalam kondisi buruk!",
  ui_story_5004_50042401_5_dialog_content = "Ada apa dengan Beryl?",
  ui_story_5004_50042401_6_dialog_content = "Saya pikir kita harus membawanya kembali ke Lumopolis untuk perawatan segera.",
  ui_story_5004_50042401_7_dialog_content = "Itu benar, kita harus kembali, PlayerName.",
  ui_story_5004_50042401_8_dialog_content = "Jangan lupa kami datang ke sini untuk menghibur Beryl.",
  ui_story_5004_50042401_9_dialog_content = "Tapi jika itu benar-benar membuatnya lebih buruk, kita harus pergi!",
  ui_story_5004_50042401_10_dialog_content = "Kamu benar. Mari kita lihat bagaimana keadaannya sekarang.",
  ui_story_5004_50042401_11_dialog_content = "Aduh, itu menyakitkan! Aku tidak melihat apapun selain kegelapan...",
  ui_story_5004_50042401_12_dialog_content = "Saya minta maaf! Apakah Anda baik-baik saja, Bonacie?",
  ui_story_5004_50042401_13_dialog_content = "Oh, kita harus pergi ke Lumopolis untuk urusan mendesak, tinggalkan hadiah untuk waktu berikutnya!",
  ui_story_5004_50042401_14_dialog_content = "Apa? Bagaimana apanya?",
  ui_story_5004_50042401_15_dialog_content = "Gerakan suci, kenapa sekarang?",
  ui_story_5004_50042401_16_dialog_content = "Oke, aku punya semua orang di sini...",
  ui_story_5004_50042401_17_dialog_content = "Beryl kecil...?",
  ui_story_5004_50042401_18_dialog_content = "Dimana Beryl? Ke mana dia pergi?",
  ui_story_5004_50042401_19_dialog_content = "Berhenti mengguncangku. Aku tidak membawanya.",
  ui_story_5004_50042401_20_dialog_content = "Aku menyuruhnya untuk tetap diam dan beristirahat!",
  ui_story_5004_50042401_21_dialog_content = "Cepat, pikirkan sesuatu. Berbahaya baginya untuk berlarian sakit!",
  ui_story_5004_50042401_22_dialog_content = "PlayerName! PlayerName!",
  ui_story_5004_50042401_23_dialog_content = "Gunakan kemampuan psikis Anda dan bantu Raphael keluar, PlayerName!",
  ui_story_5004_50042401_24_dialog_content = "Oke, oke ... Tapi saya tidak bisa melakukannya dengan Anda mengguncang saya!",
  ui_story_5004_50042401_25_dialog_content = "Tenang dan lepaskan PlayerName, Raphael.",
  ui_story_5004_50042401_26_dialog_content = "Waow…",
  ui_story_5004_50042401_27_dialog_content = "Tidak di hotel.",
  ui_story_5004_50042401_28_dialog_content = "Tapi aku masih bisa mengikuti jejaknya.",
  ui_story_5004_50042401_29_dialog_content = "Dia sepertinya menuju ke tebing tempat patung batu itu berada.",
  ui_story_5004_50042401_30_dialog_content = "Suruh semua orang mencari Beryl juga, PlayerName!",
  ui_story_5004_50042401_31_dialog_content = "Semua orang? Apakah itu perlu?",
  ui_story_5004_50042401_32_dialog_content = "Liburan itu pasti membuatmu bodoh, PlayerName.",
  ui_story_5004_50042401_33_dialog_content = "Hotel ini lebih aman karena semua tindakan keamanan.",
  ui_story_5004_50042401_34_dialog_content = "Tapi tidakkah kamu ingat gerombolan Eclipsites yang kita temui dalam perjalanan ke sini?",
  ui_story_5004_50042401_35_dialog_content = "Bagaimana jika Beryl secara tidak sengaja menemukan sesuatu yang serupa?",
  ui_story_5004_50042401_36_dialog_content = "Itu benar...",
  ui_story_5004_50042401_37_dialog_content = "Oke, mari kita minta semua orang untuk membantu!",
  ui_story_5004_50042401_38_dialog_content = "Terima kasih semua untuk datang ... bahkan Genevieve ada di sini.",
  ui_story_5004_50042401_39_dialog_content = "Kami berteman sekarang dan teman harus saling membantu.",
  ui_story_5004_50042401_40_dialog_content = "Dia sebenarnya berhati hangat, meskipun kepribadiannya agresif.",
  ui_story_5004_50042401_41_dialog_content = "Apa? Saya datang karena saya tidak ingin melewatkan kesempatan untuk mempermalukan Anda!",
  ui_story_5004_50042401_42_dialog_content = "Saya harap Anda berdua dapat memperhalus perbedaan Anda. Sementara itu, kita harus menemukan Beryl!",
  ui_story_5004_50042401_43_dialog_content = "Apakah Anda yakin seperti ini, PlayerName? Hutan terasa menyeramkan.",
  ui_story_5004_50042401_44_dialog_content = "Ya, ini arah Beryl pergi.",
  ui_story_5004_50042401_45_dialog_content = "Tapi rasanya seperti kita hanya berputar-putar, dan itu benar-benar berbeda dari siang hari.",
  ui_story_5004_50042401_46_dialog_content = "(Perjalanan itu tampaknya berlangsung selamanya, dan siapa yang tahu makhluk apa yang membuat semua suara menakutkan itu...)",
  ui_story_5004_50042401_47_dialog_content = "Tunggu, aku mendengar sesuatu.",
  ui_story_5004_50042401_48_dialog_content = "Hei!",
  ui_story_5004_50042401_49_dialog_content = "Woah!",
  ui_story_5004_50042401_50_dialog_content = "Bonasi? Apa yang kamu lakukan di sini?",
  ui_story_5004_50042401_51_dialog_content = "Bukankah kamu bilang kamu akan pergi? Saya mencoba untuk mendapatkan Anda <color=#FFB400>hadiah utama</color> secepatnya.",
  ui_story_5004_50042401_52_dialog_content = "Kenapa kalian semua di sini?",
  ui_story_5004_50042401_53_dialog_content = "Apakah Anda mencari satu petualangan terakhir sebelum kembali?",
  ui_story_5004_50042401_54_dialog_content = "Bisakah saya ikut?",
  ui_story_5004_50042401_55_dialog_content = "Tidak, ini bukan petualangan!",
  ui_story_5004_50042401_56_dialog_content = "Beryl hilang. Kami ingin kembali karena kondisinya semakin parah.",
  ui_story_5004_50042401_57_dialog_content = "Raphael khawatir tentang itu atau kemungkinan dia bertemu dengan Eclipsites.",
  ui_story_5004_50042401_58_dialog_content = "Karena itu Beryl, sebagai sesama True Order, saya harus bersikeras untuk bergabung dengan Anda.",
  ui_story_5004_50042401_59_dialog_content = "Tapi ini adalah tempat yang sangat berbahaya. Ada hadiah lebih jahat dari sekedar Eclipsites!",
  ui_story_5004_50042401_60_dialog_content = "Ini bukan petualangan, jadi tolong hentikan peringatannya!",
  ui_story_5004_50042401_61_dialog_content = "Aku bisa merasakan Beryl di atas tebing... dan dia berhenti bergerak.",
  ui_story_5004_50042401_62_dialog_content = "Tapi kita masih belum bisa keluar dari hutan...",
  ui_story_5004_50042401_63_dialog_content = "Karena ini untuk Beryl, aku akan memandumu keluar dari sini. Ikuti aku.",
  ui_story_5004_50042401_64_dialog_content = "Beril!",
  ui_story_5004_50042401_65_dialog_content = "Jangan mendekat...!",
  ui_story_5004_50042401_66_dialog_content = "Berhenti bergerak maju, berbahaya di sana!",
  ui_story_5004_50042401_67_dialog_content = "Aku tahu itu, jadi jangan mendekat...",
  ui_story_5004_50042401_68_dialog_content = "Tenang, Beryl. Beritahu kami mengapa Anda ingin datang ke sini?",
  ui_story_5004_50042401_69_dialog_content = "Aku... Aku juga tidak yakin...",
  ui_story_5004_50042401_70_dialog_content = "Setelah Raphael pergi, saya menjatuhkan diri di tempat tidur, benar-benar terkuras ...",
  ui_story_5004_50042401_71_dialog_content = "Tapi aku sadar aku tidak bisa bergerak...",
  ui_story_5004_50042401_72_dialog_content = "Kemudian sebuah lengan gelap melingkari leherku dan menutupi mataku.",
  ui_story_5004_50042401_73_dialog_content = "Itu tertawa menakutkan di telingaku dan aku pingsan ...",
  ui_story_5004_50042401_74_dialog_content = "Apakah itu suara yang sama yang kamu dengar dalam mimpimu?",
  ui_story_5004_50042401_75_dialog_content = "Ya…",
  ui_story_5004_50042401_76_dialog_content = "Saya tidak tahu apa yang saya lakukan di sini ...",
  ui_story_5004_50042401_77_dialog_content = "Atau apa yang akan terjadi padaku...",
  ui_story_5004_50042401_78_dialog_content = "Jika suara itu benar... bahwa aku akan membunuh kalian semua...",
  ui_story_5004_50042401_79_dialog_content = "Tapi itu hanya mimpi buruk!",
  ui_story_5004_50042401_80_dialog_content = "Meski begitu, mereka membawaku ke sini!",
  ui_story_5004_50042401_81_dialog_content = "Aku tidak ingin orang lain mati di tanganku!",
  ui_story_5004_50042401_82_dialog_content = "Berhenti dengan pembicaraan gila!",
  ui_story_5004_50042401_83_dialog_content = "...",
  ui_story_5004_50042401_84_dialog_content = "Anda akan baik-baik saja! Bukankah Anda salah satu dari Warriors of the Beach sekarang?",
  ui_story_5004_50042401_85_dialog_content = "(Bagaimana itu akan membantu?)",
  ui_story_5004_50042401_86_dialog_content = "Raphael…",
  ui_story_5004_50042401_87_dialog_content = "Bukankah kita berjanji untuk pergi ke Lumopolis bersama?",
  ui_story_5004_50042401_88_dialog_content = "Tunggu...",
  ui_story_5004_50042401_89_dialog_content = "Kembali. Di sana berbahaya.",
  ui_story_5004_50042401_90_dialog_content = "Kristal berkedip tanpa henti... Aku tidak suka ini.",
  ui_story_5004_50042401_91_dialog_content = "Hati-hati, kristal akan meledak!",
  ui_story_5004_50042401_92_dialog_content = "Awas, PlayerName!",
  ui_story_5004_50042401_93_dialog_content = "Beril kecil!",
  ui_story_5004_50042401_95_dialog_content = "…!",
  ui_story_5004_50042401_96_dialog_content = "Beril!",
  ui_story_5004_50042401_97_dialog_content = "Raphael?",
  ui_story_5004_50042401_98_dialog_content = "Pegang tanganku!",
  ui_story_5004_50042401_99_dialog_content = "Oke...!",
  ui_story_5004_50042401_100_dialog_content = "Maaf... Ini semua karena aku...",
  ui_story_5004_50042401_101_dialog_content = "Bahkan untuk Malaikat Pelindung sepertimu, Raphael... Kau tidak akan bisa bertahan jika jatuh dari ketinggian ini.",
  ui_story_5004_50042401_102_dialog_content = "Aku ingin melihat Lumopolis... bersamamu...",
  ui_story_5004_50042401_103_dialog_content = "<size=45>APA KATAMU?</size>",
  ui_story_5004_50042401_104_dialog_content = "Lihat Lumopolis... bersamamu?",
  ui_story_5004_50042401_105_dialog_content = "<size=45>TIDAK, SEBELUM ITU!</size>",
  ui_story_5004_50042401_106_dialog_content = "Bahkan untuk Malaikat Pelindung sepertimu...?",
  ui_story_5004_50042401_107_dialog_content = "Semua misil ditembakkan... Grrr... Pilar Do'a siap... Kekuatan maksimal!",
  ui_story_5004_50042401_108_dialog_content = "<size=45>MALAIKAT BISA TERBANG, BERYL!</size>",
  ui_story_5004_50042401_109_dialog_content = "Tunggu, Beryl! Kami hampir kehabisan energi!",
  ui_story_5004_50042401_110_dialog_content = "Lepaskan aku, Rafael! Itu tidak bisa menahan kami berdua. Kita akan...",
  ui_story_5004_50042401_111_dialog_content = "Hentikan!",
  ui_story_5004_50042401_112_dialog_content = "Aku tidak akan pernah melepaskannya!",
  ui_story_5004_50042401_113_dialog_content = "<color=#e8d9bb>Kk, Kk!</color>",
  ui_story_5004_50042401_114_dialog_content = "(Hampir mencapai batas?)",
  ui_story_5004_50042401_115_dialog_content = "<size=50><color=#e8d9bb>LEDAKAN!</color></size>",
  ui_story_5004_50042401_116_dialog_content = "Bangun, Raphael, bangun...",
  ui_story_5004_50042401_117_dialog_content = "Beryl...",
  ui_story_5004_50042401_118_dialog_content = "Kamu baik-baik saja, Beryl?",
  ui_story_5004_50042401_119_dialog_content = "Aku baik-baik saja...",
  ui_story_5004_50042401_120_dialog_content = "Terima kasih…",
  ui_story_5004_50042401_121_dialog_content = "Senang melihatmu baik-baik saja. Anda melakukannya dengan baik.",
  ui_story_5004_50042401_123_dialog_content = "Sekarang kita akan menunggu sampai PlayerName datang untuk kita.",
  ui_story_5004_50042401_124_dialog_content = "Uh, Raphael, apakah itu...?",
  ui_story_5004_50042401_125_dialog_content = "Grrrr!",
  ui_story_5004_50042401_126_dialog_content = "Gah... Gah...!",
  ui_story_5004_50042401_127_dialog_content = "Eclipsites... begitu banyak dari mereka.",
  ui_story_5004_50042401_128_dialog_content = "Masih bisakah kamu bertarung, Beryl?",
  ui_story_5004_50042401_129_dialog_content = "Ya!",
  ui_story_5004_50042401_130_dialog_content = "(Anda sebaiknya segera sampai di sini, PlayerName...)",
  ui_story_5004_50042501_1_dialog_content = "Bawa kami ke bawah, Bonacie!",
  ui_story_5004_50042501_2_dialog_content = "Saya mendapatkannya. Dengan cara ini, dan tetap dekat kecuali jika Anda ingin monster menangkap Anda, bukan?",
  ui_story_5004_50042501_2X1_dialog_content = "Kita harus mendapatkan Gerakan secepat mungkin untuk Bonacie.",
  ui_story_5004_50042501_2X2_dialog_content = "Kemudian minta dia meminta Caelestite untuk membuka segelnya, jadi kita bisa memainkannya untuk membangunkan Desolate Monarch.",
  ui_story_5004_50042501_2X3_dialog_content = "Lord Prinny, kami melewati semua kesulitan untuk menjadi tuan rumah Penguasa Laut dan menyedot energi para Aurorian.",
  ui_story_5004_50042501_2X4_dialog_content = "Dan sekarang kita harus mengelabui Caelestite untuk melepaskan segelnya, lalu menyuruh Bonacie memainkan lagunya...",
  ui_story_5004_50042501_2X5_dialog_content = "Apakah Anda yakin itu akan membangunkan pria Monarch itu? Apa untungnya bagi kita?",
  ui_story_5004_50042501_2X6_dialog_content = "Ini adalah perintah dari salah satu dari Delapan Wraiths. Saya mendengar bahwa Monarch adalah Eclipsite yang sangat kuat.",
  ui_story_5004_50042501_2X7_dialog_content = "Jika itu terbangun, kita pasti bisa menyingkirkan para Aurorian yang menyebalkan itu!",
  ui_story_5004_50042501_2X8_dialog_content = "Saya harap begitu. Terlalu gelap... Hei, kenapa kamu berhenti tiba-tiba?",
  ui_story_5004_50042501_2X9_dialog_content = "Aku mendengar suara pertempuran. Mari kita berlindung!",
  ui_story_5004_50042501_3_dialog_content = "Kita seharusnya baik-baik saja bersembunyi di sini.",
  ui_story_5004_50042501_4_dialog_content = "Tidak berharap menemukan gua, tapi gelap. . .",
  ui_story_5004_50042501_5_dialog_content = "Grrrr!",
  ui_story_5004_50042501_6_dialog_content = "Ugh, apakah ada akhir dari Eclipsites yang menyebalkan ini?",
  ui_story_5004_50042501_7_dialog_content = "Bagaimana kabarmu, Beryl?",
  ui_story_5004_50042501_8_dialog_content = "Huff, puff... aku baik-baik saja... aku masih bisa bertarung...",
  ui_story_5004_50042501_10_dialog_content = "Ahh!",
  ui_story_5004_50042501_11_dialog_content = "Groar!",
  ui_story_5004_50042501_12_dialog_content = "Sial, mereka menghalangi jalan kita kembali!",
  ui_story_5004_50042501_13_dialog_content = "Sampah menjengkelkan!",
  ui_story_5004_50042501_14_dialog_content = "Rafael, Beryl!",
  ui_story_5004_50042501_15_dialog_content = "Kau baik-baik saja?",
  ui_story_5004_50042501_16_dialog_content = "Anda terlalu lambat, PlayerName!",
  ui_story_5004_50042501_17_dialog_content = "Bagaimana Anda bisa membuat wanita menunggu begitu lama?",
  ui_story_5004_50042501_18_dialog_content = "Maaf. Mengapa kita tidak mengeluarkannya di Eclipsites?",
  ui_story_5004_50042601_1_dialog_content = "Fiuh, itu akhirnya berakhir.",
  ui_story_5004_50042601_2_dialog_content = "Raphael, Beryl, apakah kamu terluka?",
  ui_story_5004_50042601_3_dialog_content = "Kami baik-baik saja. Little Beryl tidak akan terluka selama aku ada!",
  ui_story_5004_50042601_4_dialog_content = "Ya... aku punya Raphael yang melindungiku...",
  ui_story_5004_50042601_5_dialog_content = "Karena semuanya baik-baik saja, mari kita kembali ke hotel.",
  ui_story_5004_50042601_6_dialog_content = "Raphael, aku, dan Aurorian lainnya di Colossus akan membantu menyelesaikan mimpi buruk Beryl.",
  ui_story_5004_50042601_7_dialog_content = "Betul sekali. Genevieve tahu segalanya, dia pasti akan membantumu.",
  ui_story_5004_50042601_8_dialog_content = "Hei, kenapa kau memakainya padaku? Saya di sini hanya untuk membantu pertarungan.",
  ui_story_5004_50042601_9_dialog_content = "Ck. Baik, saya kenal seorang ahli mineral yang sangat baik. Aku akan bertanya padanya.",
  ui_story_5004_50042601_10_dialog_content = "Kalau begitu mari kita kembali dan berangkat ke Lumopolis.",
  ui_story_5004_50042601_11_dialog_content = "Maukah Anda memimpin kami kembali, Bonacie?",
  ui_story_5004_50042601_12_dialog_content = "Bonacie?",
  ui_story_5004_50042601_13_dialog_content = "Tunggu sebentar, saya pikir saya menemukan tombol.",
  ui_story_5004_50042601_14_dialog_content = "Heheh.",
  ui_story_5004_50042601_15_dialog_content = "Ini sangat terang... Tempat apa ini?",
  ui_story_5004_50042601_16_dialog_content = "(Mengapa semuanya tampak begitu akrab? Apakah saya melihat sesuatu?)",
  ui_story_5004_50042601_17_dialog_content = "Oh tidak, PlayerName, jalan kembali kami diblokir!",
  ui_story_5004_50042601_18_dialog_content = "Apa?",
  ui_story_5004_50042601_19_dialog_content = "Tidak, tidak bisa mengalah.",
  ui_story_5004_50042601_20_dialog_content = "Tempat... terkunci... <size=35>Silakan mulai ulang...</size> <size=33>sistem...</size>",
  ui_story_5004_50042601_21_dialog_content = "…?",
  ui_story_5004_50042601_22_dialog_content = "Semuanya, mari kita lihat apakah kita bisa membuka pintu sama sekali!",
  ui_story_5004_50042601_23_dialog_content = "Itu tidak bergerak dan semua serangan kami tidak membuat penyok.",
  ui_story_5004_50042601_24_dialog_content = "Tidakkah menurut Anda ini terasa seperti interior Colossus, PlayerName?",
  ui_story_5004_50042601_25_dialog_content = "Ya, memang, tapi bagaimana mungkin? Hei, dimana Bonacie?",
  ui_story_5004_50042601_26_dialog_content = "Mana bisa, mana bisa...",
  ui_story_5004_50042601_27_dialog_content = "Sayangku, cintaku, segalanya bagiku...",
  ui_story_5004_50042601_28_dialog_content = "Di mana Eclipsites bodoh itu menyembunyikannya?",
  ui_story_5004_50042601_29_dialog_content = "Ya, <size=45>jackpot!</size>",
  ui_story_5004_50042601_29X1_dialog_content = "Hei, apa yang kalian berdua lakukan di sini?",
  ui_story_5004_50042601_29X2_dialog_content = "Ssst, jangan biarkan para Aurorian mendengarnya!",
  ui_story_5004_50042601_29X3_dialog_content = "Kami akan mengambil Gerakan dan memberikannya kepada Anda.",
  ui_story_5004_50042601_29X4_dialog_content = "Jadi maksudmu Gerakan ada di dalam... benda ini?",
  ui_story_5004_50042601_29X5_dialog_content = "Ya. Ingat, Anda harus mendapatkan Caelestite...",
  ui_story_5004_50042601_29X6_dialog_content = "Suruh Caelestit untuk melepas segelnya, bukan? Saya tahu.",
  ui_story_5004_50042601_29X7_dialog_content = "Sekarang saya mendapat babak kedua, kalian berdua bisa istirahat, bukan?",
  ui_story_5004_50042601_29X8_dialog_content = "Hati-hati, Tuan Prinny!",
  ui_story_5004_50042601_29X9_dialog_content = "<color=#e8d9bb>DUAR!</color>",
  ui_story_5004_50042601_29X10_dialog_content = "Lalu menyeret mayat-mayat itu ke sudut gelap... Ya, sempurna!",
  ui_story_5004_50042601_30_dialog_content = "<size=45>PlayerName! Apa kamu masih di sana?</size>",
  ui_story_5004_50042601_31_dialog_content = "Kita terkunci, di mana lagi kita bisa? Kamu mau pergi kemana?",
  ui_story_5004_50042601_32_dialog_content = "saya menemukan <color=#FFB400>sesuatu yang menarik</color>, datang memeriksanya!",
  ui_story_5004_50042601_33_dialog_content = "Ada apa?",
  ui_story_5004_50042601_34_dialog_content = "Apakah ini terasa seperti <color=#FFB400>Penciptaan Caelestit</color>?",
  ui_story_5004_50042601_35_dialog_content = "Saya tahu Anda akan mengenalinya, bukan?",
  ui_story_5004_50042601_36_dialog_content = "Ini adalah ciptaan Caelestite dan kita berada di tempat yang menyerupai bagian dalam Colossus... Apakah itu berarti kita berada di Colossus?",
  ui_story_5004_50042601_37_dialog_content = "Bagaimana saya tahu? Saya hanya seorang musisi dan pembawa acara biasa, bukan?",
  ui_story_5004_50042601_38_dialog_content = "Keturunan ... yang saya tunggu ...",
  ui_story_5004_50042601_39_dialog_content = "(Itu dia lagi.)",
  ui_story_5004_50042601_40_dialog_content = "Bagaimana kalau menggunakan kemampuan psikismu, PlayerName?",
  ui_story_5004_50042601_41_dialog_content = "Aku punya firasat buruk tentang ini, PlayerName.",
  ui_story_5004_50042601_42_dialog_content = "Tapi kita terjebak. Mau bagaimana lagi?",
  ui_story_5004_50042601_43_dialog_content = "Oke, hati-hati.",
  ui_story_5004_50042601_44_dialog_content = "Keturunan ... yang saya tunggu ...",
  ui_story_5004_50042601_45_dialog_content = "Jika Anda rela merebut <color=#FFB400>Pergerakan</color>... kamu harus...",
  ui_story_5004_50042601_46_dialog_content = "Bukan memanggilnya...",
  ui_story_5004_50042601_47_dialog_content = "Jangan biarkan ... menghancurkan bumi ...",
  ui_story_5004_50042601_48_dialog_content = "Hei, pintunya terbuka sekarang!",
  ui_story_5004_50042701_49_dialog_content = "Terima kasih telah menemukan mekanismenya. Aku lelah menendang pintu bodoh itu.",
  ui_story_5004_50042701_50_dialog_content = "Apa yang Anda dapatkan dari kotak, Bonacie?",
  ui_story_5004_50042701_51_dialog_content = "Apakah itu semacam Gerakan di tangan Anda?",
  ui_story_5004_50042701_52_dialog_content = "Anda mengenalinya, PlayerName? Ini adalah bagian dari Divine Movement yang saya cari.",
  ui_story_5004_50042701_53_dialog_content = "(Jadi suara yang saya dengar menyinggung ini.)",
  ui_story_5004_50042701_54_dialog_content = "Bagaimana Anda tahu itu ada di sini? Dan dari mana Eclipsites berasal?",
  ui_story_5004_50042701_55_dialog_content = "Mereka jelas melindungi Gerakan.",
  ui_story_5004_50042701_56_dialog_content = "Oh, Caelestit. Sangat cerdik, bukan?",
  ui_story_5004_50042701_57_dialog_content = "Anda benar, saya membuat kesepakatan kecil dengan Eclipsites.",
  ui_story_5004_50042701_58_dialog_content = "Anda berurusan dengan Eclipsites?",
  ui_story_5004_50042701_59_dialog_content = "Terus? Ini bukan kemitraan dan saya tidak melakukan perbuatan jahat untuk mereka, bukan?",
  ui_story_5004_50042701_60_dialog_content = "Mereka memberi saya Gerakan yang saya inginkan, dan saya memastikan Penguasa Laut sukses.",
  ui_story_5004_50042701_61_dialog_content = "Penguasa Laut? Jadi itu bagian dari plot Eclipsite?",
  ui_story_5004_50042701_62_dialog_content = "Bahwa saya tidak tahu atau peduli. Suara di kepala saya dan Gerakan jauh lebih penting, bukan?",
  ui_story_5004_50042701_63_dialog_content = "Apakah Anda semacam musisi gila? Oh tunggu, kamu!",
  ui_story_5004_50042701_64_dialog_content = "Sekarang setelah Anda memilikinya, apa yang akan Anda lakukan? Apakah Anda masih akan bermitra dengan Eclipsites?",
  ui_story_5004_50042701_65_dialog_content = "Aku bilang itu bukan kemitraan, bukan? Cukup saling menguntungkan! Saya berencana untuk memberikannya kepada Anda, PlayerName!",
  ui_story_5004_50042701_66_dialog_content = "Berikan padaku? Setelah semua yang kamu lalui?",
  ui_story_5004_50042701_67_dialog_content = "Nah, itu <color=#FFB400>hadiah utama</color> dari Ocean Sovereign, setelah semua.",
  ui_story_5004_50042701_68_dialog_content = "Saya memang menyimpan rahasia dari Anda, jadi kami akan menyebutnya genap, bukan? Tapi saya harus memainkannya terlebih dahulu sebelum memberikannya kepada Anda.",
  ui_story_5004_50042701_69_dialog_content = "Kedengarannya seperti Anda mendapatkan gigitan pertama pada hasil kerja semua orang.",
  ui_story_5004_50042701_70_dialog_content = "Yah, kita semua berteman, bukan? Lihat ini...",
  ui_story_5004_50042701_71_dialog_content = "Apa, pertandingan identik lainnya?",
  ui_story_5004_50042701_72_dialog_content = "Tentu saja. Anda harus menggabungkan keduanya untuk menjadi satu kesatuan. Selalu seperti itu, bukan?",
  ui_story_5004_50042701_73_dialog_content = "Anu…",
  ui_story_5004_50042701_74_dialog_content = "Itu dia? Hanya sekejap?",
  ui_story_5004_50042701_75_dialog_content = "Ada apa?",
  ui_story_5004_50042701_76_dialog_content = "Aku bisa merasakan semacam energi di dalamnya, tapi itu ditahan.",
  ui_story_5004_50042701_77_dialog_content = "(Masih belum berhasil? Kira saya harus mencoba apa <color=#FFB400>tikus itu</color> dikatakan...)",
  ui_story_5004_50042701_78_dialog_content = "Anda mencobanya, PlayerName. Lakukan sesuatu, gunakan kemampuan psikismu mungkin, bukan?",
  ui_story_5004_50042701_79_option_content = "Tidak mungkin.",
  ui_story_5004_50042701_80_dialog_content = "Saya tidak ingin menyentuh apa pun dari tawar-menawar dengan Eclipsites!",
  ui_story_5004_50042701_81_dialog_content = "Baik, baik, aku bersumpah aku tidak akan pernah membuat kesepakatan dengan Eclipsites lagi!",
  ui_story_5004_50042701_82_option_content = "Jika itu diberikan kepada saya ...",
  ui_story_5004_50042701_83_dialog_content = "Masih tidak!",
  ui_story_5004_50042701_84_dialog_content = "Instingku memberitahuku bahwa ini adalah sesuatu yang berbahaya!",
  ui_story_5004_50042701_85_dialog_content = "Seberapa berbahayakah itu? Kami memiliki semua orang di sini, bukan? Ayo, tolong!",
  ui_story_5004_50042701_86_option_content = "Anda... Baik, saya akan mencobanya.",
  ui_story_5004_50042701_87_dialog_content = "Tetapi saya mendengar suara yang memperingatkan saya untuk tidak merusak segel apa pun.",
  ui_story_5004_50042701_88_dialog_content = "Anda pasti salah dengar, bukan? Ayo, tolong?",
  ui_story_5004_50042701_89_dialog_content = "Anda bersumpah tidak akan pernah membuat kesepakatan dengan Eclipsites lagi?",
  ui_story_5004_50042701_90_dialog_content = "Baik, baik, aku bersumpah, tidak akan pernah lagi!",
  ui_story_5004_50042701_91_dialog_content = "...",
  ui_story_5004_50042701_92_option_content = "Aktifkan telepati",
  ui_story_5004_50042701_93_dialog_content = "Berhasil, tidak?",
  ui_story_5004_50042701_94_dialog_content = "Luar biasa.",
  ui_story_5004_50042701_95_dialog_content = "Terima kasih, PlayerName...",
  ui_story_5004_50042701_96_dialog_content = "Apa yang kamu lakukan, Bonacie?!",
  ui_story_5004_50042701_97_dialog_content = "Oh, betapa menakjubkannya ini! Aku bisa merasakan panggilannya begitu segelnya hilang...",
  ui_story_5004_50042701_98_dialog_content = "Maaf, PlayerName...",
  ui_story_5004_50042701_99_dialog_content = "Tujuan saya berada di sini, tujuan keberadaan saya, adalah semata-mata untuk memainkan Melodi Ilahi!",
  ui_story_5004_50042701_100_dialog_content = "Apa energi tak menyenangkan yang saya rasakan ini?",
  ui_story_5004_50042701_101_dialog_content = "Bonasi!",
  ui_story_5004_50042701_102_dialog_content = "Hahaha!",
  ui_story_5004_50042701_103_dialog_content = "Ritme yang begitu indah! Benar-benar di luar kesempurnaan, bukan?",
  ui_story_5004_50042701_104_dialog_content = "Tidak... aku tak berdaya...",
  ui_story_5004_50042701_105_dialog_content = "Jangan dengarkan musiknya!",
  ui_story_5004_50042701_106_dialog_content = "Hentikan, Bonasie!",
  ui_story_5004_50042701_107_dialog_content = "Mengumpulkan Gerakan Void adalah kehormatan tertinggi yang diberikan suara itu kepadaku.",
  ui_story_5004_50042701_108_dialog_content = "Sungguh keterlaluan memintaku berhenti, bukan?",
  ui_story_5004_50042701_112_dialog_content = "Apakah energi itu berasal dari Bonacie? Tidak, itu mengalir keluar dari Gerakan di depannya!",
  ui_story_5004_50042701_113_dialog_content = "Hei, lihat ke sana!",
  ui_story_5004_50042701_114_dialog_content = "Apakah itu kastil yang muncul dari laut?",
  ui_story_5004_50042701_115_dialog_content = "Kastil... Tapi bagaimana ini bisa...",
  ui_story_5004_50042701_116_dialog_content = "Dengar, PlayerName, ritme yang menggetarkan, bukan?",
  ui_story_5004_50042701_117_dialog_content = "Kalian Caelestit... tentu saja ras kalian akan menyimpan musik indah ini untuk kalian sendiri, bukan? Tidak ada alasan untuk membaginya dengan dunia biasa!",
  ui_story_5004_50042701_118_dialog_content = "Dilakukan dengan baik, bukan? Aku mulai lebih menghargaimu Caelestites!",
  ui_story_5004_50042701_119_dialog_content = "Ini adalah suara Kebenaran, suara keilahian.",
  ui_story_5004_50042701_120_dialog_content = "Mereka bergema di pikiranku, PlayerName!",
  ui_story_5004_50042701_121_dialog_content = "Keluar dari itu, Beryl. PlayerName! Sesuatu bersinar di atas Bonacie!",
  ui_story_5004_50042701_122_dialog_content = "Itu meteorit, dan menuju ke arah kita!",
  ui_story_5004_50042701_123_dialog_content = "Dari mana meteorit itu berasal?",
  ui_story_5004_50042701_124_dialog_content = "Hati-hati, itu menabrak dengan cara ini!",
  ui_story_5004_50042701_125_dialog_content = "Domain Kristal!",
  ui_story_5004_50042701_126_dialog_content = "Ugh!",
  ui_story_5004_50042701_127_dialog_content = "Kau baik-baik saja?",
  ui_story_5004_50042701_128_dialog_content = "Ya, baru saja digulingkan oleh ombak, itu saja. Untungnya, kami memiliki Beryl...",
  ui_story_5004_50042701_129_dialog_content = "Meteorit lain yang lebih besar akan datang!",
  ui_story_5004_50042701_130_dialog_content = "Saya akan memberikan semua yang saya punya.",
  ui_story_5004_50042701_131_dialog_content = "(Tidak, meteorit yang ukurannya lebih dari yang bisa kita tangani!)",
  ui_story_5004_50042701_132_dialog_content = "Apakah ini akhirnya...",
  ui_story_5004_50042701_133_dialog_content = "Jangan menyerah begitu cepat, PlayerName.",
  ui_story_5004_50042701_134_dialog_content = "Suara itu!",
  ui_story_5004_50042701_135_dialog_content = "Ya, itu teman mekanik setia Anda dan sahabatnya Brock!",
  ui_story_5004_50042701_136_dialog_content = "Duduk dan nikmati kekuatan Rediesel Steel MkV Zero, PlayerName!",
  ui_story_5004_50042701_137_dialog_content = "Ohhhhh!",
  ui_story_5004_50042701_138_dialog_content = "Berhenti berteriak! Kamu bertingkah seratus kali lebih gila dari biasanya!",
  ui_story_5004_50042701_139_dialog_content = "Tarik lebih tinggi. Ini masih akan bekerja lebih tinggi!",
  ui_story_5004_50042701_140_dialog_content = "Tarik apa yang lebih tinggi? Lupakan saja, saya menarik semuanya!",
  ui_story_5004_50042701_141_dialog_content = "Itu dia! Terangi hidupku!",
  ui_story_5004_50042701_142_dialog_content = "Hei, apa artinya lampu berkedip?",
  ui_story_5004_50042701_143_dialog_content = "Itulah peringatan kelebihan beban!",
  ui_story_5004_50042701_144_dialog_content = "Jadi apa yang akan terjadi?",
  ui_story_5004_50042701_145_dialog_content = "Itu akan meledak dalam 30 detik!",
  ui_story_5004_50042701_146_dialog_content = "Nah, Rediesel Steel MkV, bakar bersamaku sampai akhir!",
  ui_story_5004_50042701_147_dialog_content = "Hancurkan meteorit itu keluar jalurnya!",
  ui_story_5004_50042701_148_dialog_content = "Anda tidak perlu mendorongnya kembali!",
  ui_story_5004_50042701_149_dialog_content = "Fleur!",
  ui_story_5004_50042701_150_dialog_content = "Siap!",
  ui_story_5004_50042701_151_dialog_content = [[
Meteorit yang sangat buruk ...
Dapatkan neraka <size=45>keluar dari sini!</size>]],
  ui_story_5004_50042701_152_dialog_content = "(Percikan dari pendorong itu menyilaukan!)",
  ui_story_5004_50042701_153_dialog_content = "Sukses, PlayerName! Meteorit itu keluar jalur!",
  ui_story_5004_50042701_154_dialog_content = "Apakah Anda yakin itu tidak masalah? Dari apa yang saya tahu, robot itu akan kelebihan beban dan berantakan!",
  ui_story_5004_50042701_157_dialog_content = "Berhenti memutar-mutar ibu jari Anda, PlayerName! menjauh dari pantai!",
  ui_story_5004_50042701_158_dialog_content = "Gelombang datang!!",
  ui_story_5004_50042701_159_dialog_content = "Saya masih lemas, terima kasih kepada Bonacie!",
  ui_story_5004_50042701_160_dialog_content = "Pegang tanganku, PlayerName!",
  ui_story_5004_50042701_161_dialog_content = "Tidak bisa... Sudah terlambat!",
  ui_story_5004_50042701_162_dialog_content = "Kau baik-baik saja, PlayerName?",
  ui_story_5004_50042701_163_dialog_content = "Apakah ini yang menggunakan teknologi Caelestite yang Anda bicarakan?",
  ui_story_5004_50042701_164_dialog_content = "Ya. Ini terintegrasi dengan teknologi Caelestite, dan ini adalah robot paling kuat!",
  ui_story_5004_50042701_165_dialog_content = "Sayangnya, bagian-bagian dengan teknologi Caelestite mengalami kerusakan parah karena menjatuhkan meteorit itu.",
  ui_story_5004_50042701_166_dialog_content = "Maksud Anda pendorong yang tak terbayangkan, bukan?",
  ui_story_5004_50042701_167_dialog_content = "Apakah Anda Illumina atau Lumopolis, semua orang berutang banyak pada Brock hari ini!",
  ui_story_5004_50042701_168_dialog_content = "Ingatlah untuk memilih saya dalam pemilihan bos Rediesel Wrench berikutnya, Anda mendengar saya!",
  ui_story_5004_50042701_169_dialog_content = "Brock tua yang sama... Hei, dimana Bonacie?",
  ui_story_5004_50042701_170_dialog_content = "Bagusnya! Saya merasa hebat!",
  ui_story_5004_50042701_171_dialog_content = "Wah, dari mana Anda berasal?",
  ui_story_5004_50042701_172_dialog_content = "Saya sudah berkeliling, bahkan mengikuti kalian ketika ombak besar melanda, Anda hanya tidak menyadarinya, bukan?",
  ui_story_5004_50042701_173_dialog_content = "Ini dia, Gerakan.",
  ui_story_5004_50042701_174_dialog_content = "Itu mudah. Tunggu, apa yang kamu miliki sekarang?",
  ui_story_5004_50042701_175_dialog_content = "Tidak ada, karena tujuan saya adalah memainkannya dan hanya itu.",
  ui_story_5004_50042701_176_dialog_content = "Hanya sekali dan itu terukir selamanya di jiwaku, jadi tidak perlu bagiku untuk menyimpannya.",
  ui_story_5004_50042701_177_dialog_content = "Belum lagi itu adalah milik Caelestite, jadi itu hanya hak untuk kamu simpan.",
  ui_story_5004_50042701_178_dialog_content = "Jangan khawatir, saya tidak akan memainkannya lagi, jadi maafkan saya, bukan?",
  ui_story_5004_50042701_179_dialog_content = "(Dan Anda pikir Anda lolos begitu saja?)",
  ui_story_5004_50042701_180_dialog_content = "Benda berbahaya ini harus disimpan di tempat yang aman.",
  ui_story_5004_50042701_181_dialog_content = "Membiarkannya hanya akan membujuk orang lain untuk mengeksploitasinya.",
  ui_story_5004_50042701_182_dialog_content = "Kamu benar. Saya akan menerimanya, tetapi ini tidak berarti Anda bebas dari hukuman!",
  ui_story_5004_50042701_183_dialog_content = "Anda akan menguraikan kesepakatan Anda dengan Eclipsites!",
  ui_story_5004_50042801_E1_dialog_content = "Jadi itu segalanya, aku bersumpah!",
  ui_story_5004_50042801_E2_dialog_content = "Jadi Anda membantu mereka dengan Ocean Sovereign hanya untuk mendapatkan Gerakan Anda?",
  ui_story_5004_50042801_E3_dialog_content = "Itu benar! Tepat sekali!",
  ui_story_5004_50042801_E4_dialog_content = "Baiklah…",
  ui_story_5004_50042801_E5_dialog_content = "Anda akhirnya bangun, tuanku...",
  ui_story_5004_50042801_E6_dialog_content = "Apa itu? Anda ingin bertemu dengan para pejuang yang membangunkan Anda?",
  ui_story_5004_50042801_E7_dialog_content = "Tunggu, kalian dengar itu? Itu memudar masuk dan keluar dari telingaku.",
  ui_story_5004_50042801_E8_dialog_content = "Oke oke. Heh, aku yakin mereka juga sangat ingin bertemu denganmu...",
  ui_story_5004_50042801_E9_dialog_content = "Tapi Anda belum dalam kekuatan penuh, jadi izinkan saya untuk membantu Anda.",
  ui_story_5004_50042801_E10_dialog_content = "Mendengar apa? Pikiranku masih penuh dengan lagu itu... Tapi aku bisa merasakan Darkflow semakin padat!",
  ui_story_5004_50042801_E11_dialog_content = "Dari mana asalnya? Saya tidak merasakannya sedetik yang lalu!",
  ui_story_5004_50042801_E12_dialog_content = "<color=#e8d9bb>\"Musik diputar, menghentikan pencarian. Raja terbangun, hanya untuk membakar bintang-bintang, memberikan malapetaka dan kemarahan kepada semua orang.\"</color>",
  ui_story_5004_50042801_E13_dialog_content = "...",
  ui_story_5004_50042801_184_dialog_content = "Aahhhhhh!",
  ui_story_5004_50042801_185_dialog_content = "Apakah mereka Eclipsites yang lari dari pertempuran?",
  ui_story_5004_50042801_186_dialog_content = "Tidak, mereka...!",
  ui_story_5004_50042802_1_dialog_content = "Kuat... Jauh melampaui Eclipsites pada umumnya.",
  ui_story_5004_50042802_2_dialog_content = "Dari mana mereka berasal? Belum pernah melihat yang seperti mereka sebelumnya.",
  ui_story_5004_50042802_3_dialog_content = "Untungnya, mereka dikalahkan. Mereka tidak bisa melakukan kejahatan sekarang.",
  ui_story_5004_50042802_4_dialog_content = "Tidak, mereka mungkin klon.",
  ui_story_5004_50042802_5_dialog_content = "Saya merasakan kekuatan lain yang jauh lebih kuat mengendalikan mereka selama pertempuran.",
  ui_story_5004_50042802_6_dialog_content = "Dan sumber kekuatan itu ada di kastil itu.",
  ui_story_5004_50042802_7_dialog_content = "(Saya sangat terganggu, saya hampir lupa tentang kastil super-eksotis itu sepenuhnya.)",
  ui_story_5004_50042802_8_dialog_content = "(Tapi sekarang saya dapat dengan mudah merasakan Darkflow yang semakin menakutkan darinya.)",
  ui_story_5004_50042802_9_dialog_content = "Ck. Apakah Eclipsites itu melakukan itu? Betapa rumitnya...",
  ui_story_5004_50042802_10_dialog_content = "Tidak heran saya mendapatkan Gerakan dengan begitu mudah. Mereka menggunakan PlayerName dan kekuatanku untuk memanggil monster itu!",
  ui_story_5004_50042802_11_dialog_content = "Saya melihat Ocean Sovereign bukan hanya penipuan menghasilkan uang. Tikus aneh itu telah merencanakan semua ini!",
  ui_story_5004_50042802_12_dialog_content = "Saya hanya akan mengalahkan mereka dan mengambil Gerakan lain kali!",
  ui_story_5004_50042802_13_dialog_content = "Penipuan menghasilkan uang? Apa yang dibutuhkan Eclipsites dengan uang?!",
  ui_story_5004_50042802_14_dialog_content = "Mereka bilang mereka akan memeras setiap sen terakhir dari Aurorian dan membuat mereka miskin, jadi mereka harus bekerja dan tidak mampu melawan...",
  ui_story_5004_50042802_15_dialog_content = "Perhatian saya hanya pada Gerakan dan tidak ada yang lain.",
  ui_story_5004_50042802_16_dialog_content = "Kita harus memeriksa kastil dan musuh di dalamnya, PlayerName.",
  ui_story_5004_50042802_17_dialog_content = "Carleen benar. Jika tidak, semua orang di pantai mungkin dalam bahaya, dan mungkin lebih buruk.",
  ui_story_5004_50042802_18_dialog_content = "Kita di sini sekarang, jangan biarkan Eclipsites menakut-nakuti kita.",
  ui_story_5004_50042802_19_dialog_content = "Itu hanya beberapa Eclipsites yang bagus untuk bounty.",
  ui_story_5004_50042802_20_dialog_content = "Ya, aku juga ingin pergi... Aku sangat penasaran dengan kastil itu...",
  ui_story_5004_50042802_21_dialog_content = "Jika Beryl pergi, aku juga.",
  ui_story_5004_50042802_22_dialog_content = "Mengapa Anda melihat saya? Itu tugas saya untuk memastikan keamanan pantai sebagai Kepala Keamanan!",
  ui_story_5004_50042802_23_dialog_content = "Rediesel Steel Mark V-Zero akan membawa semua orang!",
  ui_story_5004_50042802_24_dialog_content = "Yah, kira saya akan berkontribusi dan memperbaiki robot dengan bagian-bagian berharga dan sumber daya dari simpanan saya.",
  ui_story_5004_50042802_25_dialog_content = "Lalu kita akan menghajar mereka karena berani mengeksploitasiku!",
  ui_story_5004_50042802_26_dialog_content = "Oke, mari kita pergi kalau begitu!",
  ui_story_5004_50042901_1_dialog_content = "Bisakah MkV bertahan, Fleur?",
  ui_story_5004_50042901_2_dialog_content = "Itu Rediesel Steel MkV Zero!",
  ui_story_5004_50042901_3_dialog_content = "Ini mengadopsi teknologi propulsi Colossus, dan hanya diisi oleh sumber daya Nona Bonacie!",
  ui_story_5004_50042901_4_dialog_content = "Saya kira dia sudah mati untuk menyelesaikan skor dengan Eclipsites yang menggunakannya.",
  ui_story_5004_50042901_5_dialog_content = "Teknologi raksasa, katamu? Apakah akan kehilangan kekuatan seperti Soroz?",
  ui_story_5004_50042901_6_dialog_content = "Hati-hati, Fleur, jangan terbang terlalu tinggi!",
  ui_story_5004_50042901_7_dialog_content = "Hah, kenapa?",
  ui_story_5004_50042901_8_dialog_content = "Hah???",
  ui_story_5004_50042901_9_dialog_content = "Apa yang sedang terjadi? Pembacaannya terombang-ambing di antara dua ekstrem!",
  ui_story_5004_50042901_10_dialog_content = "Ada apa, Fleur?",
  ui_story_5004_50042901_11_dialog_content = "Tidak ada apa-apa. Alatnya sedikit rusak...",
  ui_story_5004_50042901_12_dialog_content = "Hanya instrumennya?",
  ui_story_5004_50042901_13_dialog_content = "Kami menabrak! Saya tahu bongkahan baja ini tidak dapat diandalkan!",
  ui_story_5004_50042901_14_dialog_content = "Rediesel Steel MkV Zero saya tidak akan pernah crash!",
  ui_story_5004_50042901_15_dialog_content = "Hal ini menerjang! Cepat, lakukan sesuatu!",
  ui_story_5004_50042901_16_dialog_content = "Kami akan meluncur ke kastil! Tunggu, semuanya!",
  ui_story_5004_50042901_17_dialog_content = "Meluncur pantatku! Kami menabrak...",
  ui_story_5004_50042901_18_dialog_content = "Tenang, percayalah pada teknologi Rediesel Wrench!",
  ui_story_5004_50042901_19_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5004_50042901_20_dialog_content = "PlayerName.",
  ui_story_5004_50042901_21_dialog_content = "Bangun, PlayerName.",
  ui_story_5004_50042901_22_dialog_content = "Ah, kepalaku...",
  ui_story_5004_50042901_23_dialog_content = "Vice?",
  ui_story_5004_50042901_24_dialog_content = "Anda akhirnya datang ke. Anda kedinginan.",
  ui_story_5004_50042901_25_dialog_content = "Di mana kita? Apakah kita menabrak kastil?",
  ui_story_5004_50042901_26_dialog_content = "Kami tidak tahu, tapi tempat ini terlihat... sangat tidak biasa. Aliran Gelap di sini mencekik.",
  ui_story_5004_50042901_27_dialog_content = "Dan lihat semua gambar yang beredar. Mereka dianimasikan seolah-olah mereka hidup.",
  ui_story_5004_50042901_28_dialog_content = "Lihat bola mata di gambar itu?",
  ui_story_5004_50042901_29_dialog_content = "Itu mengikuti kami berkeliling dan membuatku merinding.",
  ui_story_5004_50042901_30_dialog_content = "Beryl, gambar yang di sana, apakah itu menyulap dengan lemon?",
  ui_story_5004_50042901_31_dialog_content = "Sepertinya begitu...",
  ui_story_5004_50042901_32_dialog_content = "Lihat ke sana, PlayerName!",
  ui_story_5004_50042901_33_dialog_content = "Itu Soroz! Bagaimana bisa ada di sini?",
  ui_story_5004_50042901_34_dialog_content = "Aku harus pergi melihat.",
  ui_story_5004_50042901_35_dialog_content = "Apa... Bagaimana lempengan ini muncul di bawah kakiku?",
  ui_story_5004_50042901_36_dialog_content = "Itu kamu ya Soroz.",
  ui_story_5004_50042901_37_dialog_content = "Sial, aku tidak bisa mendekatinya tidak peduli seberapa cepat aku berjalan.",
  ui_story_5004_50042901_38_dialog_content = "Pelan-pelan, PlayerName.",
  ui_story_5004_50042901_39_dialog_content = "Berbahaya untuk bergerak secepat itu di sini.",
  ui_story_5004_50042901_40_dialog_content = "Oke. Kalian punya petunjuk?",
  ui_story_5004_50042901_41_dialog_content = "Biarkan aku berpikir... Kami menabrak kastil dan pingsan.",
  ui_story_5004_50042901_42_dialog_content = "Dan kami terbangun di sini, yang jelas bukan di dalam kastil tapi mungkin di dimensi saku.",
  ui_story_5004_50042901_43_dialog_content = "Ck. Saya pikir kami hanya akan bertarung sekali dan kembali.",
  ui_story_5004_50042901_44_dialog_content = "Sekarang kita terjebak tanpa jalan keluar.",
  ui_story_5004_50042901_45_dialog_content = "Saya rasa tidak ada bagian lain dari Gerakan di sini.",
  ui_story_5004_50042901_46_dialog_content = "...",
  ui_story_5004_50042901_47_dialog_content = "Bagaimana kabarmu, Beryl? Di sini, gunakan saya sebagai pendukung.",
  ui_story_5004_50042901_48_dialog_content = "Aku baik-baik saja, terima kasih...",
  ui_story_5004_50042901_49_dialog_content = "Aku punya pengakuan untuk dibuat...",
  ui_story_5004_50042901_50_dialog_content = "Ingat istana pasir yang saya bangun?",
  ui_story_5004_50042901_51_dialog_content = "Ya, kastil itu sangat mirip dengan yang ini!",
  ui_story_5004_50042901_52_dialog_content = "Apakah Anda pada sesuatu, Beryl?",
  ui_story_5004_50042901_53_dialog_content = "Saya tidak yakin... Tapi struktur ini selalu ada di pikiran saya.",
  ui_story_5004_50042901_54_dialog_content = "Jadi saya menebak suara di kepala saya dan tempat ini terhubung.",
  ui_story_5004_50042901_55_dialog_content = "Hati-hati, semuanya... Bukan hanya Darkflow di sini... Ada kekuatan yang terasa sangat familiar bagiku...",
  ui_story_5004_50042901_56_dialog_content = "Jangan khawatir, Beryl, kami tidak akan membiarkan siapa pun menyakitimu.",
  ui_story_5004_50042901_57_dialog_content = "Kami akan mencari tahu tagihan saya sebagai pengawal Anda nanti. Aku bahkan akan memberimu diskon!",
  ui_story_5004_50042901_58_dialog_content = "Apakah uang yang Anda pedulikan? Anda tidak bertingkah seperti bangsawan, Jenewa!",
  ui_story_5004_50042901_59_dialog_content = "Diam, kamu! Saya mencoba untuk meringankan suasana di sini!",
  ui_story_5004_50042901_60_dialog_content = "Kita harus bersatu untuk mengalahkan Eclipsites. Itu sesuatu yang aneh penyendiri seperti Anda tidak akan mengerti.",
  ui_story_5004_50042901_61_dialog_content = "Itu benar, mengalahkan Eclipsites adalah alasan kita semua ada di sini.",
  ui_story_5004_50042901_62_dialog_content = "Tentu, kita terjebak dalam ilusi aneh sekarang, tapi itu bukan alasan untuk berhenti!",
  ui_story_5004_50042901_63_dialog_content = "Ya!",
  ui_story_5004_50042901_64_dialog_content = "Mari kita coba melihat sekeliling... meskipun kita tidak bisa melihat apa-apa.",
  ui_story_5004_50042901_65_dialog_content = "Mari kita memilih arah dan menaatinya.",
  ui_story_5004_50042901_66_dialog_content = "Baiklah. Hati-hati.",
  ui_story_5004_50042901_67_dialog_content = "Saya tidak bisa membedakan sekitarnya.",
  ui_story_5004_50042901_68_dialog_content = "Bukan hanya Soroz, tetapi bahkan gambar-gambar di sekelilingnya tampak agak akrab.",
  ui_story_5004_50042901_69_dialog_content = "Itu puncak menara di Lumopolis...",
  ui_story_5004_50042901_70_dialog_content = "Wanita di foto itu...!",
  ui_story_5004_50042901_71_dialog_content = "Makhluk-makhluk keji, beraninya mereka mencoba menggangguku dengan citra ibuku!",
  ui_story_5004_50042901_72_dialog_content = "Tetap tenang, Carleen. Jangan jatuh untuk trik mereka.",
  ui_story_5004_50042901_73_dialog_content = "Bisakah tempat ini membaca pikiran kita?",
  ui_story_5004_50042901_74_dialog_content = "Gadis kecil di foto itu...",
  ui_story_5004_50042901_75_dialog_content = "(Mengapa saya mendapatkan dorongan untuk menyentuhnya?)",
  ui_story_5004_50042901_76_option_content = "Sentuh gambar",
  ui_story_5004_50042901_77_dialog_content = "…!",
  ui_story_5004_50042901_78_dialog_content = "(Asap yang sangat kuat, dan aku mendengar tangisan yang familiar... Bukankah ini yang kulihat saat aku menyentuh Beryl?)",
  ui_story_5004_50042901_79_dialog_content = "Maaf…",
  ui_story_5004_50042901_80_dialog_content = "maafkan aku ayah dan ibu...",
  ui_story_5004_50042901_81_dialog_content = "PlayerName, PlayerName?",
  ui_story_5004_50042901_82_dialog_content = "Vice…",
  ui_story_5004_50042901_83_dialog_content = "Kenapa kamu menangis? Apa yang Anda rasakan?",
  ui_story_5004_50042901_84_dialog_content = "(Apakah itu ingatan Beryl? Mengapa saya melihatnya tiba-tiba?)",
  ui_story_5004_50042901_85_dialog_content = "(Apa hubungan antara Beryl dan gambar itu? Orang tuanya...)",
  ui_story_5004_50042901_86_dialog_content = "(Tidak, itu bisa menjadi trik Eclipsite lain. Saya harus tetap diam sampai saya tahu lebih banyak.)",
  ui_story_5004_50042901_87_dialog_content = "Aku baik-baik saja, hanya melihat beberapa ilusi... Mungkin tipuan Eclipsite.",
  ui_story_5004_50042901_88_dialog_content = "Beritahu semua orang untuk berhati-hati terhadap gambar. Mereka bisa memainkan trik di pikiran Anda.",
  ui_story_5004_50042901_89_dialog_content = "Apa-apaan ini... Kenapa?",
  ui_story_5004_50042901_90_dialog_content = "Mengapa Anda menyelinap di sekitar sana?",
  ui_story_5004_50042901_91_dialog_content = "Dua gambar di sebelah Anda adalah kami sebagai anak-anak. Apa yang mereka lakukan?",
  ui_story_5004_50042901_92_dialog_content = "Jangan mendekat!",
  ui_story_5004_50042901_93_dialog_content = "Hai! Mengapa Anda membakarnya? Aku bahkan tidak mendapat kesempatan untuk melihatnya.",
  ui_story_5004_50042901_94_dialog_content = "Itu karena aku tidak menginginkanmu!",
  ui_story_5004_50042901_95_dialog_content = "Aahhhh!",
  ui_story_5004_50042901_96_dialog_content = "Hati-hati, kami punya Eclipsites!",
  ui_story_5004_50042901_97_dialog_content = "Gan! Gan!",
  ui_story_5004_50042901_98_dialog_content = "Mereka baru saja muncul dari gambar! Bersiaplah untuk bertarung!",
  ui_story_5004_50043001_1_dialog_content = "Punya mereka semua. Apakah saya atau mereka lebih tangguh daripada yang ada di pantai?",
  ui_story_5004_50043001_2_dialog_content = "Ya, jauh lebih keras.",
  ui_story_5004_50043001_3_dialog_content = "Dan mereka hanya klon. Aliran Gelap tidak berkurang sedikit pun.",
  ui_story_5004_50043001_4_dialog_content = "Kami bahkan tidak dapat menemukan musuh yang sebenarnya sekarang. Ini akan sulit.",
  ui_story_5004_50043001_5_dialog_content = "Ini pertama kalinya aku menemukan... ilusi yang aneh.",
  ui_story_5004_50043001_6_dialog_content = "Biarkan aku meminjam pin di topimu, Genevieve.",
  ui_story_5004_50043001_7_dialog_content = "Untuk apa? Anda sebaiknya tidak merusaknya!",
  ui_story_5004_50043001_8_dialog_content = "Heeyeah!",
  ui_story_5004_50043001_9_dialog_content = "Mengapa Anda membuangnya?",
  ui_story_5004_50043001_10_dialog_content = "Aduh! Kenapa itu mengenai wajahku dari atas?",
  ui_story_5004_50043001_11_dialog_content = "Bahkan arahnya kacau!",
  ui_story_5004_50043001_12_dialog_content = "Bagaimana kalau melempar Kepompong Bulanmu, Carleen?",
  ui_story_5004_50043001_13_dialog_content = "Lebih baik Anda menembakkan panah saja.",
  ui_story_5004_50043001_14_dialog_content = "Oh, benar...",
  ui_story_5004_50043001_15_dialog_content = "Tunggu! Bagaimana jika itu mengenai wajahku lagi?",
  ui_story_5004_50043001_16_dialog_content = "Tidak masalah, aku di sini! Saya hanya akan memiliki rudal mengikuti panah!",
  ui_story_5004_50043001_17_dialog_content = "Tidak, tinggalkan aku sendiri dan temukan ide lain!",
  ui_story_5004_50043001_18_dialog_content = "Bagaimana kalau berbicara dengan gambar mulut di sana?",
  ui_story_5004_50043001_19_dialog_content = "Lupakan saja, itu terlihat menjijikkan.",
  ui_story_5004_50043001_20_dialog_content = "Sepertinya itu dari dunia yang berbeda.",
  ui_story_5004_50043001_21_dialog_content = "Jadi...",
  ui_story_5004_50043001_22_dialog_content = "Bagaimana dengan yang itu?",
  ui_story_5004_50043001_23_dialog_content = "Gadis kecil yang sama? Dia menunjuk ke pintu di belakangnya.",
  ui_story_5004_50043001_24_dialog_content = "Apakah dia ingin kita melewatinya?",
  ui_story_5004_50043001_25_dialog_content = "Nah, apa lagi yang bisa kita lakukan? Dia tidak tampak bermusuhan.",
  ui_story_5004_50043001_26_dialog_content = "Tapi itu sangat kecil. Bagaimana kita bisa melewatinya?",
  ui_story_5004_50043001_27_option_content = "Masukkan jarimu",
  ui_story_5004_50043001_28_dialog_content = "<color=#e8d9bb>Klik.</color>",
  ui_story_5004_50043001_29_dialog_content = "Saya pikir saya baru saja menekan sesuatu. Hey apa yang terjadi?",
  ui_story_5004_50043001_30_dialog_content = "Tanah di bawah kaki menyusut! Kita akan jatuh!",
  ui_story_5004_50043001_31_dialog_content = "…!",
  ui_story_5004_50043001_32_dialog_content = "Dia pingsan. Apa yang kita lakukan sekarang? Aku tidak percaya bubuk itu bisa membuat monster mengerikan seperti itu...",
  ui_story_5004_50043001_33_dialog_content = "Kami mendapat sampel yang cukup. Mari kita tinggalkan dia di sini.",
  ui_story_5004_50043001_34_dialog_content = "Aku penasaran melihat reaksinya saat dia bangun dan melihat semua mayat ini.",
  ui_story_5004_50043001_35_dialog_content = "Itulah harga yang Anda bayar untuk pengkhianatan.",
  ui_story_5004_50043001_36_dialog_content = "Kau sama kejamnya dengan Eclipsites.",
  ui_story_5004_50043001_37_dialog_content = "Ugh!",
  ui_story_5004_50043001_38_dialog_content = "Itu menyakitkan...",
  ui_story_5004_50043001_39_dialog_content = "Turun, tolong!",
  ui_story_5004_50043001_40_dialog_content = "aku tidak bisa bernafas...",
  ui_story_5004_50043001_41_dialog_content = "Aku hampir mati di sana. Bau sekali aku harus berada di bawah hanya karena aku menyentuhnya terlebih dahulu!",
  ui_story_5004_50043001_42_dialog_content = "Terima kasih telah menyelamatkan kami semua, PlayerName.",
  ui_story_5004_50043001_43_dialog_content = "Katakanlah, jika ini adalah salah satu permainan Gronru, kita seharusnya berada di Level Dua sekarang.",
  ui_story_5004_50043001_44_dialog_content = "Apakah Anda mengatakan kita akan melihat antagonis baru?",
  ui_story_5004_50043001_45_dialog_content = "Selamat datang, tamu dari jauh!",
  ui_story_5004_50043001_46_dialog_content = "Ini dia!",
  ui_story_5004_50043001_47_dialog_content = "Selamat datang di kastil dan taman saya, Dream Void Keep.",
  ui_story_5004_50043001_48_dialog_content = "Dream Void Keep? Apakah Anda pemiliknya?",
  ui_story_5004_50043001_49_dialog_content = "Anda dapat menganggap saya sebagai nyonyanya. Lagipula, aku sudah tinggal di sini dengan semua mainan ini selama lebih dari sepuluh tahun.",
  ui_story_5004_50043001_50_dialog_content = "Oh! Dengan mainan, maksud saya potongan selamat datang yang Anda temui. Mereka tidak memperlakukanmu dengan buruk, kan?",
  ui_story_5004_50043001_51_dialog_content = "Suara...!",
  ui_story_5004_50043001_52_dialog_content = "Itu yang ada di mimpiku!",
  ui_story_5004_50043001_53_dialog_content = "Jadi Eclipsites seperti catur adalah kreasi Anda? Mengapa Anda terlihat seperti ini?",
  ui_story_5004_50043001_54_dialog_content = "Mudah, sekarang. Saya melihat Caelestite memiliki rasa ingin tahu yang sama seperti yang dikabarkan.",
  ui_story_5004_50043001_55_dialog_content = "Kami tidak memiliki pengunjung Aurorian selama bertahun-tahun, jadi Anda lebih baik menghibur saya dan tidak mati begitu saja.",
  ui_story_5004_50043001_56_dialog_content = "Biarkan saya membaca jurnal tahun pertama saya di sini. Mungkin ada jawaban di dalamnya untuk Anda.",
  ui_story_5004_50043001_57_dialog_content = "Hei, hilang... Ke mana perginya jurnal pertama itu? Apakah Anda mencurinya?",
  ui_story_5004_50043001_58_dialog_content = "Oh tidak, tanpanya, saya tidak bisa memberikan teh sore yang disiapkan khusus untuk para tamu!",
  ui_story_5004_50043001_59_dialog_content = "Mungkin aku harus membuka tengkorakmu dan melihat apakah jurnalku ada di dalam?",
  ui_story_5004_50043001_60_dialog_content = "Saya tidak berpikir dia berpikir jernih, PlayerName.",
  ui_story_5004_50043001_61_dialog_content = "Hei, hentikan sandiwara itu. Anda adalah bos dari tikus penipu itu, bukan?",
  ui_story_5004_50043001_62_dialog_content = "Mari kita belum bergerak. Kami tidak cukup tahu tentang tempat ini. Sebaiknya kita coba bicara dulu.",
  ui_story_5004_50043001_63_option_content = "Siapa kau?",
  ui_story_5004_50043001_64_dialog_content = "Saya... eh... Coba saya pikir, apa yang tertulis di jurnal kedua...?",
  ui_story_5004_50043001_65_dialog_content = "Saya seorang sarjana besar dan algojo tanpa ampun!",
  ui_story_5004_50043001_66_dialog_content = "Wow, saya sangat mengesankan!",
  ui_story_5004_50043001_67_dialog_content = "(Dia masih menjualnya...)",
  ui_story_5004_50043001_68_option_content = "Apa itu Dream Void Keep?",
  ui_story_5004_50043001_69_dialog_content = "Di situlah kita sekarang! Coba saya lihat... Ini adalah permainan catur dari penderitaan mental murni dan kegilaan.",
  ui_story_5004_50043001_70_dialog_content = "Itulah yang tertulis dalam jurnal keenam saya.",
  ui_story_5004_50043001_71_dialog_content = "Ini juga tempat Raja tidur dan tempat aku berjanji untuk membangunkannya.",
  ui_story_5004_50043001_72_dialog_content = "(Mengingat Darkflow, ada Eclipsite yang sangat kuat di sekitar sini. Mungkinkah Monarch yang dia bicarakan?)",
  ui_story_5004_50043001_73_option_content = "Mengapa itu muncul dari dasar laut?",
  ui_story_5004_50043001_74_dialog_content = "Pertanyaan bagus.",
  ui_story_5004_50043001_75_dialog_content = "\"Itu adalah kota yang luar biasa sebelum dibuang oleh Caelestites yang jahat.\"",
  ui_story_5004_50043001_76_dialog_content = "\"Ras jahat mendapatkan gurun yang adil ketika mereka dibantai.\"",
  ui_story_5004_50043001_77_dialog_content = "Hei, ada banyak hal dalam buku \"Cara Memasak Caelestites\" ini!",
  ui_story_5004_50043001_78_dialog_content = "Camilan apa yang kamu suka, Caelestite? Aku bisa membuatmu menjadi apapun yang kamu suka!",
  ui_story_5004_50043001_79_dialog_content = "(Diusir oleh Caelestites? Apakah dia memanfaatkan obsesi Bonacie dengan Gerakan dan merekayasa plotnya?)",
  ui_story_5004_50043001_80_dialog_content = "Aku sudah muak dengan ocehannya, PlayerName.",
  ui_story_5004_50043001_81_option_content = "Tunggu tunggu...",
  ui_story_5004_50043001_82_dialog_content = "Saya hanya punya beberapa buku dan jurnal lagi. Mari kita bicara lagi.",
  ui_story_5004_50043001_83_option_content = "Dia kehilangan semua kelerengnya...",
  ui_story_5004_50043001_84_dialog_content = "Ayo serang sebelum kita semua bingung dengannya, PlayerName.",
  ui_story_5004_50043001_85_dialog_content = "Apa? Tidak, tolong jangan serang saya!",
  ui_story_5004_50043001_86_dialog_content = "Jika kau melakukannya, aku... aku harus membunuhmu!",
  ui_story_5004_50043001_87_dialog_content = "Dan Anda tidak bisa mati begitu cepat! Anda mengalami kesulitan untuk sampai ke sini, jadi mengapa tidak mencari tahu lebih banyak tentang tempat ini?",
  ui_story_5004_50043001_88_dialog_content = "Ayo, bisa kita bicara? Jangan serang aku! Aku akan menyajikan teh untukmu!",
  ui_story_5004_50043001_89_dialog_content = "Tiga, empat, lima, enam ... Saya akan mendapatkan porsi untuk tujuh sekarang!",
  ui_story_5004_50043001_90_dialog_content = "Dia terbang menjauh... Hei, tunggu, bukankah kita punya delapan orang?",
  ui_story_5004_50043001_91_dialog_content = "Dimana Bonacie?",
  ui_story_5004_50043001_92_dialog_content = "Tahan di sana! Apa yang kamu lakukan dengan Bonacie?",
  ui_story_5004_50043001_93_dialog_content = "Kasar sekali! Saya baru saja mengirimnya ke tempat yang lebih cocok untuk pesta teh.",
  ui_story_5004_50043001_94_dialog_content = "Kembalikan dia. Sekarang!",
  ui_story_5004_50043001_95_dialog_content = "Apakah itu perintah? Haha, betapa menggemaskannya tamuku yang memberiku perintah!",
  ui_story_5004_50043001_96_dialog_content = "Anda pengganggu kurang ajar dari pesta teh saya ... Tidak, saya tidak ingin membunuh Anda. Aku harus mengendalikan diriku!",
  ui_story_5004_50043001_97_dialog_content = "Hei, kamu dari Lumopolis, kan? Aku bisa merasakannya.",
  ui_story_5004_50043001_98_dialog_content = "Arogan, berpendirian, dan tidak setuju.",
  ui_story_5004_50043001_99_dialog_content = "Kembali padamu. Sebagai Kapten Penjaga Lumopolis...",
  ui_story_5004_50043001_100_dialog_content = "Setiap Eclipsite yang mengancam keberadaan Aurorian akan menghadapi kemarahanku!",
  ui_story_5004_50043001_101_dialog_content = "Heh...",
  ui_story_5004_50043001_102_dialog_content = "Hehehe...",
  ui_story_5004_50043001_103_dialog_content = "Hahaha!",
  ui_story_5004_50043001_104_dialog_content = "Dikatakan dengan baik, dikatakan dengan sangat baik!",
  ui_story_5004_50043001_105_dialog_content = "Saya tidak bisa melawannya lagi, Kapten sayang, saya tidak bisa!",
  ui_story_5004_50043001_106_dialog_content = "Jika Anda bersikeras, maka Anda harus bermain dengan mainan saya!",
  ui_story_5004_50043001_107_dialog_content = "Aahhhh!",
  ui_story_5004_50043001_108_dialog_content = "Awas, monster masuk!",
  ui_story_5004_50043101_1_dialog_content = "Itu menyenangkan, kapten gadisku.",
  ui_story_5004_50043101_2_dialog_content = "Saya minum beberapa cangkir teh melihat Anda berkelahi dan itu membuat saya merasa jauh lebih baik.",
  ui_story_5004_50043101_3_dialog_content = "Tapi saya melihat Anda semua memiliki beberapa luka lagi dan ayunan Anda semakin lambat.",
  ui_story_5004_50043101_4_dialog_content = "Saya kira Aurorian tidak begitu tangguh, mengingat Anda mengalami kesulitan dengan mainan saya.",
  ui_story_5004_50043101_5_dialog_content = "Saya sarankan Anda tidak mengganggu saya atau bahkan terburu-buru pada saya. Anda harus berbicara dengan saya, atau setidaknya mengulur waktu.",
  ui_story_5004_50043101_6_dialog_content = "Selama bertahun-tahun saya membuat jurnal, ini adalah hal paling menarik yang terjadi dalam waktu yang lama.",
  ui_story_5004_50043101_7_dialog_content = "Tolong temani aku sebentar lagi!",
  ui_story_5004_50043101_8_dialog_content = "Apa yang sebenarnya kamu inginkan?",
  ui_story_5004_50043101_9_dialog_content = "Apa itu? Biarkan saya berpikir... Saya lelah dengan pekerjaan penelitian, jadi bagaimana kalau menjadi koki gourmet?",
  ui_story_5004_50043101_10_dialog_content = "Seperti \"Cara Memasak Caelestites\" favorit saya, saya harus menulis \"Cara Memasak Auroria\"!",
  ui_story_5004_50043101_11_dialog_content = "Oh tunggu, tidak, aku menjadi bersemangat hanya dengan memikirkannya, dan itu mungkin membuatku ingin membunuhmu lagi!",
  ui_story_5004_50043101_12_dialog_content = "Tidak, membosankan untuk membunuhmu begitu saja, dan Raja harus menghadiri pesta teh yang telah aku rencanakan sejak lama...",
  ui_story_5004_50043101_13_dialog_content = "Itu Raja Desolate saya, tuan baru saya yang memberi saya kekuatan saya. Dia akan senang makan makanan ringan yang dibuat dari Anda.",
  ui_story_5004_50043101_14_dialog_content = "Ya, Anda akan menyaksikan kekuatan saya dan merasakan ketakutan dan keputusasaan ...",
  ui_story_5004_50043101_15_dialog_content = "Itu akan membuat Anda lebih enak dan lezat!",
  ui_story_5004_50043101_16_dialog_content = "Ini bukan kekuatan, hanya trik mewah!",
  ui_story_5004_50043101_17_dialog_content = "Berhentilah membual, Eclipsite.",
  ui_story_5004_50043101_18_dialog_content = "Kreasi Anda hanya gundukan di jalan.",
  ui_story_5004_50043101_19_dialog_content = "Membuat dan mengendalikan boneka-boneka yang tidak punya pikiran ini akan merugikan Anda.",
  ui_story_5004_50043101_20_dialog_content = "Segera setelah kami menemukan Anda yang sebenarnya, semuanya berakhir!",
  ui_story_5004_50043101_21_dialog_content = "Benar, aku tidak memiliki kekuatan sebesar itu, tapi Raja memilikinya.",
  ui_story_5004_50043101_22_dialog_content = "\"Orang-orang tertentu di Lumopolis menginginkan kekuatan besar Eclipsites.\"",
  ui_story_5004_50043101_23_dialog_content = "\"Beberapa bahkan akan membuat kesepakatan dengan Eclipsites, bahkan menukar tubuh dan nyawa mereka untuk mendapatkan Darkflow.\"",
  ui_story_5004_50043101_24_dialog_content = "Coba saya lihat... Buku ini berumur lebih dari satu dekade. Apakah Lumopolis masih seperti ini?",
  ui_story_5004_50043101_25_dialog_content = "Maukah Anda memberi tahu saya bagaimana rasanya melindungi para pengkhianat itu, Kapten tersayang?",
  ui_story_5004_50043101_26_dialog_content = "Kata-katamu tidak bisa menggodaku, bidat.",
  ui_story_5004_50043101_27_dialog_content = "Tidak buruk. Saya melihat dibutuhkan lebih dari sekedar otot untuk menjadi seorang kapten.",
  ui_story_5004_50043101_28_dialog_content = "Jadi Anda sudah tahu apa itu Lumopolis yang berantakan.",
  ui_story_5004_50043101_29_dialog_content = "Ya, yang disebut kota yang tidak pernah jatuh, menara putih yang tinggi...",
  ui_story_5004_50043101_30_dialog_content = "Dugaan juara harapan sebenarnya adalah bangsawan yang terbaring di bawahnya...",
  ui_story_5004_50043101_31_dialog_content = "Para penipu bermuka dua!",
  ui_story_5004_50043101_32_dialog_content = "Siapa yang mengira pemalsuan sok bisa berada di antara elit penguasa!",
  ui_story_5004_50043101_33_dialog_content = "Bukan begitu, ya, ya, ya?",
  ui_story_5004_50043101_34_dialog_content = "<color=#FFB400>Beryl Gautier</color>!",
  ui_story_5004_50043101_35_dialog_content = "Anda tahu saya ... Siapa Anda? Bagaimana Anda tahu saya?",
  ui_story_5004_50043101_36_dialog_content = "Gautier, Gautier, Gautier...",
  ui_story_5004_50043101_37_dialog_content = "Tentu saja saya mengenali Anda, dan keluarga konyol Anda juga!",
  ui_story_5004_50043101_38_dialog_content = "Namamu ada di setiap jurnalku!",
  ui_story_5004_50043101_39_dialog_content = "Bukankah Anda di sini untuk menebus karena darah mengalir di pembuluh darah Anda dan dosa-dosa yang Anda bawa?",
  ui_story_5004_50043101_40_dialog_content = "Mereka tahu betapa kuatnya kristal itu ...",
  ui_story_5004_50043101_41_dialog_content = "Namun mereka masih mencoba menipu kematian. Betapa tidak masuk akalnya!",
  ui_story_5004_50043101_42_dialog_content = "Itu kekuatan, kekuatan murni, yang harus digunakan untuk menaklukkan dan menghancurkan!",
  ui_story_5004_50043101_43_dialog_content = "Ini bukan mainan untuk badut, terutama yang ada di Lumopolis!",
  ui_story_5004_50043101_44_dialog_content = "Bagaimana Anda tahu begitu banyak tentang keluarga saya ...?",
  ui_story_5004_50043101_45_dialog_content = "Bagaimana? Oh, jadi kamu tidak ingat. Itu keren! Tunggu, tidak, tidak bagus, sayang sekali!",
  ui_story_5004_50043101_46_dialog_content = "Sayang sekali, sayang sekali... Kamu bisa menghindarinya jika kamu membuat jurnal sepertiku.",
  ui_story_5004_50043101_47_dialog_content = "Saya akan menyiapkan porsi ekstra untuk Anda, dibuat dari gadis di sebelah Anda.",
  ui_story_5004_50043101_48_dialog_content = "Jangan berani-berani menyentuh Raphael!",
  ui_story_5004_50043101_49_dialog_content = "Beryl kecil...",
  ui_story_5004_50043101_50_dialog_content = "Oh? Baiklah, baiklah, aku tidak akan menyentuhnya. Hee!",
  ui_story_5004_50043101_51_dialog_content = "Tetapi bahkan jika saya tidak melakukannya, apakah Anda pikir Anda dapat melindunginya sebagai pion belaka?",
  ui_story_5004_50043101_52_dialog_content = "Saya akan dengan sungguh-sungguh menulis tentang hubungan Anda yang menyentuh secara detail!",
  ui_story_5004_50043101_53_dialog_content = "Anda akan hidup dalam tulisan saya setelah kematian Anda!",
  ui_story_5004_50043101_54_dialog_content = "Apa yang harus saya sebut itu? \"Kepolosan Bodoh\"? \"Lagu Sedih Pion\"?",
  ui_story_5004_50043101_55_dialog_content = "Anda semua Aurorian membuat saya tertawa dengan kebodohan Anda, begitu banyak, saya ingin mengikat Anda masing-masing dan menginterogasi Anda untuk sebuah buku!",
  ui_story_5004_50043101_56_dialog_content = "Oh, benar, dan membuat Anda menjadi camilan untuk menemani teh saya!",
  ui_story_5004_50043101_57_dialog_content = "Membaca kisah hidup Anda sambil mencicipi daging dan darah Anda...",
  ui_story_5004_50043101_58_dialog_content = "Ambil contoh Aurorian bodoh itu, subjek dari buku \"Musisi Bodoh\" saya.",
  ui_story_5004_50043101_59_dialog_content = "Dia hanya ingin bermain musik dan tanpa disadari merusak segelnya.",
  ui_story_5004_50043101_60_dialog_content = "Saya mengirim Eclipsites ke hotel dan <color=#FFB400>memasang perangkap</color>... Kemudian memegang Penguasa Laut untuk menyedot Lumina dari semua Aurorian yang hadir.",
  ui_story_5004_50043101_61_dialog_content = "Kalian semua memainkan peran besar dalam menghidupkan kembali Raja Desolate!",
  ui_story_5004_50043101_62_dialog_content = "Saya ahli strategi, ahli taktik, konspirator, pemain catur yang sempurna... oh yeah, dan penulis!",
  ui_story_5004_50043101_63_dialog_content = "Anda lupa orang gila. Anda sudah kehilangan akal karena berada di sini terlalu lama!",
  ui_story_5004_50043101_64_dialog_content = "Apa? Beraninya kau... Beraninya kau mengatakan sesuatu yang sangat berharga!",
  ui_story_5004_50043101_65_dialog_content = "Sebelum saya membuat Anda menjadi makanan penutup, cobalah untuk tidak terbunuh oleh mainan baru saya, saya mohon.",
  ui_story_5004_50043101_66_dialog_content = "Silakan bertahan!",
  ui_story_5004_50043201_1_dialog_content = "Huft, huft...",
  ui_story_5004_50043201_2_dialog_content = "Hidungmu berdarah lagi, PlayerName. Jangan mendorongnya.",
  ui_story_5004_50043201_3_dialog_content = "Aku baik-baik saja, hanya sedikit lelah.",
  ui_story_5004_50043201_4_dialog_content = "(Pertempuran terus-menerus sangat merugikan saya ...)",
  ui_story_5004_50043201_5_dialog_content = "Apakah pertarungan sudah berakhir? Saya baru saja memulai makanan penutup berikutnya.",
  ui_story_5004_50043201_6_dialog_content = "Komentar saya tentang pertempuran terakhir Anda adalah...",
  ui_story_5004_50043201_7_dialog_content = "\"Seorang anak yang mengarahkan perkelahian berkelahi dengan kecepatan seorang wanita tua mengayunkan tongkat.\"",
  ui_story_5004_50043201_8_dialog_content = "Sejujurnya, Anda semakin lambat. Aku punya empat cangkir teh dan camilan menunggumu.",
  ui_story_5004_50043201_9_dialog_content = "Anda ... Anda pikir ini adalah permainan?",
  ui_story_5004_50043201_10_dialog_content = "Apakah Anda bangga mengirimkan ilusi dan klon untuk melawan kami?",
  ui_story_5004_50043201_11_dialog_content = "Keluar dan bertarung secara langsung jika Anda punya nyali!",
  ui_story_5004_50043201_12_dialog_content = "Memanggil saya keluar ketika Anda bahkan tidak bisa mengalahkan mainan menyedihkan saya?",
  ui_story_5004_50043201_13_dialog_content = "Saya ingin tahu lebih banyak tentang Anda, karena saya percaya makanan paling enak saat penuh emosi.",
  ui_story_5004_50043201_14_dialog_content = "Selain itu, Desolate Monarch masih mengumpulkan kekuatannya. Kami punya waktu untuk mengobrol.",
  ui_story_5004_50043201_15_dialog_content = "Oh, saya menemukan jurnal pertama! Biarkan saya melihat apa yang saya tulis ...",
  ui_story_5004_50043201_16_dialog_content = "Bwahaha, penemuan yang luar biasa! Kemarilah dan biarkan aku membacakannya untukmu!",
  ui_story_5004_50043201_17_dialog_content = "Ahem, berhenti sejenak saat aku berdehem.",
  ui_story_5004_50043201_18_dialog_content = "Mengapa otak kecilmu yang malang tidak dapat memahaminya, gadis kecil Gautier?",
  ui_story_5004_50043201_19_dialog_content = "Siapa yang tahu banyak tentang kristal, dan siapa yang bisa memanggil Anda dalam mimpi Anda?",
  ui_story_5004_50043201_20_dialog_content = "Itu kamu... Kamu satu-satunya Pyrrhus yang masih hidup... yang membelot ke Eclipsites... Caroline Pyrrhus!",
  ui_story_5004_50043201_21_dialog_content = "Ya, satu-satunya!",
  ui_story_5004_50043201_22_dialog_content = "Oh tidak, memalukan mendengar nama Aurorian lamaku!",
  ui_story_5004_50043201_23_dialog_content = "Saya tahu saya tidak seharusnya membaca jurnal untuk orang lain.",
  ui_story_5004_50043201_24_dialog_content = "Tapi aku masih ingin, jadi pinjamkan aku telingamu!",
  ui_story_5004_50043201_25_dialog_content = "Anda adalah seorang Aurorian?",
  ui_story_5004_50043201_26_dialog_content = "Satu lagi yang menyerahkan dan menjual jiwanya ke Eclipsites.",
  ui_story_5004_50043201_27_dialog_content = "Hee, benar, saya hampir lupa bahwa saya pernah menjadi seorang Aurorian.",
  ui_story_5004_50043201_28_dialog_content = "Tapi jurnal ini penuh dengan detail tentang betapa bebas dan bahagianya saya setelah menjadi Eclipsite.",
  ui_story_5004_50043201_29_dialog_content = "Ribuan kali lebih bahagia daripada di Lumopolis!",
  ui_story_5004_50043201_30_dialog_content = "Kembali ke topik. Seperti yang baru saja saya katakan, tidak seperti keluarga saya, keluarga Anda hanya ingin menggunakan kristal sebagai sumber listrik...",
  ui_story_5004_50043201_31_dialog_content = "Ketika kekuatannya yang brutal dan kejam harus dimanfaatkan sebagai senjata!",
  ui_story_5004_50043201_34_dialog_content = "Itu bisa menjadi kekuatan untuk mengusir Eclipsites dari Lumopolis, bahkan mengirim mereka kembali ke jurang!",
  ui_story_5004_50043201_35_dialog_content = "Namun keluarga lemah Anda menangis kepada Tuan Kota tentang hal itu! Oh, aku mulai marah lagi setelah membaca bagian ini!",
  ui_story_5004_50043201_36_dialog_content = "Kalian para Pyrrhuses menculik para Aurorian yang tertindas dan bereksperimen dengan kristal-kristal itu.",
  ui_story_5004_50043201_37_dialog_content = "Tidak ada yang masuk akal akan memaafkan bereksperimen pada jenis mereka sendiri!",
  ui_story_5004_50043201_38_dialog_content = "Saya akui saya benar-benar menyukai eksperimen ketika saya masih muda.",
  ui_story_5004_50043201_39_dialog_content = "Tapi tanpa saya, tidak akan ada Beryl yang Anda lihat sekarang, subjek saya yang paling membanggakan...",
  ui_story_5004_50043201_40_dialog_content = "Jangan katakan padaku Beryl...",
  ui_story_5004_50043201_41_dialog_content = "...",
  ui_story_5004_50043201_42_dialog_content = "Jurnal memiliki informasi yang sangat rinci. Makanan favorit Anda, olahraga favorit ...",
  ui_story_5004_50043201_43_dialog_content = "Bahkan apa yang Anda suka pegang saat Anda tidur.",
  ui_story_5004_50043201_44_dialog_content = "Seolah-olah penulis jatuh cinta padamu!",
  ui_story_5004_50043201_45_dialog_content = "Tunggu, saya penulisnya, jadi itu membuat saya intip.",
  ui_story_5004_50043201_46_dialog_content = "Meskipun tidak sepenuhnya sempurna, itu adalah tonggak sejarah dalam eksperimen saya.",
  ui_story_5004_50043201_47_dialog_content = "Dan aku menaruh cinta padamu...",
  ui_story_5004_50043201_48_dialog_content = "Kristal bubuk khusus yang dibuat dengan Darkflow masih tumbuh di tubuhmu, bukan?",
  ui_story_5004_50043201_49_dialog_content = "Mereka hidup di dalam diri Anda, memakan emosi dan kemauan Anda.",
  ui_story_5004_50043201_50_dialog_content = "Berhenti...",
  ui_story_5004_50043201_51_dialog_content = "Tapi mereka pasti tidak stabil... Hee, ini dia, bagian favoritku!",
  ui_story_5004_50043201_52_dialog_content = "Oh, api besar yang kau mulai, dan tangisan korban Aurorian yang tak terhitung jumlahnya itu...",
  ui_story_5004_50043201_53_dialog_content = "Hentikan!",
  ui_story_5004_50043201_54_dialog_content = "Jangan sombong!",
  ui_story_5004_50043201_55_dialog_content = "Hee, Raja memanggilku...",
  ui_story_5004_50043201_56_dialog_content = "Saya akan segera kembali dan mengubah Anda menjadi makanan lezat seperti Auroria panggang itu.",
  ui_story_5004_50043201_57_dialog_content = "Tidak, tidak, tidak, tidak, tidak!",
  ui_story_5004_50043201_58_dialog_content = "Tenang, Beryl!",
  ui_story_5004_50043201_59_dialog_content = "Raphael, biarkan aku mencoba menenangkannya dengan telepati!",
  ui_story_5004_50043201_60_dialog_content = "Tolong cepat. Sepertinya dia sangat kesakitan...",
  ui_story_5004_50043201_61_dialog_content = "(Saya merasakan kekuatan buas mengalir melalui tubuhnya.)",
  ui_story_5004_50043201_62_dialog_content = "(Ini jelas sesuatu yang tidak dimiliki Aurorian, namun juga bukan Darkflow.)",
  ui_story_5004_50043201_63_dialog_content = "(Mungkin itu kekuatan jahat dan destruktif seperti yang dikatakan Caroline.)",
  ui_story_5004_50043201_64_dialog_content = "(Beryl telah berjuang untuk mengendalikannya, hanya untuk Caroline yang memprovokasi dia ...)",
  ui_story_5004_50043201_65_dialog_content = "(Dan dia kehilangan kendali sedikit demi sedikit.)",
  ui_story_5004_50043201_66_dialog_content = "Beryl kecil...",
  ui_story_5004_50043201_67_dialog_content = "Raphael... Aku baik-baik saja sekarang... Terima kasih, PlayerName.",
  ui_story_5004_50043201_68_dialog_content = "Maaf... aku tidak bermaksud menyembunyikan masa laluku darimu...",
  ui_story_5004_50043201_69_dialog_content = "Tapi itu mungkin karena eksperimen Caroline... atau mungkin aku secara naluriah menolak untuk mengingat kenangan menyakitkan itu...",
  ui_story_5004_50043201_70_dialog_content = "Bagian dari masa lalu itu adalah satu kekaburan besar bagi saya...",
  ui_story_5004_50043201_71_dialog_content = "Saya hanya ingat bahwa Pyrrhus menculik saya ketika saya masih sangat muda.",
  ui_story_5004_50043201_72_dialog_content = "Mereka mengunciku di ruangan yang benar-benar gelap... memberiku bubuk kristal.",
  ui_story_5004_50043201_73_dialog_content = "Kemudian tubuhku bertingkah seperti dikutuk... Aku tidak bisa melepaskan diri dari kristal yang membuatku menderita.",
  ui_story_5004_50043201_74_dialog_content = "Tidak sampai kemudian saya menemukan ... bahwa itu adalah eksperimen Pyrrhus untuk mengubah Aurorian menjadi senjata ... melalui kristal.",
  ui_story_5004_50043201_75_dialog_content = "Tidak apa-apa, Beryl. Setiap orang memiliki masa lalunya masing-masing.",
  ui_story_5004_50043201_76_dialog_content = "Bagikan saat-saat bahagia dan lupakan yang tidak menyenangkan. Tidak ada yang menyalahkan Anda karena menginginkan kehidupan baru.",
  ui_story_5004_50043201_77_dialog_content = "Aku baik-baik saja dengan itu. Maksudku, masa laluku tidak lebih baik dari masa lalumu.",
  ui_story_5004_50043201_78_dialog_content = "Aku juga tidak keberatan. Anda tidak perlu mempermalukan diri sendiri.",
  ui_story_5004_50043201_79_dialog_content = "Kami berteman, dan saya percaya Anda saat ini, tidak peduli apa yang terjadi di masa lalu!",
  ui_story_5004_50043201_80_dialog_content = "Tanpa ragu, masalah mendesak adalah menghukum Caroline atas dosa-dosa yang dia lakukan dan menghentikan lebih banyak tragedi terjadi.",
  ui_story_5004_50043201_81_dialog_content = "Aku bersama kalian semua, tentu saja.",
  ui_story_5004_50043201_82_dialog_content = "Terimakasih semuanya...",
  ui_story_5004_50043201_83_dialog_content = "Caroline Pyrrhus... Dia benar-benar tidak punya kehormatan untuk disebut sebagai mantan bangsawan.",
  ui_story_5004_50043201_84_dialog_content = "Dia tidak hanya bersekongkol dengan Eclipsites, tetapi dia juga melakukan kekejaman terhadap rakyatnya sendiri.",
  ui_story_5004_50043201_85_dialog_content = "Lalu ada Raja yang dia hormati. Jika dia sekuat yang dia gambarkan ...",
  ui_story_5004_50043201_86_dialog_content = "Kita harus menghentikan Monarch agar tidak terbangun.",
  ui_story_5004_50043201_87_dialog_content = "Tapi bagaimana kita akan menemukan bentuk aslinya dalam ilusi ini?",
  ui_story_5004_50043201_88_dialog_content = "Nah, ketika PlayerName membantu saya secara telepati...",
  ui_story_5004_50043201_89_dialog_content = "Saya pikir saya merasakan tempat dengan banyak kristal ...",
  ui_story_5004_50043201_90_dialog_content = "Mungkin di situlah mereka bersembunyi...",
  ui_story_5004_50043201_91_dialog_content = "Kerja yang baik! Ayo pergi ke sana!",
  ui_story_5004_50043201_92_dialog_content = "Ya, dan itu akan menjadi pertempuran yang melelahkan.",
  ui_story_5004_50043201_93_dialog_content = "Jangan khawatir, Beryl, aku akan mendapatkan balasan dari penyihir itu untukmu!",
  ui_story_5004_50043201_94_dialog_content = "Ya... Lalu kita kembali ke Lumopolis seperti yang kita janjikan.",
  ui_story_5004_50043201_95_dialog_content = "Terlepas dari musuh apa yang menunggu, saya tidak akan mundur!",
  ui_story_5004_50043301_1_dialog_content = "Wow, tidak menyangka bisa menemukan tempat ini.",
  ui_story_5004_50043301_2_dialog_content = "Ahem! \"Saya menghargai kalian semua datang ke <color=#FFB400>Ruang tahta</color> untuk berlutut di depan penguasa barumu.\"",
  ui_story_5004_50043301_3_dialog_content = "\"Ini adalah wujud baruku yang dibuat dari kristal, dengan kekuatan yang identik dengan milikmu, Beryl.\"",
  ui_story_5004_50043301_4_dialog_content = "\"Perbedaannya adalah, kamu hanya prototipe, dan aku adalah produk akhir yang mampu mengendalikan semua kekuatan kristal.\"",
  ui_story_5004_50043301_5_dialog_content = "\"Dan <color=#FFB400>Raja Sunyi</color> juga akan bangkit kembali melalui kristal dan memerintah sekali lagi.\"",
  ui_story_5004_50043301_6_dialog_content = "Ahem, itulah awal dari pidato yang saya tulis untuk Anda semua. Apakah kamu menyukainya?",
  ui_story_5004_50043301_7_dialog_content = "<color=#e8d9bb>Caroline melambaikan tangannya dan kristal itu pecah. Kemudian badai tepung diserap oleh Raja.</color>",
  ui_story_5004_50043301_8_dialog_content = "...",
  ui_story_5004_50043301_9_dialog_content = "Apakah kamu melihat itu? Seberapa kompatibel kekuatan kristal dengan Eclipsites!",
  ui_story_5004_50043301_10_dialog_content = "Dan saya pikir itu adalah berkah dari dewa untuk Aurorian! Aku malu pada gagasan itu!",
  ui_story_5004_50043301_11_dialog_content = "Ini jelas merupakan hadiah untuk Eclipsites!",
  ui_story_5004_50043301_12_dialog_content = "Aku sudah cukup dengan teriakanmu.",
  ui_story_5004_50043301_13_dialog_content = "Mari kita bertarung di tempat terbuka!",
  ui_story_5004_50043301_14_dialog_content = "Akhirnya, akhirnya... Hee... Haha! Aku pada titik di mana aku ingin membunuhmu sekarang!",
  ui_story_5004_50043301_15_dialog_content = "Cepat, cepat! Lebih banyak rasa sakit, lebih banyak keputusasaan untuk lebih banyak rasa!",
  ui_story_5004_50043302_1_dialog_content = "Sialan, mereka terus berdatangan!",
  ui_story_5004_50043302_2_dialog_content = "Berhentilah bermain-main dengan para prajurit... Bakar, sayang, bakar!",
  ui_story_5004_50043302_3_dialog_content = "Tidak mungkin... aku...",
  ui_story_5004_50043302_4_dialog_content = "Tembak kepala langsung! Cahayanya meredup!",
  ui_story_5004_50043302_5_dialog_content = "Kita berhasil?",
  ui_story_5004_50043302_6_dialog_content = "...",
  ui_story_5004_50043302_7_dialog_content = "Hee, tertipu Anda!",
  ui_story_5004_50043302_8_dialog_content = "!",
  ui_story_5004_50043302_9_dialog_content = "Smokey!",
  ui_story_5004_50043302_10_dialog_content = "Itu menyakitkan... Lepaskan aku!",
  ui_story_5004_50043302_11_dialog_content = "Tidak mengharapkan penyergapan. Terima kasih telah mencariku.",
  ui_story_5004_50043302_12_dialog_content = "Tunggu, itu luka yang dalam. Biarkan Raphael mengobatinya untukmu!",
  ui_story_5004_50043302_13_dialog_content = "(Sial, tidak turun! Sementara itu, Eclipsites terus bermunculan di mana-mana...)",
  ui_story_5004_50043302_14_dialog_content = "(Ini tidak mungkin, belum pernah bertemu Eclipsite yang dikonversi sekuat ini sebelumnya!)",
  ui_story_5004_50043302_15_dialog_content = "(Mungkinkah Raja ada hubungannya dengan itu...?)",
  ui_story_5004_50043302_16_dialog_content = "Fokus, PlayerName! Gelombang pertempuran bisa berubah kapan saja!",
  ui_story_5004_50043302_17_dialog_content = "Cari bukaan apa saja.",
  ui_story_5004_50043302_18_dialog_content = "Anda di sana, berbicara lebih keras sehingga saya bisa menulis kata-kata terakhir Anda ke dalam jurnal saya!",
  ui_story_5004_50043302_19_dialog_content = "Mekarlah!",
  ui_story_5004_50043302_20_dialog_content = "*Batuk*... Asapnya tebal sekali. Apakah Beryl meledakkan kristal pada Caroline sebagai pertahanan?",
  ui_story_5004_50043302_21_dialog_content = "...",
  ui_story_5004_50043302_22_dialog_content = "Boleh juga.",
  ui_story_5004_50043302_23_dialog_content = "Bagaimana mungkin...?",
  ui_story_5004_50043302_24_dialog_content = "Kenapa tidak ada goresan padanya?",
  ui_story_5004_50043302_25_dialog_content = "Mana mungkin...",
  ui_story_5004_50043302_26_dialog_content = "Cukup mengesankan untuk sebuah prototipe.",
  ui_story_5004_50043302_27_dialog_content = "Bagaimanapun, Berylku yang malang, eksperimenku yang gagal...",
  ui_story_5004_50043302_28_dialog_content = "Kamu masih tidak berguna seperti dulu.",
  ui_story_5004_50043302_29_dialog_content = "Kau membunuh begitu banyak orang, membunuh orang tuamu... Menurutmu siapa yang bisa kau selamatkan sekarang?",
  ui_story_5004_50043302_30_dialog_content = "Saya memperingatkan Anda, Anda akan menjadi kematian semua orang tersayang di sekitar Anda sebelum jatuh ke dalam jurang.",
  ui_story_5004_50043302_31_dialog_content = "Tidak...",
  ui_story_5004_50043302_32_dialog_content = "Orang tua...?",
  ui_story_5004_50043302_33_dialog_content = "Aahhhhhh!",
  ui_story_5004_50043302_34_dialog_content = "Jangan hentikan aku, monster!",
  ui_story_5004_50043302_35_dialog_content = "Carleen dan Vice, lindungi Raphael!",
  ui_story_5004_50043302_36_dialog_content = "Saya tahu Anda masih ingat bagaimana Anda membantai orang tua Anda yang tak berdaya ...",
  ui_story_5004_50043302_37_dialog_content = "Terimalah kematianmu. Ini adalah penebusan atas kejahatanmu. Itu adalah keselamatanmu.",
  ui_story_5004_50043302_38_dialog_content = "Maaf, semuanya... Maaf, ibu dan ayah...",
  ui_story_5004_50043302_39_dialog_content = "Beril!",
  ui_story_5004_50043302_40_dialog_content = "Jangan dengarkan dia, Beryl. Dia membunuh orang tuamu!",
  ui_story_5004_50043302_41_dialog_content = "Anda memang kehilangan kendali dan menyebabkan kebakaran, tetapi kemudian Anda langsung pingsan!",
  ui_story_5004_50043302_42_dialog_content = "Dia menyanderamu dan membunuh orang tua dan keluargamu!",
  ui_story_5004_50043302_43_dialog_content = "...",
  ui_story_5004_50043302_44_dialog_content = "Itu pengakuan dari anggota Pyrrhus yang ditangkap, jadi itu kebenarannya!",
  ui_story_5004_50043302_45_dialog_content = "Anda ikut campur!",
  ui_story_5004_50043302_46_dialog_content = "Ugh!",
  ui_story_5004_50043302_47_dialog_content = "Heh, itu twist yang tak terduga.",
  ui_story_5004_50043302_48_dialog_content = "Tapi, tapi... Haha!",
  ui_story_5004_50043302_49_dialog_content = "Anda benar-benar percaya itu!",
  ui_story_5004_50043302_50_dialog_content = "!",
  ui_story_5004_50043302_51_dialog_content = "Jadi, apakah Anda ingat bagaimana mayat orang tua Anda terlihat ketika Anda datang?",
  ui_story_5004_50043302_52_dialog_content = "Saya mementaskan itu khusus untuk Anda, supaya Anda berpikir Anda membunuh mereka!",
  ui_story_5004_50043302_53_dialog_content = "Sangat bodoh, sangat bodoh, sangat bodoh bagi Anda untuk benar-benar jatuh cinta padanya! Dan setelah sekian lama!",
  ui_story_5004_50043302_54_dialog_content = "Kenapa kamu...",
  ui_story_5004_50043302_55_dialog_content = "Saya merasa merinding setiap kali saya sampai ke bagian jurnal ini!",
  ui_story_5004_50043302_56_dialog_content = "Kamu pasti mengira kamu telah membunuh orang tuamu selama ini!",
  ui_story_5004_50043302_57_dialog_content = "Jurnal ini adalah milik saya yang paling berharga, dan saya ingin membaginya dengan Anda!",
  ui_story_5004_50043302_58_dialog_content = "Alasan besar aku membiarkanmu hidup adalah agar aku bisa menuliskan ekspresi di wajahmu sekarang!",
  ui_story_5004_50043302_59_dialog_content = "Bahagia sekarang? Anda telah hidup dengan gagasan Anda membunuh orang yang Anda cintai selama ini.",
  ui_story_5004_50043302_60_dialog_content = "Ekspresi Anda ketika Anda akhirnya menemukan kebenaran sangat indah!",
  ui_story_5004_50043302_61_dialog_content = "Aku akan merobek wajahmu untuk membuat sampul jurnalku!",
  ui_story_5004_50043302_62_dialog_content = "Gautier, Gautier! Beginilah seharusnya pengkhianat Gautier berakhir!",
  ui_story_5004_50043302_63_dialog_content = "Beraninya kau melakukan itu!",
  ui_story_5004_50043302_64_dialog_content = "Prototipe gagal sepertimu bahkan tidak bisa bermimpi untuk melawan aku yang sempurna dan Raja yang bangkit!",
  ui_story_5004_50043302_65_dialog_content = "Untuk menyematkan pembunuhan pada saya dan mencoba untuk menyakiti teman-teman saya ...",
  ui_story_5004_50043302_66_dialog_content = "Aku tidak akan pernah memaafkanmu!",
  ui_story_5004_50043302_67_dialog_content = "Apakah ini kekuatan yang selama ini ditekan oleh Beryl?",
  ui_story_5004_50043302_68_dialog_content = "Jika Anda melepaskan kekuatannya, Anda bisa menjadi monster seperti Caroline!",
  ui_story_5004_50043302_69_dialog_content = "Saya kehilangan orang yang saya cintai dan terperosok dalam rasa sakit dan rasa bersalah karena saya kecil dan lemah ...",
  ui_story_5004_50043302_70_dialog_content = "Pelakunya sekarang ada di depanku, dan mencoba menyakiti orang-orang yang dekat denganku!",
  ui_story_5004_50043302_71_dialog_content = "Caroline Pirus!",
  ui_story_5004_50043302_72_dialog_content = "Aku akan menyeretmu ke neraka bersamaku, bahkan jika aku harus kehilangan kendali!",
  ui_story_5004_50043302_73_dialog_content = "Serangan kristal liar seperti itu ...",
  ui_story_5004_50043302_74_dialog_content = "Caroline terjebak! Tunggu, meskipun kristal itu melumpuhkannya, dia masih belum turun!",
  ui_story_5004_50043302_75_dialog_content = "Trik ruang tamu! Beri aku lebih banyak kekuatan, tuanku! Izinkan saya untuk menghukum semua orang yang berani menentang Anda!",
  ui_story_5004_50043302_76_dialog_content = "...",
  ui_story_5004_50043302_77_dialog_content = "Saya pikir saya mendapatkannya! Meskipun saya tidak yakin tentang hal itu.",
  ui_story_5004_50043302_78_dialog_content = "Keabadian Caroline terkait dengan Raja!",
  ui_story_5004_50043302_79_dialog_content = "Fokuskan seranganmu pada mereka saat Caroline terjebak!",
  ui_story_5004_50043402_1_dialog_content = "…!",
  ui_story_5004_50043402_2_dialog_content = "Kenapa kamu... Kamu berani...!",
  ui_story_5004_50043402_3_dialog_content = "Anda berani menghancurkan apa yang membutuhkan waktu bertahun-tahun untuk saya capai!",
  ui_story_5004_50043402_4_dialog_content = "Sekarang giliran kita untuk menyerang balik!",
  ui_story_5004_50043402_5_dialog_content = "Anda akan membayar harga menyakiti saya dengan hidup Anda!",
  ui_story_5004_50043402_6_dialog_content = "Ini tidak mungkin... Mustahil bagiku untuk kalah darimu yang lemah!",
  ui_story_5004_50043402_7_dialog_content = "Anda hanyalah potongan-potongan... Tidak mungkin... Saya seorang ahli kristal dari Lumopolis... Saya adalah Ratu di sini!",
  ui_story_5004_50043402_8_dialog_content = "Tuanku! Beri aku lebih banyak kekuatan! Kenapa aku tidak bisa mendengarmu?",
  ui_story_5004_50043402_9_dialog_content = "Aku harus... melanjutkan... Ini belum berakhir! Pesta tehku...!",
  ui_story_5004_50043402_10_dialog_content = "Terkutuklah kalian semua! Bersatu dan kita akan memiliki Aurorian yang lebih lezat! Anda pengkhianat kurang ajar!",
  ui_story_5004_50043402_11_dialog_content = "Aku akan selamanya membuangmu ke...",
  ui_story_5004_50043402_12_dialog_content = "Aku tidak menginginkan omong kosongmu lagi. Pergi!",
  ui_story_5004_50043402_13_dialog_content = "Aku tidak akan membiarkanmu merusak... pesta tehnya... Aghhh!",
  ui_story_5004_50043402_14_dialog_content = "Heh, heh...",
  ui_story_5004_50043402_15_dialog_content = "Apa kali ini kita berhasil?",
  ui_story_5004_50043402_16_dialog_content = "Anda punya banyak kristal pada Anda, Beryl!",
  ui_story_5004_50043402_17_dialog_content = "Tidak apa-apa, Raphael... selama kamu dan semua orang baik-baik saja...",
  ui_story_5004_50043402_18_dialog_content = "Akhirnya... Aku membalaskan dendam keluargaku... dan melindungimu... Hebat...",
  ui_story_5004_50043402_19_dialog_content = "Bangun, Beril! Jangan kau tertidur!",
  ui_story_5004_50043402_20_dialog_content = "Kita harus membawa Beryl kembali ke Lumopolis sekarang, PlayerName!",
  ui_story_5004_50043402_21_dialog_content = "Tapi kita masih belum bisa menemukan Bonacie dan kita tidak tahu jalan keluarnya...",
  ui_story_5004_50043402_22_dialog_content = "Tunggu, tanahnya pecah!",
  ui_story_5004_50043402_23_dialog_content = "Awas!",
  ui_story_5004_50043402_24_dialog_content = "!",
  ui_story_5004_50043402_25_dialog_content = "Di mana kita jatuh saat ini?",
  ui_story_5004_50043402_26_dialog_content = "Aku akan selamanya membuangmu ke...",
  ui_story_5004_50043402_27_dialog_content = "Pesta... pesta teh... tidak akan pernah berakhir...",
  ui_story_5004_50043402_28_dialog_content = "Hee hee..."
}
return config
